        'O que se registra num relógio: instantâneo (corda), com valor (leitura de carga) ou sessão com início e fim (pulso, winder, sol). O identificador é o nome nas funções das fórmulas: HORAS("pulso"; 30). Sessão exclusiva: o relógio fica num lugar só. Mede o gasto: cada leitura desse tipo mede quanto caiu por dia de uso ou guardado (a função MEDIDO das fórmulas). Vale quando: uma fórmula que diz para quais relógios o tipo vale (ex.: corda_manual, só para quem aceita corda); vazia, vale para todos do grupo.' => 'Lo que se registra en un reloj: instantáneo (cuerda), con valor (lectura de carga) o sesión con inicio y fin (muñeca, winder, sol). El identificador es el nombre en las funciones de las fórmulas: HORAS("pulso"; 30). Sesión exclusiva: el reloj está en un solo lugar. Mide el consumo: cada lectura de este tipo mide cuánto bajó por día de uso o guardado (la función MEDIDO de las fórmulas). Vale cuando: una fórmula que dice para qué relojes vale el tipo (ej.: corda_manual, solo para los que aceptan cuerda); vacía, vale para todos los del grupo.',
