        'qualquer data' => 'cualquier fecha',
        'Cada aviso tem uma fórmula da data prevista; entra "em breve" dentro da antecedência e "atrasado" quando a data passa. O "vale quando" (uma fórmula) diz para quais relógios o aviso vale (ex.: corda_manual = 0, só para o automático sem corda); vazio, vale para todos do grupo. O texto é o motivo nas mensagens ({motivo}): "Dar corda: San Martin (a reserva acaba em 3h, 28/09/2026 10:53)"; nele: {relogio}, {data}, {quando} e {limite} (o limite de carga do relógio). O tipo que resolve vira o botão na tela Hoje. Como as fórmulas, pode ter uma versão por ponto da árvore. Na escala inteligente: "no relógio do dia" é conferido no escolhido, do começo ao fim do bloco dele; "sempre", também nos guardados, todo dia. O que vence vira o lembrete do dia, e o lançamento que resolve é simulado com o valor (leitura) ou as horas (sessão) do aviso. Se o aviso vai pelo Telegram e pela agenda é a Configuração, em "O que vai para onde"; aqui fica a data que ele usa na agenda. "Na hora": além do alerta da manhã, o Telegram recebe o aviso no minuto em que ele vence (uma vez, até ele ser resolvido), como o "Tirar do carregador" quando a bateria enche.' => 'Cada aviso tiene una fórmula de la fecha prevista; entra en "pronto" dentro de la antelación y en "atrasado" cuando la fecha pasa. El "vale cuando" (una fórmula) dice para qué relojes vale el aviso (ej.: corda_manual = 0, solo para el automático sin cuerda); vacío, vale para todos los del grupo. El texto es el motivo en los mensajes ({motivo}): "Dar cuerda: San Martin (la reserva se acaba en 3h, 28/09/2026 10:53)"; en él: {relogio}, {data}, {quando} y {limite} (el límite de carga del reloj). El tipo que lo resuelve se vuelve el botón en la pantalla Hoy. Como las fórmulas, puede tener una versión por punto del árbol. En la escala inteligente: "en el reloj del día" se comprueba en el elegido, del inicio al fin de su bloque; "siempre", también en los guardados, todos los días. Lo que vence se vuelve el recordatorio del día, y el registro que lo resuelve se simula con el valor (lectura) o las horas (sesión) del aviso. Si el aviso va por Telegram y a la agenda se define en la Configuración, en "Qué va adónde"; aquí queda la fecha que usa en la agenda. "Al momento": además de la alerta de la mañana, Telegram recibe el aviso en el minuto en que vence (una vez, hasta que se resuelva), como el "Quitar del cargador" cuando la batería se llena.',
