        '— sorteia —' => '— sortea —',
        'Cada modo tem blocos de dias da semana. O sorteio segue os critérios, recalculados a cada dia com o uso dos dias anteriores do plano (a carga não é simulada: não se sabe se você vai carregar). Com o ciclo (opcional), um relógio só volta depois que todos os disponíveis do bloco passaram; dentro do ciclo, a forma de escolha decide a ordem. Um bloco sorteia entre os relógios disponíveis de um ponto da árvore — um relógio para o bloco inteiro na semana, ou um por dia — ou usa um relógio fixo. A forma de escolha vale para o modo; a garantia de rodízio ({1} dias), para todos. Na escala inteligente, o modo monta o período inteiro de uma vez (de 7 dias a 2 anos), simulando as fórmulas dia a dia: escolhe sempre pela maior nota no dia simulado, e o relógio escolhido fica os dias da fórmula dias_seguidos (vazio: 1); os blocos dizem de onde escolher em cada dia da semana (ou o relógio fixo), e o "um por" não conta. A escala é refeita toda manhã a partir do estado real.' => 'Cada modo tiene bloques de días de la semana. El sorteo sigue los criterios, recalculados cada día con el uso de los días anteriores del plan (la carga no se simula: no se sabe si usted va a cargar). Con el ciclo (opcional), un reloj solo vuelve después de que pasaron todos los disponibles del bloque; dentro del ciclo, la forma de elección decide el orden. Un bloque sortea entre los relojes disponibles de un punto del árbol — un reloj para todo el bloque en la semana, o uno por día — o usa un reloj fijo. La forma de elección vale para el modo; la garantía de rotación ({1} días), para todos. En la escala inteligente, el modo arma todo el período de una vez (de 7 días a 2 años), simulando las fórmulas día a día: elige siempre por la nota más alta en el día simulado, y el reloj elegido se queda los días de la fórmula dias_seguidos (vacío: 1); los bloques dicen de dónde elegir en cada día de la semana (o el reloj fijo), y el "uno por" no cuenta. La escala se rehace cada mañana a partir del estado real.',
