        'Registro da última rodada' => 'Registro de la última ronda',
        'Rotina do dia' => 'Rutina del día',
        'Manhã: relógio do dia e avisos' => 'Mañana: reloj del día y avisos',
        'Noite: preparar o de amanhã' => 'Noche: preparar el de mañana',
        'No pulso a partir de' => 'En la muñeca desde',
        'Pôr no pulso sozinho' => 'Poner en la muñeca solo',
        'No pulso até' => 'En la muñeca hasta',
        'Tirar do pulso sozinho' => 'Quitar de la muñeca solo',
        'Sessão no sol esquecida fecha às' => 'Una sesión de sol olvidada se cierra a las',
        'Sem <strong>pôr sozinho</strong>, o relógio do dia só entra no pulso pelo <strong>Pôs no pulso</strong>; sem <strong>tirar sozinho</strong>, só sai pelo ' => 'Sin <strong>poner solo</strong>, el reloj del día solo entra en la muñeca con <strong>Se lo puso</strong>; sin <strong>quitar solo</strong>, solo sale con ',
        '<strong>Tirou do pulso</strong> (esquecido, continua contando como no pulso). O horário de uso vale sempre para o plano e as previsões. Fora do pulso, o relógio conta como guardado.' => '<strong>Se lo quitó</strong> (si se olvida, sigue contando como en la muñeca). El horario de uso vale siempre para el plan y las previsiones. Fuera de la muñeca, el reloj cuenta como guardado.',
        'Limites e contas' => 'Límites y cálculos',
        'Carregar quando a carga chegar a (%)' => 'Cargar cuando la carga llegue a (%)',
        'Solar: pôr no sol quando chegar a (%)' => 'Solar: poner al sol cuando llegue a (%)',
        'Gasto medido: média dos últimos (dias)' => 'Consumo medido: promedio de los últimos (días)',
        'Aviso Encostado: dias sem ir ao pulso' => 'Aviso Arrinconado: días sin ir a la muñeca',
        'O limite de carga de um relógio (no cadastro dele) vale no lugar do geral. Medições do gasto mais velhas que a janela saem da média. ' => 'El límite de carga de un reloj (en su ficha) vale en lugar del general. Las mediciones del consumo más viejas que la ventana salen del promedio. ',
        'Um relógio da coleção que passa do limite de dias sem ir ao pulso ganha o aviso <strong>Encostado</strong> (desliga em Cadastros › Avisos).' => 'Un reloj de la colección que pasa del límite de días sin ir a la muñeca recibe el aviso <strong>Arrinconado</strong> (se desactiva en Definiciones › Avisos).',
        'Telas' => 'Pantallas',
        'Idioma padrão (quem não escolheu outro no menu)' => 'Idioma predeterminado (para quien no eligió otro en el menú)',
        'Abrir o relógio na página Hoje' => 'Abrir el reloj en la página Hoy',
        'Ao lado da lista' => 'Al lado de la lista',
        'Numa janela flutuante, grande' => 'En una ventana flotante, grande',
        'Destaque no alto da página Hoje' => 'Destacado arriba de la página Hoy',
        'O relógio do dia' => 'El reloj del día',
        'O relógio no pulso agora' => 'El reloj en la muñeca ahora',
        'Próximos dias (página Hoje): mostrar até (dias por página)' => 'Próximos días (página Hoy): mostrar hasta (días por página)',
        'Plano: mostrar até (dias por página)' => 'Plan: mostrar hasta (días por página)',
        'Endereço do sistema (a âncora {link})' => 'Dirección del sistema (el marcador {link})',
        '<strong>Ao lado da lista:</strong> o relógio clicado abre num painel à direita, e a lista continua à vista. <strong>Numa janela flutuante:</strong> abre grande, ' => '<strong>Al lado de la lista:</strong> el reloj pulsado se abre en un panel a la derecha, y la lista sigue a la vista. <strong>En una ventana flotante:</strong> se abre grande, ',
        'no meio da tela, com os quadros lado a lado; fecha no ×, no Esc ou num clique fora. No celular, os dois cobrem a tela inteira.' => 'en el medio de la pantalla, con los cuadros lado a lado; se cierra con la ×, con Esc o con un clic afuera. En el celular, los dos cubren la pantalla entera.',
        '<strong>Destaque:</strong> o quadro grande no alto da página Hoje mostra o relógio do dia (o do plano) ou o que está no pulso agora, ' => '<strong>Destacado:</strong> el cuadro grande arriba de la página Hoy muestra el reloj del día (el del plan) o el que está en la muñeca ahora, ',
        'mesmo que seja outro (o do dia aparece embaixo do nome). Sem nenhum relógio no pulso, fica o do dia.' => 'aunque sea otro (el del día aparece debajo del nombre). Sin ningún reloj en la muñeca, queda el del día.',
        '<strong>Mostrar até:</strong> quantos dias os Próximos dias (página Hoje, padrão 7) e o dia a dia da página Plano (padrão 31) mostram de cada vez. ' => '<strong>Mostrar hasta:</strong> cuántos días muestran a la vez los Próximos días (página Hoy, predeterminado 7) y el día a día de la página Plan (predeterminado 31). ',
        'Passando disso, embaixo aparecem as páginas: &lt; (anterior), os números e &gt; (próxima).' => 'Pasado eso, abajo aparecen las páginas: &lt; (anterior), los números y &gt; (siguiente).',
        'Cron' => 'Cron',
        'Sorteios' => 'Sorteos',
        'Os números vêm de' => 'Los números vienen de',
        '1. RANDOM.ORG (ruído atmosférico) · 2. fora do ar, ANU QRNG (quântico) · 3. sem os dois, o gerador seguro do PHP' => '1. RANDOM.ORG (ruido atmosférico) · 2. si está caído, ANU QRNG (cuántico) · 3. sin los dos, el generador seguro de PHP',
        'Último lote' => 'Último lote',
        'nenhum ainda' => 'ninguno todavía',
        'Serviços fora' => 'Servicios caídos',
        'os dois sem responder desde {1} {2}; o sistema tenta de novo depois de 10 minutos' => 'los dos sin responder desde {1} {2}; el sistema vuelve a intentar después de 10 minutos',
        'Todo sorteio do sistema (o rodízio totalmente aleatório, o sorteio pela nota e o desempate de notas iguais na escala) usa estes números. Eles chegam num lote, e cada sorteio usa só o que precisa, sem viés.' => 'Todo sorteo del sistema (la rotación totalmente aleatoria, el sorteo por la nota y el desempate de notas iguales en la escala) usa estos números. Llegan en un lote, y cada sorteo usa solo lo que necesita, sin sesgo.',
        'Telegram (API de alerta)' => 'Telegram (API de alertas)',
        'Enviar alertas' => 'Enviar alertas',
        'O endereço e o destinatário ficam no config.php. O texto de cada aviso vem da mensagem padrão do Telegram ou da personalizada dele, em "O que vai para onde".' => 'La dirección y el destinatario están en el config.php. El texto de cada aviso viene del mensaje predeterminado de Telegram o del personalizado de ese aviso, en "Qué va adónde".',
        'Google Agenda' => 'Google Calendar',
        'Criar eventos na agenda' => 'Crear eventos en la agenda',
        'Antecedência dos eventos (dias)' => 'Antelación de los eventos (días)',
        'ID da agenda' => 'ID de la agenda',
        'xxxx@group.calendar.google.com' => 'xxxx@group.calendar.google.com',
        'Caminho da chave JSON no servidor' => 'Ruta de la clave JSON en el servidor',
        'Chave encontrada. Compartilhe a agenda com {1}, com permissão para fazer alterações nos eventos.' => 'Clave encontrada. Comparta la agenda con {1}, con permiso para hacer cambios en los eventos.',
        'Nenhuma chave válida nesse caminho. Confira o nome do arquivo e se o usuário do PHP-FPM (www-data) tem permissão de leitura.' => 'Ninguna clave válida en esa ruta. Revise el nombre del archivo y si el usuario de PHP-FPM (www-data) tiene permiso de lectura.',
        'O teste cria um evento daqui a 10 minutos, no formato dos modelos. Salve antes de testar.' => 'La prueba crea un evento dentro de 10 minutos, en el formato de las plantillas. Guarde antes de probar.',
        'Criar evento de teste' => 'Crear evento de prueba',
        'Remover evento de teste' => 'Quitar evento de prueba',
        'Inserir âncora na mensagem padrão do {1}' => 'Insertar marcador en el mensaje predeterminado de {1}',
        'Mensagem padrão' => 'Mensaje predeterminado',
        'Todo aviso usa a mensagem padrão do canal, a não ser que tenha a sua personalizada, marcada em "O que vai para onde". As âncoras entre chaves, como {relogio}, viram os valores na hora de enviar; "Inserir âncora" põe uma onde está o cursor.' => 'Todo aviso usa el mensaje predeterminado del canal, a menos que tenga el suyo personalizado, marcado en "Qué va adónde". Los marcadores entre llaves, como {relogio}, se vuelven los valores al enviar; "Insertar marcador" pone uno donde está el cursor.',
        'O que cada âncora vira' => 'En qué se convierte cada marcador',
        'Excluir o evento {1}?' => '¿Eliminar el evento {1}?',
        '{1} no {2}' => '{1} en {2}',
        '{1}, personalizado no {2}' => '{1}, personalizado en {2}',
        'Vazio usa a mensagem padrão do {1}' => 'Vacío usa el mensaje predeterminado de {1}',
        'O que vai para onde' => 'Qué va adónde',
        'Marque "Personalizar" num canal para aquele aviso ter uma mensagem só dele, no lugar da mensagem padrão do canal. Cada canal tem a sua.' => 'Marque "Personalizar" en un canal para que ese aviso tenga un mensaje solo suyo, en lugar del mensaje predeterminado del canal. Cada canal tiene el suyo.',
        'Quando' => 'Cuándo',
        'Personalizar' => 'Personalizar',
        'As mudanças desta página valem depois de salvar.' => 'Los cambios de esta página valen después de guardar.',
        'Salvar configuração' => 'Guardar configuración',
        'Conferir a carga dos smartwatches' => 'Revisar la carga de los smartwatches',
        'Relógio (opcional: com relógio, as âncoras dele funcionam) {1}' => 'Reloj (opcional: con reloj, sus marcadores funcionan) {1}',
        'Nenhum, é um evento geral' => 'Ninguno, es un evento general',
        ' (indisponível)' => ' (no disponible)',
        'Quando dispara {1}' => 'Cuándo se dispara {1}',
        'Data' => 'Fecha',
        'A partir de' => 'A partir de',
        'Hora {1}' => 'Hora {1}',
        'Dia do mês {1}' => 'Día del mes {1}',
        'A cada quantos dias {1}' => 'Cada cuántos días {1}',
        'Dias da semana' => 'Días de la semana',
        ' Ativo' => ' Activo',
        'Próximas vezes: {1}.' => 'Próximas veces: {1}.',
        'nenhuma nos próximos 60 dias' => 'ninguna en los próximos 60 días',
        'Depois de salvar, o evento aparece na tabela "O que vai para onde", onde se escolhem os canais e o texto de cada um. Evento novo já vem marcado para o Telegram.' => 'Después de guardar, el evento aparece en la tabla "Qué va adónde", donde se eligen los canales y el texto de cada uno. Un evento nuevo ya viene marcado para Telegram.',
        'Salvar alterações' => 'Guardar cambios',
        'Criar evento' => 'Crear evento',
        'Eventos personalizados' => 'Eventos personalizados',
        'Um aviso seu, com horário e repetição próprios: todo dia, em dias da semana, todo mês, a cada N dias ou uma vez só. Os eventos já criados estão na tabela acima (editar e excluir ficam no nome deles).' => 'Un aviso suyo, con horario y repetición propios: todos los días, en días de la semana, todos los meses, cada N días o una sola vez. Los eventos ya creados están en la tabla de arriba (editar y eliminar están en su nombre).',
        'Editar o evento {1}' => 'Editar el evento {1}',
        'Novo evento' => 'Nuevo evento',
        'Como sai hoje' => 'Cómo sale hoy',
        'Telegram de manhã' => 'Telegram de la mañana',
        '(nada a enviar)' => '(nada que enviar)',
        'Enviar agora' => 'Enviar ahora',
        'Telegram à noite' => 'Telegram de la noche',
        '(nada a enviar: amanhã continua o mesmo relógio)' => '(nada que enviar: mañana sigue el mismo reloj)',
        'Agenda' => 'Agenda',
        'Nada previsto no período.' => 'Nada previsto en el período.',
        '{1} eventos criados pelo sistema estão na agenda. Mudou um modelo? Sincronize: os eventos já criados são atualizados.' => '{1} eventos creados por el sistema están en la agenda. ¿Cambió una plantilla? Sincronice: los eventos ya creados se actualizan.',
        'Sincronizar agora' => 'Sincronizar ahora',
        'Cópia de segurança' => 'Copia de seguridad',
        'Uma cópia do banco inteiro por dia, na rodada da noite, guardando as {1} mais novas, {2} o conteúdo dos documentos (os arquivos já ficam na pasta deles). A cópia volta em qualquer um dos três bancos, na mesma versão do sistema. {3}' => 'Una copia de toda la base de datos por día, en la ronda de la noche, guardando las {1} más nuevas, {2} el contenido de los documentos (los archivos ya quedan en su carpeta). La copia se restaura en cualquiera de las tres bases de datos, en la misma versión del sistema. {3}',
        'Última: {1} {2}.' => 'Última: {1} {2}.',
        'Nenhuma feita ainda.' => 'Ninguna hecha todavía.',
        'A cópia automática está desligada: {1}. Ponha no config.php a BACKUP_PASTA, uma pasta do servidor fora da pasta publicada.' => 'La copia automática está desactivada: {1}. Ponga en el config.php la BACKUP_PASTA, una carpeta del servidor fuera de la carpeta publicada.',
        'Cópia' => 'Copia',
        'Feita em' => 'Hecha el',
        'Tamanho' => 'Tamaño',
        'Baixar' => 'Descargar',
        'Voltar o banco para a cópia de {1}? Tudo o que foi feito depois some. Antes, o sistema guarda uma cópia do que está agora.' => '¿Volver la base de datos a la copia de {1}? Todo lo que se hizo después desaparece. Antes, el sistema guarda una copia de cómo está ahora.',
        'Restaurar' => 'Restaurar',
        'Fazer uma cópia agora' => 'Hacer una copia ahora',
        'Não consegui ler a configuração: {1}' => 'No pude leer la configuración: {1}',
        'Configuração' => 'Configuración',
        'Inteligente' => 'Inteligente',
        'vai o relógio com a maior nota nos critérios' => 'va el reloj con la nota más alta en los criterios',
        'Inteligente com sorteio' => 'Inteligente con sorteo',
        'sorteio em que a nota de cada relógio é a chance dele: variedade sem perder o critério' => 'sorteo en el que la nota de cada reloj es su probabilidad: variedad sin perder el criterio',
        'todos com a mesma chance, sem olhar os critérios (os números do RANDOM.ORG; fora do ar, do ANU QRNG; sem os dois, do gerador seguro do PHP)' => 'todos con la misma probabilidad, sin mirar los criterios (los números de RANDOM.ORG; si está caído, de ANU QRNG; sin los dos, del generador seguro de PHP)',
        'Fila (FIFO)' => 'Fila (FIFO)',
        'vai o que está há mais tempo sem uso: todos passam pelo pulso em rodízio' => 'va el que lleva más tiempo sin uso: todos pasan por la muñeca en rotación',
        'Critérios de escolha do relógio' => 'Criterios de elección del reloj',
        'Não foi salvo:' => 'No se guardó:',
        'Como a nota funciona' => 'Cómo funciona la nota',
        'Cada {1} — todos os relógios, um grupo em qualquer nível da árvore, ou um relógio — pode ter o seu {2}. O relógio usa o conjunto {3}, inteiro: o dele; senão o do grupo dele; senão o do grupo de cima; e assim até o de todos os relógios. Um lugar sem conjunto próprio herda o de cima.' => 'Cada {1} — todos los relojes, un grupo en cualquier nivel del árbol, o un reloj — puede tener su propio {2}. El reloj usa el conjunto {3}, entero: el suyo; si no, el de su grupo; si no, el del grupo de arriba; y así hasta el de todos los relojes. Un lugar sin conjunto propio hereda el de arriba.',
        'conjunto de critérios' => 'conjunto de criterios',
        'mais perto dele' => 'más cercano a él',
        'Num conjunto, cada {1} tem um peso, e a soma fecha 100%. Cada parâmetro tem {2}, com peso dentro dele, que também fecha 100%. Cada subparâmetro mede uma coisa do relógio e usa {3} para transformar o valor medido numa nota de 0 a 100. {4} = peso do subparâmetro × peso do parâmetro; {5} = soma de nota × peso efetivo. Subparâmetro sem medida para o relógio (autonomia num relógio que não é smartwatch, por exemplo) sai da conta, e os pesos dos que ficam são reescalados.' => 'En un conjunto, cada {1} tiene un peso, y la suma da 100%. Cada parámetro tiene {2}, con peso dentro de él, que también suman 100%. Cada subparámetro mide una cosa del reloj y usa {3} para transformar el valor medido en una nota de 0 a 100. {4} = peso del subparámetro × peso del parámetro; {5} = suma de nota × peso efectivo. Un subparámetro sin medida para el reloj (autonomía en un reloj que no es smartwatch, por ejemplo) sale de la cuenta, y los pesos de los que quedan se reescalan.',
        'parâmetro' => 'parámetro',
        'subparâmetros' => 'subparámetros',
        'Peso efetivo' => 'Peso efectivo',
        'nota final' => 'nota final',
        'Como a nota vira escolha' => 'Cómo la nota se convierte en elección',
        'Cada modo de rodízio tem a sua forma de escolher o relógio, escolhida no quadro {1}, na página Hoje:' => 'Cada modo de rotación tiene su forma de elegir el reloj, elegida en el cuadro {1}, en la página Hoy:',
