        'Garantia de rodízio: {1} (no mesmo quadro). Fora da nota também valem o grupo de cada bloco de dias, os relógios fixos e não repetir o de ontem.' => 'Garantía de rotación: {1} (en el mismo cuadro). Fuera de la nota también valen el grupo de cada bloque de días, los relojes fijos y no repetir el de ayer.',
