        '{1} A linha em branco serve para incluir uma faixa; o "+ faixa" cria mais.' => '{1} La línea en blanco sirve para agregar un rango; el "+ rango" crea más.',
        'Uma nota por categoria; categoria sem faixa: o subparâmetro não se aplica ao relógio daquela categoria.' => 'Una nota por categoría; categoría sin rango: el subparámetro no se aplica al reloj de esa categoría.',
        'Nota de 0 a 100. "De" entra na faixa, "até" não (a última inclui o seu "até"); "até" vazio = sem limite. A primeira começa em 0; cada uma começa onde a anterior terminou; a última vai até {1}.' => 'Nota de 0 a 100. "Desde" entra en el rango, "hasta" no (el último incluye su "hasta"); "hasta" vacío = sin límite. El primero empieza en 0; cada uno empieza donde terminó el anterior; el último va hasta {1}.',
        '"sem limite" (até vazio)' => '"sin límite" (hasta vacío)',
