        '{1} {2} com esses filtros{3}. Os trechos são contínuos: em uso (rodízio), fora do rodízio, em cada tipo de sessão (no winder, no sol...) e em repouso; as marcações (corda, carga, pilha, revisão) não têm fim nem duração.' => '{1} {2} con estos filtros{3}. Los tramos son continuos: en uso (rotación), fuera de la rotación, en cada tipo de sesión (en el winder, al sol...) y en reposo; las marcas (cuerda, carga, pila, revisión) no tienen fin ni duración.',
