        'Domingo' => 'Domingo',
        'Vai o relógio com a maior nota nos critérios. Previsível: com os mesmos dados, a mesma escolha.' => 'Va el reloj con la nota más alta en los criterios. Previsible: con los mismos datos, la misma elección.',
        'Sorteio em que a nota de cada relógio é a chance dele: quem tem nota maior sai mais vezes, mas todos têm chance. Variedade sem perder o critério.' => 'Sorteo en el que la nota de cada reloj es su probabilidad: el de nota más alta sale más veces, pero todos tienen opción. Variedad sin perder el criterio.',
        'Todos os relógios do tipo têm a mesma chance, sem olhar os critérios. Os números vêm do RANDOM.ORG (ruído atmosférico); fora do ar, do ANU QRNG (quântico); sem os dois, do gerador seguro do PHP.' => 'Todos los relojes del tipo tienen la misma probabilidad, sin mirar los criterios. Los números vienen de RANDOM.ORG (ruido atmosférico); si no está disponible, de ANU QRNG (cuántico); sin ambos, del generador seguro de PHP.',
        'Vai o que está há mais tempo sem uso: todos passam pelo pulso, em fila. Não olha os critérios, e já garante o rodízio por natureza.' => 'Va el que lleva más tiempo sin uso: todos pasan por la muñeca, en fila. No mira los criterios y ya garantiza la rotación por naturaleza.',
        'Dia' => 'Día',
        'Lembrete' => 'Recordatorio',
        'Neste modo o sorteio é feito dia a dia.' => 'En este modo el sorteo se hace día a día.',
        'Página {1} de {2} · {3} dias no plano, {4} por página (o "Mostrar até" da {5}).' => 'Página {1} de {2} · {3} días en el plan, {4} por página (el "Mostrar hasta" de {5}).',
        'Não consegui ler os próximos dias: {1}' => 'No pude leer los próximos días: {1}',
        'sem modo' => 'sin modo',
        'no pulso agora' => 'en la muñeca ahora',
        'Relógio do dia: {1} ({2})' => 'Reloj del día: {1} ({2})',
        'Hoje não tem relógio do dia.' => 'Hoy no hay reloj del día.',
        'Por que ele: ' => 'Por qué él: ',
        'Hoje sem relógio? O dia fica livre: o {1} sai do rodízio de hoje (se já está no pulso pelo rodízio, sai agora; o tempo que ficou conta). Os outros dias não mudam.' => '¿Hoy sin reloj? El día queda libre: {1} sale de la rotación de hoy (si ya está en la muñeca por la rotación, sale ahora; el tiempo que estuvo cuenta). Los demás días no cambian.',
        'Sem relógio hoje' => 'Sin reloj hoy',
        'Hoje sem relógio' => 'Hoy sin reloj',
        'dia livre' => 'día libre',
        'Nenhum relógio vai ao pulso pelo rodízio hoje. Quer usar um? Escolha abaixo, ou sorteie de novo (inclusive hoje) no quadro do modo de rodízio.' => 'Ningún reloj va a la muñeca por la rotación hoy. ¿Quiere usar uno? Elija abajo, o sortee de nuevo (incluido hoy) en el cuadro del modo de rotación.',
        'Nenhum relógio para hoje' => 'Ningún reloj para hoy',
        'Nenhum relógio disponível no grupo deste dia. Mude o grupo no modo de rodízio ou marque um relógio como disponível.' => 'Ningún reloj disponible en el grupo de este día. Cambie el grupo en el modo de rotación o marque un reloj como disponible.',
