        'ver o plano inteiro →' => 'ver el plan completo →',
        'Sortear entre' => 'Sortear entre',
        ' (indisponível: o dia sorteia outro do mesmo grupo)' => ' (no disponible: el día sortea otro del mismo grupo)',
        'Modo de rodízio {1}' => 'Modo de rotación {1}',
        'Rodízio manual' => 'Rotación manual',
        'Você escolhe o relógio de cada dia de um período. Ponha o começo e o fim e clique em OK: os dias aparecem de 7 em 7, cada um com a lista dos relógios, "Decida por mim" (o sistema escolhe) e "Sem relógio (dia livre)". Fora do período, continua valendo o modo de rodízio de sempre ({1}).' => 'Usted elige el reloj de cada día de un período. Ponga el inicio y el fin y haga clic en OK: los días aparecen de 7 en 7, cada uno con la lista de relojes, "Decide por mí" (el sistema elige) y "Sin reloj (día libre)". Fuera del período, sigue valiendo el modo de rotación de siempre ({1}).',
        'nenhum' => 'ninguno',
        'Monta o plano do período inteiro de uma vez, simulando a carga de cada relógio dia a dia, com os lembretes de carregar, dar corda e pôr no sol. É refeita toda manhã a partir do estado real.' => 'Arma el plan de todo el período de una vez, simulando la carga de cada reloj día a día, con los recordatorios de cargar, dar cuerda y poner al sol. Se rehace cada mañana a partir del estado real.',
        'Cada bloco de dias sorteia entre os relógios do grupo escolhido, ou usa o relógio fixo; marcando "sortear um por dia", cada dia do bloco tem o seu sorteio. O plano vem montado até domingo; a semana seguinte é sorteada quando começa.' => 'Cada bloque de días sortea entre los relojes del grupo elegido, o usa el reloj fijo; marcando "sortear uno por día", cada día del bloque tiene su sorteo. El plan se arma hasta el domingo; la semana siguiente se sortea cuando empieza.',
        'Período {1}' => 'Período {1}',
        'Uma semana' => 'Una semana',
        'Um mês' => 'Un mes',
        'Dois meses' => 'Dos meses',
        'Meio ano' => 'Medio año',
