        'Como escolher o relógio {1}' => 'Cómo elegir el reloj {1}',
        'Como escolher o relógio: {1}' => 'Cómo elegir el reloj: {1}',
        'pela maior nota' => 'por la nota más alta',
        'A escala escolhe sempre pela maior nota nos critérios, com as medidas de cada dia simulado.' => 'La escala elige siempre por la nota más alta en los criterios, con las medidas de cada día simulado.',
        'Garantia de rodízio: dias sem uso, no máximo {1}' => 'Garantía de rotación: días sin uso, como máximo {1}',
        'Quem passa do limite tem prioridade, o mais tempo parado primeiro. 0 desliga. O mesmo valor vale para todos os modos que usam a nota.' => 'Quien pasa del límite tiene prioridad, el que lleva más tiempo parado primero. 0 lo desactiva. El mismo valor vale para todos los modos que usan la nota.',
        'A nota vem dos {1}, que você cadastra.' => 'La nota viene de los {1}, que usted define.',
        'Trocar o modo refaz o plano a partir de amanhã; hoje continua o {1}. Continuar?' => 'Cambiar el modo rehace el plan a partir de mañana; hoy sigue {1}. ¿Continuar?',
        'Trocar o modo apaga o plano atual. Continuar?' => 'Cambiar el modo borra el plan actual. ¿Continuar?',
        'Aplicar modo' => 'Aplicar modo',
        'Trocar o modo apaga o plano atual e gera outro{1}. O histórico de uso, corda, sol e carga continua. Os modos e os blocos de dias se cadastram em {2}.' => 'Cambiar el modo borra el plan actual y genera otro{1}. El historial de uso, cuerda, sol y carga se mantiene. Los modos y los bloques de días se definen en {2}.',
        ' a partir de amanhã: hoje continua o {1}, que já está no pulso (para trocar hoje, use "Usando hoje")' => ' a partir de mañana: hoy sigue {1}, que ya está en la muñeca (para cambiar hoy, use "Usando hoy")',
        ' a partir de hoje' => ' a partir de hoy',
