        'verdadeiro ou falso: o dia já começou no pulso (há relógio do dia e: pondo no pulso sozinho, passou do uso_inicio; senão, ele já foi posto no pulso hoje)' => 'verdadero o falso: el día ya empezó en la muñeca (hay reloj del día y: poniéndolo en la muñeca solo, pasó de uso_inicio; si no, ya se puso en la muñeca hoy)',
