        'o que o relógio do destaque é: dia (o relógio do dia, no pulso ou não) ou pulso (outro relógio, no pulso agora; o do dia fica no dia)' => 'lo que es el reloj del destacado: dia (el reloj del día, en la muñeca o no) o pulso (otro reloj, en la muñeca ahora; el del día se queda en dia)',
        'o que a Configuração pede: dia (o relógio do dia) ou pulso (o relógio no pulso agora)' => 'lo que pide la Configuración: dia (el reloj del día) o pulso (el reloj en la muñeca ahora)',
        'verdadeiro: o relógio do destaque está no pulso agora (havendo mais de um no pulso, conta o que foi por último)' => 'verdadero: el reloj del destacado está en la muñeca ahora (si hay más de uno en la muñeca, cuenta el que fue el último)',
        'o relógio do destaque; null: nenhum (sem relógio do dia e ninguém no pulso). No pulso: o que está no pulso agora (havendo mais de um, o que foi ao pulso por último); ninguém no pulso, o relógio do dia' => 'el reloj del destacado; null: ninguno (sin reloj del día y nadie en la muñeca). En la muñeca: el que está en la muñeca ahora (si hay más de uno, el que fue a la muñeca el último); nadie en la muñeca, el reloj del día',
        'numa frase, por que é ele: O relógio do dia. / O relógio do dia, no pulso agora. / No pulso agora; o relógio do dia é outro. / No pulso agora; hoje não tem relógio do dia. / Nenhum relógio no pulso agora: aqui, o relógio do dia. / Nenhum relógio para hoje e nenhum no pulso.' => 'en una frase, por qué es él: El reloj del día. / El reloj del día, en la muñeca ahora. / En la muñeca ahora; el reloj del día es otro. / En la muñeca ahora; hoy no hay reloj del día. / Ningún reloj en la muñeca ahora: aquí, el reloj del día. / Ningún reloj para hoy y ninguno en la muñeca.',
