        'o estado como a tabela mostra: "Em uso", o nome da sessão aberta ("No sol", "No carregador"; duas juntas: "No sol · No winder"), "Em repouso", "Indisponível" ou "Emprestado" (o emprestado parado)' => 'el estado como lo muestra la tabla: "En uso", el nombre de la sesión abierta ("Al sol", "En el cargador"; dos juntas: "Al sol · En el winder"), "En reposo", "No disponible" o "Prestado" (el prestado parado)',
