        'a cópia no banco pelo config.php (DOCUMENTOS_COPIA_BANCO), que vale sobre o relógio e o arquivo: verdadeiro, todo arquivo vai; falso, nenhum vai; null (sem a constante), cada relógio decide (a caixa do cadastro só aparece então)' => 'la copia en la base de datos por el config.php (DOCUMENTOS_COPIA_BANCO), que vale sobre el reloj y el archivo: verdadero, todo archivo va; falso, ninguno va; null (sin la constante), cada reloj decide (la casilla de la ficha solo aparece entonces)',
