        'a condição que toda linha tem de cumprir, como o banco escreve' => 'la condición que toda fila tiene que cumplir, como la escribe la base de datos',
        'as listas do código que a reescrita precisa ter iguais' => 'las listas del código que la reescritura tiene que tener iguales',
        'as funções do motor das fórmulas' => 'las funciones del motor de las fórmulas',
        'o nome da função' => 'el nombre de la función',
        'quantos argumentos ela aceita ("2", "1 a 2", "3 ou mais")' => 'cuántos argumentos acepta ("2", "1 a 2", "3 o más")',
        'o que ela devolve' => 'lo que devuelve',
        'verdadeiro: lê os lançamentos do relógio (o primeiro argumento é um tipo de lançamento, entre aspas)' => 'verdadero: lee los registros del reloj (el primer argumento es un tipo de registro, entre comillas)',
        'os tipos de campo do cadastro' => 'los tipos de campo de la ficha',
        'o tipo (inteiro, decimal, sim_nao, data, lista, texto)' => 'el tipo (inteiro, decimal, sim_nao, data, lista, texto)',
        'o que ele é, e como entra nas contas' => 'qué es, y cómo entra en las cuentas',
        'os formatos dos tipos de lançamento' => 'los formatos de los tipos de registro',
        'o que ele é' => 'qué es',
        'as repetições dos eventos personalizados' => 'las repeticiones de los eventos personalizados',
        'a repetição (uma, diaria, semanal, mensal, intervalo)' => 'la repetición (uma, diaria, semanal, mensal, intervalo)',
        'como ela aparece na tela' => 'cómo aparece en la pantalla',
        'os dias da semana como o sistema numera' => 'los días de la semana como los numera el sistema',
        'o número (1 segunda a 7 domingo)' => 'el número (1 lunes a 7 domingo)',
        'as âncoras das mensagens (entre chaves no texto)' => 'los marcadores de los mensajes (entre llaves en el texto)',
        'a âncora, sem as chaves' => 'el marcador, sin las llaves',
        'o que ela vira' => 'en qué se convierte',
        'os canais das mensagens' => 'los canales de los mensajes',
        'o código do canal (tg: Telegram, ag: Google Agenda)' => 'el código del canal (tg: Telegram, ag: Google Calendar)',
        'como a mensagem sai nele' => 'cómo sale el mensaje en él',
        'as migrações, na ordem' => 'las migraciones, en orden',
        'o arquivo do SQL dela' => 'el archivo del SQL de ella',
        'o que ela traz' => 'lo que trae',
        'verdadeiro: ela tem também um passo em programa, depois do SQL' => 'verdadero: también tiene un paso en programa, después del SQL',
        'as constantes do config.php' => 'las constantes del config.php',
        'o nome (ou os nomes) da constante' => 'el nombre (o los nombres) de la constante',
        'para que ela serve' => 'para qué sirve',
        'falso: a cópia de segurança está desligada no config.php (BACKUP_ATIVO = false): o cron não faz cópia, a escrita fazer é recusada e a Configuração não mostra o quadro Cópia de segurança' => 'falso: la copia de seguridad está desactivada en el config.php (BACKUP_ATIVO = false): el cron no hace copia, la escritura fazer se rechaza y la Configuración no muestra el cuadro Copia de seguridad',
        'verdadeiro: a pasta das cópias (BACKUP_PASTA do config.php) existe, aceita gravar e fica fora da pasta publicada' => 'verdadero: la carpeta de las copias (BACKUP_PASTA del config.php) existe, acepta escribir y queda fuera de la carpeta publicada',
        'por que a pasta não serve (sem BACKUP_PASTA, não existe, sem permissão de escrita, ou dentro da pasta publicada); null: serve' => 'por qué la carpeta no sirve (sin BACKUP_PASTA, no existe, sin permiso de escritura, o dentro de la carpeta publicada); null: sirve',
        'quantas cópias ficam na pasta (BACKUP_MANTER; padrão 7): a cada cópia nova, as mais velhas que passam disso saem' => 'cuántas copias quedan en la carpeta (BACKUP_MANTER; por defecto 7): con cada copia nueva, las más antiguas que pasan de eso salen',
        'verdadeiro: as cópias levam o conteúdo dos documentos guardado no banco (BACKUP_DOCUMENTOS); falso: não levam (os arquivos já estão na pasta dos documentos)' => 'verdadero: las copias llevan el contenido de los documentos guardado en la base de datos (BACKUP_DOCUMENTOS); falso: no lo llevan (los archivos ya están en la carpeta de los documentos)',
        'a versão do banco agora (a última migração): só uma cópia da mesma versão volta' => 'la versión de la base de datos ahora (la última migración): solo vuelve una copia de la misma versión',
        'quando foi feita a última cópia (texto AAAA-MM-DD HH:MM:SS); null: nenhuma' => 'cuándo se hizo la última copia (texto AAAA-MM-DD HH:MM:SS); null: ninguna',
        'as cópias que estão na pasta, da mais nova para a mais velha' => 'las copias que están en la carpeta, de la más nueva a la más antigua',
        'o nome do arquivo (relojoeiro-AAAA-MM-DD-HHMMSS.jsonl.gz): é o que se passa em arquivo= para baixar ou restaurar' => 'el nombre del archivo (relojoeiro-AAAA-MM-DD-HHMMSS.jsonl.gz): es lo que se pasa en arquivo= para descargar o restaurar',
        'o tamanho por extenso ("7 KB", "1,2 MB")' => 'el tamaño por extenso ("7 KB", "1,2 MB")',
        'quando a cópia foi feita (texto AAAA-MM-DD HH:MM:SS)' => 'cuándo se hizo la copia (texto AAAA-MM-DD HH:MM:SS)',
        'verdadeiro: a cópia leva o conteúdo dos documentos' => 'verdadero: la copia lleva el contenido de los documentos',
        'a versão do banco da cópia (a última migração dele)' => 'la versión de la base de datos de la copia (su última migración)',
        'as camadas do sistema, na ordem' => 'las capas del sistema, en orden',
        'cada arquivo do sistema (os do repositório), pela camada' => 'cada archivo del sistema (los del repositorio), por la capa',
        'o conteúdo do arquivo, como está (texto); só com arquivo= ou conteudo=1' => 'el contenido del archivo, como está (texto); solo con arquivo= o conteudo=1',
        'o conteúdo da imagem, em base64; só com arquivo= ou conteudo=1' => 'el contenido de la imagen, en base64; solo con arquivo= o conteudo=1',
        'só nas páginas, com arquivo= ou conteudo=1: o HTML que o navegador recebe, já montado (o topo com o menu, o esqueleto da página e os scripts)' => 'solo en las páginas, con arquivo= o conteudo=1: el HTML que recibe el navegador, ya montado (la cabecera con el menú, el esqueleto de la página y los scripts)',
        'o que fica de fora de propósito, e o que ver no lugar' => 'lo que queda fuera a propósito, y qué ver en su lugar',
        'o que é (o config.php, a chave do Google, o banco, a pasta dos documentos, as senhas)' => 'qué es (el config.php, la clave de Google, la base de datos, la carpeta de los documentos, las contraseñas)',
        'com arquivo=: o nome do arquivo, com a pasta (estilo.css, testes/cenario.php, docs/telas/hoje.png): é o que se passa em arquivo=' => 'con arquivo=: el nombre del archivo, con la carpeta (estilo.css, testes/cenario.php, docs/telas/hoje.png): es lo que se pasa en arquivo=',
        'com arquivo=: a camada (tela, api, linha_de_comando, banco, servidor, testes, documentacao, repositorio, imagem; veja camadas)' => 'con arquivo=: la capa (tela, api, linha_de_comando, banco, servidor, testes, documentacao, repositorio, imagem; vea camadas)',
        'com arquivo=: o que o arquivo é e o que ele faz' => 'con arquivo=: qué es el archivo y qué hace',
        'com arquivo=: php, javascript, css, sql, markdown, apache, nginx, texto ou png' => 'con arquivo=: php, javascript, css, sql, markdown, apache, nginx, texto o png',
        'com arquivo=: o tamanho, em bytes' => 'con arquivo=: el tamaño, en bytes',
        'com arquivo=: quantas linhas (null na imagem)' => 'con arquivo=: cuántas líneas (null en la imagen)',
        'com arquivo=: o SHA-256 do arquivo: para conferir a cópia, ou saber se mudou desde a última leitura' => 'con arquivo=: el SHA-256 del archivo: para comprobar la copia, o saber si cambió desde la última lectura',
        'com arquivo=: a data da última alteração do arquivo no servidor (AAAA-MM-DD HH:MM:SS)' => 'con arquivo=: la fecha de la última modificación del archivo en el servidor (AAAA-MM-DD HH:MM:SS)',
        'com arquivo=: o endereço deste arquivo na API, com o conteúdo, em JSON' => 'con arquivo=: la dirección de este archivo en la API, con el contenido, en JSON',
        'com arquivo=: o endereço do arquivo puro, sem JSON (texto como text/plain; imagem como imagem)' => 'con arquivo=: la dirección del archivo puro, sin JSON (texto como text/plain; imagen como imagen)',
        'com arquivo=: só nas páginas: os arquivos que ela usa, na ordem (o pagina.php, o estilo.css, a própria página e os scripts que ela carrega)' => 'con arquivo=: solo en las páginas: los archivos que usa, en orden (el pagina.php, el estilo.css, la propia página y los scripts que carga)',
        'com arquivo=: só nas páginas: o endereço do HTML que o navegador recebe, puro' => 'con arquivo=: solo en las páginas: la dirección del HTML que recibe el navegador, puro',
        'com arquivo=: o conteúdo do arquivo, como está (texto); só com arquivo= ou conteudo=1' => 'con arquivo=: el contenido del archivo, como está (texto); solo con arquivo= o conteudo=1',
        'com arquivo=: o conteúdo da imagem, em base64; só com arquivo= ou conteudo=1' => 'con arquivo=: el contenido de la imagen, en base64; solo con arquivo= o conteudo=1',
        'com arquivo=: só nas páginas, com arquivo= ou conteudo=1: o HTML que o navegador recebe, já montado (o topo com o menu, o esqueleto da página e os scripts)' => 'con arquivo=: solo en las páginas, con arquivo= o conteudo=1: el HTML que recibe el navegador, ya montado (la cabecera con el menú, el esqueleto de la página y los scripts)',
        'aparece quando a consulta usa filtros (incluir, excluir, f, busca, ordem, limite, pagina, mostrar)' => 'aparece cuando la consulta usa filtros (incluir, excluir, f, busca, ordem, limite, pagina, mostrar)',
        'o que foi pedido e não existe (caminho sem lista, parte que não existe)' => 'lo que se pidió y no existe (camino sin lista, parte que no existe)',
        'quantos itens a lista tinha' => 'cuántos elementos tenía la lista',
        'quantos vieram (a página)' => 'cuántos vinieron (la página)',
        'o limite por página; null: sem' => 'el límite por página; null: sin',
        'quantos passaram nos filtros' => 'cuántos pasaron los filtros',
        'o recurso (vazio: tudo)' => 'el recurso (vacío: todo)',
        'a ação (escrita)' => 'la acción (escritura)',
        'json (padrão) ou xml' => 'json (por defecto) o xml',
        'o token da API; também no cabeçalho X-Api-Token, ou o login do site (HTTP Basic) no lugar dele' => 'el token de la API; también en la cabecera X-Api-Token, o el inicio de sesión del sitio (HTTP Basic) en su lugar',
        'pedido recusado: uma escrita que não passou nas validações ({ok: false, mensagem, erros: [...]}, um erro por motivo) ou uma fórmula mal escrita no recurso=calcular ({erro, erros})' => 'petición rechazada: una escritura que no pasó las validaciones ({ok: false, mensagem, erros: [...]}, un error por motivo) o una fórmula mal escrita en recurso=calcular ({erro, erros})',
        'recurso=entrar com o login certo e volta=<página>: vai para a página' => 'recurso=entrar con el login correcto y volta=<página>: va a la página',
        'sem o token nem o login do site, ou com eles errados; sem nenhum usuário (ou com o banco vazio), também sem_usuarios: true e como (o que fazer: instalar, criar o primeiro usuário pelo token)' => 'sin el token ni el inicio de sesión del sitio, o con ellos erróneos; sin ningún usuario (o con la base de datos vacía), también sem_usuarios: true y como (qué hacer: instalar, crear el primer usuario por el token)',
        'recurso desconhecido (com recursos, a lista deles), ou o relógio, a foto, o documento (ou o arquivo dele) ou o README.md (recurso=manual) que não existe, ou um arquivo que não sai pelo recurso=codigo ({erro, e o_que_ver no que fica de fora de propósito, como o config.php, ou arquivos, os que saem)' => 'recurso desconocido (con recursos, la lista de ellos), o el reloj, la foto, el documento (o su archivo) o el README.md (recurso=manual) que no existe, o un archivo que no sale por recurso=codigo ({erro, y o_que_ver en lo que queda fuera a propósito, como el config.php, o arquivos, los que salen)',
        'o banco recusou a gravação (um registro que outro ainda usa, um valor repetido, ou um valor fora das regras de validação do banco: o nome da regra, ck_<tabela>_<o quê>, vem no detalhe)' => 'la base de datos rechazó el guardado (un registro que otro aún usa, un valor repetido, o un valor fuera de las reglas de validación de la base de datos: el nombre de la regla, ck_<tabla>_<qué>, viene en el detalle)',
        'o envio passou do limite do PHP do servidor (post_max_size): um arquivo grande demais' => 'el envío pasó del límite de PHP del servidor (post_max_size): un archivo demasiado grande',
        'sistema parado (token ou fuso inválido no config.php) ou erro interno' => 'sistema parado (token o huso no válido en el config.php) o error interno',
        'banco desatualizado (só recurso=migracoes responde, e o recurso=manual e o recurso=codigo, que não usam o banco), banco vazio (antes da instalação só recurso=instalacao responde, e o manual e o código) ou banco fora do ar' => 'base de datos desactualizada (solo responde recurso=migracoes, y recurso=manual y recurso=codigo, que no usan la base de datos), base de datos vacía (antes de la instalación solo responde recurso=instalacao, y el manual y el código) o base de datos fuera de servicio',
        'números com vírgula ou ponto; textos entre aspas; argumentos separados por ponto e vírgula; operações + - * / ^; comparações = <> < <= > >= (dão 1 ou 0); variáveis: os identificadores dos campos e das fórmulas; vazio se propaga; divisão por zero: vazio' => 'números con coma o punto; textos entre comillas; argumentos separados por punto y coma; operaciones + - * / ^; comparaciones = <> < <= > >= (dan 1 o 0); variables: los identificadores de los campos y de las fórmulas; vacío se propaga; división por cero: vacío',
    ],
    'reconstrucao' => [
        'os eventos que o sistema criou no Google Agenda: a chave (o que o evento é: o tipo, o relógio e o dia), o id no Google, a data, o título e a assinatura (o resumo do conteúdo, para saber se mudou)' => 'los eventos que el sistema creó en Google Calendar: la clave (lo que es el evento: el tipo, el reloj y el día), el id en Google, la fecha, el título y la firma (el resumen del contenido, para saber si cambió)',
        'os avisos do cadastro: o identificador, o nome, a fórmula da data prevista (expressao), a condição (vale quando), a antecedência em dias, o texto, se está ativo, o grupo da versão (no_id; vazio: todos), o tipo de lançamento que resolve, como a escala simula a solução (escala, simula_valor, simula_horas) e se entra na agenda só dentro da janela ou sempre' => 'los avisos de la ficha: el identificador, el nombre, la fórmula de la fecha prevista (expressao), la condición (vale cuando), la antelación en días, el texto, si está activo, el grupo de la versión (no_id; vacío: todos), el tipo de registro que lo resuelve, cómo simula la escala la solución (escala, simula_valor, simula_horas) y si entra en la agenda solo dentro de la ventana o siempre',
        'os campos do cadastro dos relógios: o identificador (o nome nas fórmulas), o nome, o tipo, a unidade, o valor padrão, o grupo em que vale (vazio: todos) e a ordem' => 'los campos de la ficha de los relojes: el identificador (el nombre en las fórmulas), el nombre, el tipo, la unidad, el valor predeterminado, el grupo en el que vale (vacío: todos) y el orden',
        'as opções de um campo do tipo lista, em ordem (sem repetir, sem diferenciar maiúsculas e acentos)' => 'las opciones de un campo del tipo lista, en orden (sin repetir, sin diferenciar mayúsculas y acentos)',
        'o valor de cada campo em cada relógio (texto normalizado pelo tipo do campo: número com ponto, data AAAA-MM-DD, sim/não 1 ou 0)' => 'el valor de cada campo en cada reloj (texto normalizado por el tipo del campo: número con punto, fecha AAAA-MM-DD, sí/no 1 o 0)',
        'para cada canal (tg: Telegram, ag: Google Agenda) e cada tipo de aviso (dia, vespera, o identificador de um aviso) ou evento personalizado: se ele vai pelo canal, se tem mensagem própria e o texto dela' => 'para cada canal (tg: Telegram, ag: Google Calendar) y cada tipo de aviso (dia, vespera, el identificador de un aviso) o evento personalizado: si va por el canal, si tiene mensaje propio y su texto',
        'os valores soltos da Configuração (horários, limites, mensagens padrão, marcas do sistema), chave e valor' => 'los valores sueltos de la Configuración (horarios, límites, mensajes por defecto, marcas del sistema), clave y valor',
        'as faixas de um subparâmetro: de um número até outro (ou sem limite) ou uma categoria, e a nota (0 a 100) que o valor ganha nela' => 'los rangos de un subparámetro: de un número hasta otro (o sin límite) o una categoría, y la nota (0 a 100) que el valor gana en él',
        'os parâmetros de um conjunto de critérios: o lugar (todos, um grupo ou um relógio), o nome, o peso (%) e a ordem' => 'los parámetros de un conjunto de criterios: el lugar (todos, un grupo o un reloj), el nombre, el peso (%) y el orden',
        'os subparâmetros de um parâmetro: o nome, a variável que mede (um campo ou uma fórmula), o peso dentro do parâmetro (%) e a ordem' => 'los subparámetros de un parámetro: el nombre, la variable que mide (un campo o una fórmula), el peso dentro del parámetro (%) y el orden',
        'cada execução do cron que registrou algo: início, fim, duração, o registro em texto, se teve erro e se teve atividade' => 'cada ejecución del cron que registró algo: inicio, fin, duración, el registro en texto, si tuvo error y si tuvo actividad',
        'os documentos de cada relógio: a categoria, o título, a data, a descrição, o nome e o tipo do arquivo, o tamanho, o caminho na pasta (arquivo e miniatura), se a cópia no banco está completa (no_banco), se o próprio arquivo pede a cópia (copia_banco) e o SHA-256' => 'los documentos de cada reloj: la categoría, el título, la fecha, la descripción, el nombre y el tipo del archivo, el tamaño, el camino en la carpeta (archivo y miniatura), si la copia en la base de datos está completa (no_banco), si el propio archivo pide la copia (copia_banco) y el SHA-256',
        'as categorias dos documentos (Manual, Nota fiscal, Fotos...): identificador, nome e ordem' => 'las categorías de los documentos (Manual, Factura, Fotos...): identificador, nombre y orden',
        'as famílias de arquivo que uma categoria aceita (imagem, video, audio, pdf, xml); nenhuma: qualquer arquivo' => 'las familias de archivo que acepta una categoría (imagem, video, audio, pdf, xml); ninguna: cualquier archivo',
        'a cópia de um documento dentro do banco, em pedaços de 4 MB (parte 0, 1, 2...; a parte -1 é a miniatura)' => 'la copia de un documento dentro de la base de datos, en trozos de 4 MB (parte 0, 1, 2...; la parte -1 es la miniatura)',
        'os dias da semana de um evento personalizado semanal (1 segunda a 7 domingo)' => 'los días de la semana de un evento personalizado semanal (1 lunes a 7 domingo)',
        'cada ocorrência de um evento personalizado que já disparou (para não disparar duas vezes)' => 'cada ocurrencia de un evento personalizado que ya se disparó (para no dispararse dos veces)',
        'os lembretes do usuário: nome, se está ativo, a repetição (uma vez, todo dia, em dias da semana, todo mês, a cada N dias), a data de início, a hora, o dia do mês, o intervalo e o relógio (opcional)' => 'los recordatorios del usuario: nombre, si está activo, la repetición (una vez, todos los días, en días de la semana, todos los meses, cada N días), la fecha de inicio, la hora, el día del mes, el intervalo y el reloj (opcional)',
        'as fórmulas do cadastro: o identificador (o nome nas outras fórmulas, nos avisos e nos critérios), o nome, a expressão, a unidade e o grupo da versão (no_id; vazio: todos). A mesma fórmula pode ter uma versão por grupo: vale a do grupo mais perto do relógio' => 'las fórmulas de la ficha: el identificador (el nombre en las otras fórmulas, en los avisos y en los criterios), el nombre, la expresión, la unidad y el grupo de la versión (no_id; vacío: todos). La misma fórmula puede tener una versión por grupo: vale la del grupo más cercano al reloj',
        'a foto de cada relógio (a imagem inteira, o tipo e quando foi trocada)' => 'la foto de cada reloj (la imagen entera, el tipo y cuándo se cambió)',
        'o histórico de cada relógio: o tipo, o início (o instante, num instantâneo), o fim (numa sessão; vazio: aberta), o valor (numa leitura) e a origem (manual, rodizio, importado)' => 'el historial de cada reloj: el tipo, el inicio (el instante, en un instantáneo), el fin (en una sesión; vacío: abierta), el valor (en una lectura) y el origen (manual, rodizio, importado)',
        'os tipos de lançamento: identificador, nome, formato (instantâneo, com valor ou sessão), unidade, a hora em que a sessão esquecida fecha sozinha (fecha_as), o grupo, a ordem, se a sessão é exclusiva (o relógio fica num lugar só), se a leitura mede o gasto e a condição (vale quando)' => 'los tipos de registro: identificador, nombre, formato (instantáneo, con valor o sesión), unidad, la hora a la que la sesión olvidada se cierra sola (fecha_as), el grupo, el orden, si la sesión es exclusiva (el reloj queda en un solo lugar), si la lectura mide el consumo y la condición (vale cuando)',
        'cada medição do gasto: o lançamento (a leitura) que a fechou, se mede o uso ou o repouso, o gasto achado (% por dia), as duas leituras, o intervalo, as horas no pulso e fora, o peso (horas) e se entra na média' => 'cada medición del consumo: el registro (la lectura) que la cerró, si mide el uso o el reposo, el consumo hallado (% por día), las dos lecturas, el intervalo, las horas en la muñeca y fuera, el peso (horas) y si entra en la media',
        'os modos de rodízio: nome, a forma de escolha, a ordem, o horizonte da escala inteligente (escala_dias; vazio: o modo sorteia pelos blocos), o ciclo e a marca do modo em uso (1 no ativo, vazio nos outros: no máximo um)' => 'los modos de rotación: nombre, la forma de elección, el orden, el horizonte de la escala inteligente (escala_dias; vacío: el modo sortea por los bloques), el ciclo y la marca del modo en uso (1 en el activo, vacío en los demás: como máximo uno)',
        'os blocos de um modo: nome, de onde sortear (um grupo; vazio: todos), um relógio por dia ou um para o bloco inteiro, o relógio fixo (opcional) e a ordem' => 'los bloques de un modo: nombre, de dónde sortear (un grupo; vacío: todos), un reloj por día o uno para el bloque entero, el reloj fijo (opcional) y el orden',
        'os dias da semana de um bloco (1 segunda a 7 domingo; um dia em um bloco só)' => 'los días de la semana de un bloque (1 lunes a 7 domingo; un día en un solo bloque)',
        'a árvore dos grupos: o nome, o grupo de cima (vazio: a raiz) e a ordem entre irmãos' => 'el árbol de los grupos: el nombre, el grupo de arriba (vacío: la raíz) y el orden entre hermanos',
        'o relógio de cada dia: o relógio, o bloco do modo que o escolheu, a origem (sorteio ou manual), a ação do dia (o que fazer antes de usar), o motivo da escolha e quando foi gravado' => 'el reloj de cada día: el reloj, el bloque del modo que lo eligió, el origen (sorteio o manual), la acción del día (qué hacer antes de usar), el motivo de la elección y cuándo se guardó',
        'os relógios: nome, grupo, se está disponível para o rodízio, se pede a cópia no banco de todos os documentos e quando foi cadastrado' => 'los relojes: nombre, grupo, si está disponible para la rotación, si pide la copia en la base de datos de todos los documentos y cuándo se registró',
        'os dias livres do plano: sem relógio e sem sorteio (nem a escala), para escolher à mão' => 'los días libres del plan: sin reloj y sin sorteo (ni la escala), para elegir a mano',
        'quem entra no site: o login e o hash da senha (password_hash)' => 'quién entra en el sitio: el login y el hash de la contraseña (password_hash)',
        'mysql (MySQL ou MariaDB, o padrão), pgsql (PostgreSQL), sqlite ou firebird (Firebird 3+)' => 'mysql (MySQL o MariaDB, el predeterminado), pgsql (PostgreSQL), sqlite o firebird (Firebird 3+)',
        'o servidor do banco (MySQL, PostgreSQL e Firebird; no Firebird, DB_NOME é o caminho do arquivo .fdb no servidor ou um apelido, e DB_HOST vazio abre o arquivo direto)' => 'el servidor de la base de datos (MySQL, PostgreSQL y Firebird; en Firebird, DB_NOME es el camino del archivo .fdb en el servidor o un alias, y DB_HOST vacío abre el archivo directo)',
        'o arquivo do banco (SQLite), fora da pasta publicada' => 'el archivo de la base de datos (SQLite), fuera de la carpeta publicada',
        'obrigatório, com pelo menos 10 caracteres: sem ele o sistema inteiro para (as páginas, a API e o cron dizem o motivo)' => 'obligatorio, con al menos 10 caracteres: sin él el sistema entero se para (las páginas, la API y el cron dicen el motivo)',
        'o fuso horário do sistema e das datas gravadas (vazio: o do PHP)' => 'el huso horario del sistema y de las fechas guardadas (vacío: el de PHP)',
        'a API de mensagem (Telegram): um GET com destinatario, titulo e mensagem; resposta 2xx é sucesso; sem o endereço, nada é enviado' => 'la API de mensaje (Telegram): un GET con destinatario, titulo y mensagem; respuesta 2xx es éxito; sin la dirección, no se envía nada',
        'a pasta dos arquivos dos documentos, fora da pasta publicada, com escrita para o PHP' => 'la carpeta de los archivos de los documentos, fuera de la carpeta publicada, con escritura para PHP',
        'o maior documento aceito, em bytes (sem ele: 100 MB; 0 ou -1: sem limite do sistema)' => 'el mayor documento aceptado, en bytes (sin él: 100 MB; 0 o -1: sin límite del sistema)',
        'a cópia dos documentos no banco para o sistema inteiro: true, todos; false, nenhum; ausente, o relógio e o arquivo decidem' => 'la copia de los documentos en la base de datos para el sistema entero: true, todos; false, ninguno; ausente, el reloj y el archivo deciden',
        'opcional, para quem traduz: true faz a tradução que falta parar com erro (na API e no cron; nas telas, o texto aparece entre ⟦ ⟧ e o erro vai para o console)' => 'opcional, para quien traduce: true hace que la traducción que falta se detenga con un error (en la API y en el cron; en las pantallas, el texto aparece entre ⟦ ⟧ y el error va a la consola)',
        'opcional: false desliga a cópia de segurança (sem cópia automática, sem a escrita fazer e sem o quadro da Configuração); sem a linha, ligada' => 'opcional: false desactiva la copia de seguridad (sin copia automática, sin la escritura fazer y sin el cuadro de la Configuración); sin la línea, activada',
        'a cópia de segurança do banco: a pasta (fora da publicada; sem ela, não há cópia automática), quantas ficam (padrão 7) e se leva o conteúdo dos documentos (padrão: não)' => 'la copia de seguridad de la base de datos: la carpeta (fuera de la publicada; sin ella, no hay copia automática), cuántas quedan (por defecto 7) y si lleva el contenido de los documentos (por defecto: no)',
        'só para importar o sistema anterior (importar.php)' => 'solo para importar el sistema anterior (importar.php)',
        'só para testes: as fontes dos números aleatórios (RANDOM.ORG e ANU QRNG); trocadas, os sorteios pedem os números a um servidor de teste' => 'solo para pruebas: las fuentes de los números aleatorios (RANDOM.ORG y ANU QRNG); cambiadas, los sorteos piden los números a un servidor de prueba',
        'só para testes: os endereços do Google que a agenda usa (o do token e o da API do Google Agenda); trocados, a sincronização conversa com um servidor de teste' => 'solo para pruebas: las direcciones de Google que usa la agenda (la del token y la de la API de Google Calendar); cambiadas, la sincronización habla con un servidor de prueba',
        'A interface que a reescrita tem de reproduzir, tela por tela: o visual (cores, letras, controles e componentes, com os valores exatos), o menu, e cada página com o endereço, o que ela lê e grava na API, e as partes em ordem, com cada tabela (as colunas), cada formulário (os campos com o rótulo, o tipo, o padrão e os limites), cada botão (o texto e o que ele manda para a API) e cada mensagem. Os textos entre aspas são os da tela, palavra por palavra. As capturas em docs/telas/ mostram o resultado; o estilo.css é a referência de cada medida. O código de cada página, como está agora, sai pelo recurso=codigo (os arquivos dela em codigo; o HTML que ela entrega ao navegador em recurso=codigo&arquivo=<página>&html=1&cru=1).' => 'La interfaz que la reescritura tiene que reproducir, pantalla por pantalla: el visual (colores, letras, controles y componentes, con los valores exactos), el menú, y cada página con la dirección, lo que lee y guarda en la API, y las partes en orden, con cada tabla (las columnas), cada formulario (los campos con el rótulo, el tipo, el predeterminado y los límites), cada botón (el texto y lo que manda a la API) y cada mensaje. Los textos entre comillas son los de la pantalla, palabra por palabra. Las capturas en docs/telas/ muestran el resultado; el estilo.css es la referencia de cada medida. El código de cada página, como está ahora, sale por recurso=codigo (sus archivos en codigo; el HTML que entrega al navegador en recurso=codigo&arquivo=<página>&html=1&cru=1).',
        'Fundo da página: aço #e4e8ec. Bordas: aço escuro #c3cad2. Texto: tinta #1c2530 (também o fundo da barra do menu). Rótulos e notas: cinza #6b7684. Botões, links, aba ativa, barras de carga: safira #1f4f8f. O que fazer, recados e carga baixa: âmbar #a8661a. Fundo de cartões, quadros e tabelas: papel #fbfcfd.' => 'Fondo de la página: acero #e4e8ec. Bordes: acero oscuro #c3cad2. Texto: tinta #1c2530 (también el fondo de la barra del menú). Rótulos y notas: gris #6b7684. Botones, enlaces, pestaña activa, barras de carga: zafiro #1f4f8f. Qué hacer, mensajes y carga baja: ámbar #a8661a. Fondo de tarjetas, cuadros y tablas: papel #fbfcfd.',
        'Etiquetas de estado (pílulas): em uso: fundo #e3f3e6, texto #1e6b2e, borda #a9d8b3. Em repouso e erro: fundo #fbe8e6, texto #9b2c22, borda #efb5ae. Indisponível e sem atividade: fundo #eef1f4, texto cinza, borda aço escuro. Atividade, "você" e "relógio de hoje": fundo #e6eef8, texto #1f4f8f, borda #b8cbe6. Numa sessão que não é o pulso (no sol, no winder, no carregador), outras sessões e carga: fundo #fff4e0, texto #8a5a00, borda #efd29a.' => 'Etiquetas de estado (píldoras): en uso: fondo #e3f3e6, texto #1e6b2e, borde #a9d8b3. En reposo y error: fondo #fbe8e6, texto #9b2c22, borde #efb5ae. No disponible y sin actividad: fondo #eef1f4, texto gris, borde acero oscuro. Actividad, "usted" y "reloj de hoy": fondo #e6eef8, texto #1f4f8f, borde #b8cbe6. En una sesión que no es la muñeca (al sol, en el winder, en el cargador), otras sesiones y carga: fondo #fff4e0, texto #8a5a00, borde #efd29a.',
        'Origem de um valor do cadastro: "informado" em azul (#e6eef8 / #1f4f8f / #b8cbe6), "padrão" em bege (#fbf1e3 / #8a5a00 / #ecd2a8), "vazio" sem etiqueta e com a linha em cinza.' => 'Origen de un valor de la ficha: "informado" en azul (#e6eef8 / #1f4f8f / #b8cbe6), "predeterminado" en beige (#fbf1e3 / #8a5a00 / #ecd2a8), "vacío" sin etiqueta y con la línea en gris.',
        'Atrasado (um prazo vencido, "faltam" e "passa" das somas): texto #9b2c22 em negrito. Caixa de erros de gravação: fundo #fdf0ee, borda #e3b4ae, texto #7a2419, cantos 10px. Linha de execução com erro: fundo #fdf2f1.' => 'Atrasado (un plazo vencido, "faltan" y "pasa" de las sumas): texto #9b2c22 en negrita. Caja de errores de guardado: fondo #fdf0ee, borde #e3b4ae, texto #7a2419, esquinas 10px. Línea de ejecución con error: fondo #fdf2f1.',
        'Letras e números' => 'Letras y números',
        'Fonte: "Segoe UI", "Helvetica Neue", Arial, sans-serif, 16px, entrelinha 1,5.' => 'Fuente: "Segoe UI", "Helvetica Neue", Arial, sans-serif, 16px, interlineado 1,5.',
        'Título da página (h1): grande, de 2rem a 3,4rem conforme a largura (clamp(2rem, 6vw, 3.4rem)), negrito 700, espaçamento -0,02em, entrelinha 1,05. Título de seção (h2): 1,1rem. Notas e explicações: 0,92rem, cinza. Título dos quadros do painel do relógio: 0,78rem, maiúsculas, negrito, espaçado 0,06em, cinza, com uma linha embaixo. Números em tabelas e valores com algarismos de largura igual (tabular).' => 'Título de la página (h1): grande, de 2rem a 3,4rem según la anchura (clamp(2rem, 6vw, 3.4rem)), negrita 700, espaciado -0,02em, interlineado 1,05. Título de sección (h2): 1,1rem. Notas y explicaciones: 0,92rem, gris. Título de los cuadros del panel del reloj: 0,78rem, mayúsculas, negrita, espaciado 0,06em, gris, con una línea debajo. Números en tablas y valores con cifras de anchura igual (tabular).',
        'Formatos: data DD/MM/AAAA (curta: DD/MM); hora HH:MM; números com vírgula e sem zeros sobrando (1 casa por padrão); dinheiro "R$ 1.234,56"; porcentagem "12,5%"; duração pelas duas maiores partes: "1a 5m", "5d 3h", "12h 22min", "40min", "menos de 1min"; dia da semana curto: seg, ter, qua, qui, sex, sáb, dom.' => 'Formatos: fecha DD/MM/AAAA (corta: DD/MM); hora HH:MM; números con coma y sin ceros de sobra (1 decimal por defecto); dinero "R$ 1.234,56"; porcentaje "12,5%"; duración por las dos partes mayores: "1a 5m", "5d 3h", "12h 22min", "40min", "menos de 1min"; día de la semana corto: lun, mar, mié, jue, vie, sáb, dom.',
        'Campos, listas e botões' => 'Campos, listas y botones',
        'Uma altura só para campo, lista e botão: 2,4rem, para ficarem alinhados lado a lado. Cantos 8px; campo e lista com borda 1px aço escuro e fundo branco; textarea com a mesma borda. Foco visível: contorno 2px safira afastado 2px. Campo numérico curto: 5,5rem. Números digitados aceitam vírgula ou ponto (teclado decimal no celular). No celular, os campos têm letra de 16px (o iPhone não aproxima a tela).' => 'Una sola altura para campo, lista y botón: 2,4rem, para que queden alineados lado a lado. Esquinas 8px; campo y lista con borde 1px acero oscuro y fondo blanco; textarea con el mismo borde. Foco visible: contorno 2px zafiro separado 2px. Campo numérico corto: 5,5rem. Los números tecleados aceptan coma o punto (teclado decimal en el móvil). En el móvil, los campos tienen letra de 16px (el iPhone no acerca la pantalla).',
        'Botão principal: fundo safira, texto branco, borda safira, preenchimento 0,3rem 1rem. Botão "leve": fundo transparente, texto e borda safira (as ações secundárias). Botão "discreto": sem borda, 0,85rem, preenchimento lateral 0,45rem (↑, ↓ e Excluir das linhas). O Excluir das ações de linha é vermelho: texto #9b2c22, borda #efb5ae, fundo #fbe8e6 ao passar o mouse.' => 'Botón principal: fondo zafiro, texto blanco, borde zafiro, relleno 0,3rem 1rem. Botón "leve": fondo transparente, texto y borde zafiro (las acciones secundarias). Botón "discreto": sin borde, 0,85rem, relleno lateral 0,45rem (↑, ↓ y Eliminar de las filas). El Eliminar de las acciones de fila es rojo: texto #9b2c22, borde #efb5ae, fondo #fbe8e6 al pasar el ratón.',
        'Caixa de marcar (checkbox) sempre à esquerda do texto, na mesma linha. Rótulo de campo: acima do campo nas grades de formulário; à esquerda na Configuração (veja os componentes). Botões desativados durante o envio de um formulário.' => 'Casilla de marcar (checkbox) siempre a la izquierda del texto, en la misma línea. Rótulo de campo: encima del campo en las cuadrículas de formulario; a la izquierda en la Configuración (vea los componentes). Botones desactivados durante el envío de un formulario.',
        'Barra do menu: fundo tinta, links #b9c3ce sem sublinhado; o da página atual em branco com uma linha branca de 2px embaixo.' => 'Barra del menú: fondo tinta, enlaces #b9c3ce sin subrayado; el de la página actual en blanco con una línea blanca de 2px debajo.',
        'Cartão (as seções das páginas de cadastro): fundo papel, borda 1px aço escuro, cantos 12px, preenchimento 1rem, título h2 em cima.' => 'Tarjeta (las secciones de las páginas de ficha): fondo papel, borde 1px acero oscuro, esquinas 12px, relleno 1rem, título h2 arriba.',
        'Quadro (o painel do relógio): igual ao cartão (cantos 12px, preenchimento 0,85rem 1rem), com o título em maiúsculas pequenas, o corpo, e um rodapé opcional (linha em cima, botões à direita, alinhados no pé: os quadros da mesma linha da grade têm a mesma altura). Quadro "largo" ocupa a linha inteira da grade.' => 'Cuadro (el panel del reloj): igual que la tarjeta (esquinas 12px, relleno 0,85rem 1rem), con el título en versalitas, el cuerpo, y un pie opcional (línea arriba, botones a la derecha, alineados al pie: los cuadros de la misma fila de la cuadrícula tienen la misma altura). El cuadro "largo" ocupa la fila entera de la cuadrícula.',
        'Pares (rótulo e valor): duas colunas, o rótulo em cinza 0,85rem à esquerda (até 55% da largura), o valor à direita; uma linha fina aço entre os pares (a última sem); um texto menor (0,78rem, cinza) embaixo do valor é a explicação dele; rótulo vazio continua a linha de cima.' => 'Pares (rótulo y valor): dos columnas, el rótulo en gris 0,85rem a la izquierda (hasta el 55% de la anchura), el valor a la derecha; una línea fina de acero entre los pares (la última sin); un texto menor (0,78rem, gris) debajo del valor es su explicación; rótulo vacío continúa la línea de arriba.',
        'Tabela: fundo papel, cantos 10px, cabeçalho em cinza 0,9rem negrito, células com preenchimento 0,55rem 0,75rem e uma linha aço embaixo. Linha clicável: o fundo muda para #f1f4f8 ao passar e fica #e3eaf5 quando selecionada; fim de semana em #f4f6f8; o relógio de hoje com uma faixa safira de 3px na borda esquerda, e um com aviso pendente com a faixa âmbar. Tabela compacta (dos cadastros): 0,88rem, sem fundo próprio.' => 'Tabla: fondo papel, esquinas 10px, cabecera en gris 0,9rem negrita, celdas con relleno 0,55rem 0,75rem y una línea de acero debajo. Fila en la que se puede hacer clic: el fondo pasa a #f1f4f8 al pasar y queda #e3eaf5 cuando está seleccionada; fin de semana en #f4f6f8; el reloj de hoy con una franja zafiro de 3px en el borde izquierdo, y uno con aviso pendiente con la franja ámbar. Tabla compacta (de las definiciones): 0,88rem, sin fondo propio.',
        'Etiqueta de estado: pílula com cantos arredondados por inteiro, 0,8rem negrito, preenchimento 0,12rem 0,55rem, cores em "cores". Numa linha só; nos pares rótulo/valor (o quadro Agora do painel estreito) e nas marcas da cabeça, a comprida ("Em repouso desde 25/09 20:40") quebra a linha nos espaços (nunca no meio da palavra), com cantos de 0,8rem, e fica dentro do quadro.' => 'Etiqueta de estado: píldora con esquinas redondeadas por entero, 0,8rem negrita, relleno 0,12rem 0,55rem, colores en "colores". En una sola línea; en los pares rótulo/valor (el cuadro Ahora del panel estrecho) y en las marcas de la cabecera, la larga ("En reposo desde 25/09 20:40") parte la línea en los espacios (nunca en medio de la palabra), con esquinas de 0,8rem, y se queda dentro del cuadro.',
        'Barra de carga: trilho aço com 7px de altura (44px na tabela, 56 a 70px nos quadros), preenchido em safira até a porcentagem (âmbar com carga até 20%), seguido do número em negrito ("68%"; estimado: "~68%") e, menor, de onde a carga vem.' => 'Barra de carga: carril de acero con 7px de altura (44px en la tabla, 56 a 70px en los cuadros), relleno en zafiro hasta el porcentaje (ámbar con carga hasta el 20%), seguido del número en negrita ("68%"; estimado: "~68%") y, menor, de dónde viene la carga.',
        'Janela de data (o "só hoje" / "até sexta, 02/10" do relógio do dia): caixa branca, borda 2px tinta, cantos 3px, negrito, sombra interna fina, como a janela de data de um mostrador.' => 'Ventana de fecha (el "solo hoy" / "hasta el viernes, 02/10" del reloj del día): caja blanca, borde 2px tinta, esquinas 3px, negrita, sombra interna fina, como la ventana de fecha de una esfera.',
        'Recado (o resultado de uma gravação): um parágrafo âmbar em negrito no topo da área (ou do painel do relógio). Erros de gravação: a caixa vermelha clara com "Não foi salvo:" e um parágrafo por erro, no topo da página.' => 'Mensaje (el resultado de un guardado): un párrafo ámbar en negrita en lo alto del área (o del panel del reloj). Errores de guardado: la caja roja clara con "No se ha guardado:" y un párrafo por error, en lo alto de la página.',
        'Abas (Cadastros e Documentos): links lado a lado com borda aço e cantos 0,4rem, preenchimento 0,35rem 0,8rem, texto safira; a ativa com fundo safira e texto branco.' => 'Pestañas (Definiciones y Documentos): enlaces lado a lado con borde acero y esquinas 0,4rem, relleno 0,35rem 0,8rem, texto zafiro; la activa con fondo zafiro y texto blanco.',
        'Grade de formulário (form-grade): colunas de no mínimo 14rem lado a lado, o rótulo acima de cada campo; textareas, grupos de caixas e botões na linha inteira. Linha de inclusão: campos com o rótulo em cima, lado a lado, separados do resto por uma linha tracejada acima.' => 'Cuadrícula de formulario (form-grade): columnas de como mínimo 14rem lado a lado, el rótulo encima de cada campo; textareas, grupos de casillas y botones en la fila entera. Fila de inclusión: campos con el rótulo arriba, lado a lado, separados del resto por una línea de trazos arriba.',
        'Barra de salvar (Configuração): presa no pé da tela enquanto a página rola (sticky), fundo papel quase opaco, borda, cantos 12px, sombra para cima; à esquerda "As mudanças desta página valem depois de salvar.", à direita o botão.' => 'Barra de guardar (Configuración): fija al pie de la pantalla mientras la página se desplaza (sticky), fondo papel casi opaco, borde, esquinas 12px, sombra hacia arriba; a la izquierda "Los cambios de esta página valen después de guardar.", a la derecha el botón.',
        'Sem foto: quadrado tracejado (2px aço escuro, cantos 14px) com "Sem foto" em cinza no meio. Foto: quadrada (recortada), cantos 14px, borda aço escuro. Miniatura na tabela: 28px (36px no celular), cantos 5px.' => 'Sin foto: cuadrado de trazos (2px acero oscuro, esquinas 14px) con "Sin foto" en gris en el medio. Foto: cuadrada (recortada), esquinas 14px, borde acero oscuro. Miniatura en la tabla: 28px (36px en el móvil), esquinas 5px.',
        'Ações de uma linha (Editar, ↑, ↓, Excluir): numa linha só, à direita da linha da tabela.' => 'Acciones de una fila (Editar, ↑, ↓, Eliminar): en una sola línea, a la derecha de la fila de la tabla.',
        'Resumo em números (Execuções e Histórico): uma grade de caixinhas (4 colunas; 2 no celular), cada uma com o número grande (1,4rem) e o que ele é embaixo em cinza; a de erros com fundo vermelho claro.' => 'Resumen en números (Ejecuciones e Historial): una cuadrícula de cajitas (4 columnas; 2 en el móvil), cada una con el número grande (1,4rem) y lo que es debajo en gris; la de errores con fondo rojo claro.',
        'Larguras e tamanhos de tela' => 'Anchuras y tamaños de pantalla',
        'Conteúdo centrado com margens de 1,25rem: largura máxima 56rem nas páginas comuns (Plano, Usuários), 72rem na Ficha, 76rem na Configuração, Cadastros, Critérios, Grupos, Execuções e Histórico, 60rem na Ajuda. A página Hoje usa a largura toda.' => 'Contenido centrado con márgenes de 1,25rem: anchura máxima 56rem en las páginas comunes (Plan, Usuarios), 72rem en la Ficha, 76rem en la Configuración, Definiciones, Criterios, Grupos, Ejecuciones e Historial, 60rem en la Ayuda. La página Hoy usa toda la anchura.',
        'Página Hoje: duas colunas, o meio e o painel do relógio com 22rem à direita, preso ao rolar (sticky) e com rolagem própria; sem relógio aberto, o meio ocupa tudo. Com a Configuração "Numa janela flutuante, grande": o relógio abre no meio da tela, até 78rem ou 94% da largura, de 3% do alto a 3% de baixo, cantos 16px, sombra forte, com o fundo escurecido (rgba(16, 22, 29, .55)) e os quadros lado a lado; fecha no ×, no Esc ou num clique no fundo.' => 'Página Hoy: dos columnas, el centro y el panel del reloj con 22rem a la derecha, fijo al desplazar (sticky) y con desplazamiento propio; sin reloj abierto, el centro lo ocupa todo. Con la Configuración "En una ventana flotante, grande": el reloj se abre en el medio de la pantalla, hasta 78rem o el 94% de la anchura, del 3% de arriba al 3% de abajo, esquinas 16px, sombra fuerte, con el fondo oscurecido (rgba(16, 22, 29, .55)) y los cuadros lado a lado; se cierra en el ×, en Esc o con un clic en el fondo.',
        'Até 900px (celular e tablet de pé): o menu recolhido; as tabelas viram fichas (cada célula com o título da coluna ao lado) ou cartões; o painel do relógio cobre a tela inteira, com o botão "× Fechar" preso no alto, e o voltar do aparelho fecha o painel; as grades viram uma coluna. De 901 a 1199px (tablet deitado): o painel "ao lado" desliza por cima, pela direita, com até 30rem, cantos 16px à esquerda e o fundo escurecido. De 1200px em diante: o painel ao lado.' => 'Hasta 900px (móvil y tableta de pie): el menú recogido; las tablas se vuelven fichas (cada celda con el título de la columna al lado) o tarjetas; el panel del reloj cubre la pantalla entera, con el botón "× Cerrar" fijo arriba, y el volver del aparato cierra el panel; las cuadrículas se vuelven una columna. De 901 a 1199px (tableta tumbada): el panel "al lado" se desliza por encima, por la derecha, con hasta 30rem, esquinas 16px a la izquierda y el fondo oscurecido. De 1200px en adelante: el panel al lado.',
        'Nenhuma página rola de lado, em nenhum tamanho. A mesma informação em todos os tamanhos: nada é escondido por falta de espaço (a tabela dos relógios vira cartões com todos os campos quando as 12 colunas não cabem).' => 'Ninguna página se desplaza de lado, en ningún tamaño. La misma información en todos los tamaños: nada se oculta por falta de espacio (la tabla de los relojes se vuelve tarjetas con todos los campos cuando las 12 columnas no caben).',
        'As tabelas de um quadro se arrumam pela largura do quadro (container queries), não pela da tela: o mesmo quadro é estreito no painel ao lado e largo na ficha. Até 40rem, as Medições do gasto viram cartões; até 26rem, as tabelas dos Dados do relógio ficam mais justas e o valor quebra a linha.' => 'Las tablas de un cuadro se arreglan por la anchura del cuadro (container queries), no por la de la pantalla: el mismo cuadro es estrecho en el panel al lado y ancho en la ficha. Hasta 40rem, las Mediciones del consumo se vuelven tarjetas; hasta 26rem, las tablas de los Datos del reloj quedan más justas y el valor parte la línea.',
        'Nada sai da caixa em que está, de 320px (celular pequeno) a 1920px: as grades de colunas automáticas encolhem a coluna mínima até a largura da tela; um grupo de campos (fieldset) e os menus dentro dele encolhem com a tela (um menu de nome comprido não vaza); o menu de escolher o relógio da Ficha fica na largura da tela; o código comprido da Ajuda (uma URL de exemplo) quebra a linha. Os botões nunca partem o texto em duas linhas: os da foto (Abrir, Trocar, Remover foto) ficam numa linha, na largura da foto (6,5rem no painel ao lado e no celular); o botão de marcar do quadro Marcar fica numa linha própria, embaixo dos campos. Até 420px, as tabelas do painel e o resumo do Plano ficam mais justas (0,82rem, 0,3rem entre as colunas) e quebram dentro da célula. No Histórico do celular, as colunas são 25%, 25%, 18% e 32% (o Estado, a mais larga).' => 'Nada sale de la caja en la que está, de 320px (móvil pequeño) a 1920px: las cuadrículas de columnas automáticas encogen la columna mínima hasta la anchura de la pantalla; un grupo de campos (fieldset) y los menús dentro de él encogen con la pantalla (un menú de nombre largo no se sale); el menú de elegir el reloj de la Ficha se queda en la anchura de la pantalla; el código largo de la Ayuda (una URL de ejemplo) parte la línea. Los botones nunca parten el texto en dos líneas: los de la foto (Abrir, Cambiar, Quitar foto) quedan en una línea, en la anchura de la foto (6,5rem en el panel al lado y en el móvil); el botón de marcar del cuadro Marcar queda en una línea propia, debajo de los campos. Hasta 420px, las tablas del panel y el resumen del Plan quedan más justas (0,82rem, 0,3rem entre las columnas) y parten dentro de la celda. En el Historial del móvil, las columnas son 25%, 25%, 18% y 32% (el Estado, la más ancha).',
        'Comportamento comum' => 'Comportamiento común',
        'Cada página entrega só o esqueleto; o JavaScript dela lê a API e monta a tela. Gravar é um formulário que manda um POST para a API (recurso e acao nos campos); depois a página se remonta com os dados novos, sem recarregar, e mostra a mensagem da API no topo (ou no painel do relógio, se a gravação era dele).' => 'Cada página entrega solo el esqueleto; el JavaScript de ella lee la API y monta la pantalla. Guardar es un formulario que manda un POST a la API (recurso y acao en los campos); después la página se remonta con los datos nuevos, sin recargar, y muestra el mensaje de la API arriba (o en el panel del reloj, si el guardado era de él).',
        'Antes de toda exclusão e de toda ação que refaz o plano, uma confirmação do navegador com o texto do que vai acontecer (os textos estão em cada página). Durante o envio os botões do formulário ficam desativados; se a conexão falhar: "Não consegui gravar: <motivo>. Confira a conexão e tente de novo."' => 'Antes de toda eliminación y de toda acción que rehace el plan, una confirmación del navegador con el texto de lo que va a ocurrir (los textos están en cada página). Durante el envío los botones del formulario quedan desactivados; si falla la conexión: "No pude guardar: <motivo>. Compruebe la conexión e inténtelo de nuevo."',
        'Sem login: a página manda para api.php?recurso=entrar&volta=<a página>, o navegador pede o usuário e a senha e volta. Banco desatualizado (503 com pendentes): a página vai para a Configuração, que mostra só o aviso e o "Aplicar agora". Erro ao ler: "Não consegui ler <o quê>: <motivo>" em âmbar, no lugar da página.' => 'Sin inicio de sesión: la página manda a api.php?recurso=entrar&volta=<la página>, el navegador pide el usuario y la contraseña y vuelve. Base de datos desactualizada (503 con pendientes): la página va a la Configuración, que muestra solo el aviso y el "Aplicar ahora". Error al leer: "No pude leer <qué>: <motivo>" en ámbar, en el lugar de la página.',
        'Fotos reduzidas no navegador antes de enviar: no máximo 1200px no lado maior, JPEG 85%, com a prévia na tela; imagem que não abre: alerta "Não consegui abrir essa imagem. Use JPEG ou PNG.".' => 'Fotos reducidas en el navegador antes de enviar: como máximo 1200px en el lado mayor, JPEG 85%, con la vista previa en la pantalla; imagen que no se abre: alerta "No pude abrir esa imagen. Use JPEG o PNG.".',
        'A foto do relógio ampliada, só no detalhe do relógio (o painel, ou a ficha): duplo clique na foto (o cursor é a lupa de ampliar) ou o botão "Abrir foto" embaixo dela abre por cima de tudo uma janela flutuante (nas outras fotos, como a do "Hoje é dia de" e as miniaturas da lista, o clique abre o relógio e o duplo clique não faz nada a mais): fundo rgba(10,14,20,.82) na tela inteira, a foto no meio, no tamanho dela (os pixels da imagem em px da página), cantos 6px, fundo branco e sombra; maior que a área que se vê, em escala, sem deformar: a escala é o menor entre 1, (largura − 32px) ÷ a largura da foto e (altura − 72px) ÷ a altura da foto, com a largura e a altura sendo o menor entre o monitor (screen.availWidth/availHeight) e a janela do navegador; refeita quando a janela muda de tamanho ou de monitor. Embaixo, em branco, "<nome> · <largura> × <altura> px" e, em escala, "(mostrada a N%)". Um botão redondo "×" (branco, 2,4rem) no canto de cima, à direita. Fecha com o ×, com um clique fora da foto ou com Esc (o Esc fecha só a foto: o painel por baixo continua aberto); enquanto aberta, a página não rola.' => 'La foto del reloj ampliada, solo en el detalle del reloj (el panel, o la ficha): doble clic en la foto (el cursor es la lupa de ampliar) o el botón "Abrir foto" debajo de ella abre por encima de todo una ventana flotante (en las otras fotos, como la de "Hoy es día de" y las miniaturas de la lista, el clic abre el reloj y el doble clic no hace nada más): fondo rgba(10,14,20,.82) en la pantalla entera, la foto en el medio, en su tamaño (los píxeles de la imagen en px de la página), esquinas 6px, fondo blanco y sombra; mayor que el área que se ve, a escala, sin deformar: la escala es el menor entre 1, (anchura − 32px) ÷ la anchura de la foto y (altura − 72px) ÷ la altura de la foto, siendo la anchura y la altura el menor entre el monitor (screen.availWidth/availHeight) y la ventana del navegador; rehecha cuando la ventana cambia de tamaño o de monitor. Debajo, en blanco, "<nombre> · <anchura> × <altura> px" y, a escala, "(mostrada al N%)". Un botón redondo "×" (blanco, 2,4rem) en la esquina de arriba, a la derecha. Se cierra con el ×, con un clic fuera de la foto o con Esc (el Esc cierra solo la foto: el panel de debajo sigue abierto); mientras está abierta, la página no se desplaza.',
        'O título da aba do navegador é o título da página ("Relógio de hoje", "Plano", "Configuração", "Critérios de escolha", "Grupos de relógios", "Execuções do cron", "Usuários", "Cadastros", "Ajuda", "Ficha do relógio", "Documentos", "Desejos", "Estatísticas", "Hora certa", "Acessórios", "Galeria", "Passaporte do relógio" ("Passaporte — <relógio>" depois de ler); no histórico, "Histórico — <relógio>").' => 'El título de la pestaña del navegador es el título de la página ("Reloj de hoy", "Plan", "Configuración", "Criterios de elección", "Grupos de relojes", "Ejecuciones del cron", "Usuarios", "Definiciones", "Ayuda", "Ficha del reloj", "Documentos", "Deseos", "Estadísticas", "Hora exacta", "Accesorios", "Galería", "Pasaporte del reloj" ("Pasaporte — <reloj>" después de leer); en el historial, "Historial — <reloj>").',
        'O navegador de páginas (Próximos dias, Dia a dia do Plano, Rodízio manual): botões leves pequenos (padding .3rem .65rem, letra .9rem) numa linha que quebra: "<" (dica "Anterior"; desativado na primeira), os números (a 1, a última e até 2 de cada lado da atual, com "…" sem borda nos saltos; dica "Página N"; a atual em safira com letra branca, sem ser botão) e ">" (dica "Próximo"; desativado na última). Uma página só: sem navegador. Cada botão relê a API com a página.' => 'El navegador de páginas (Próximos días, Día a día del Plan, Rotación manual): botones leve pequeños (padding .3rem .65rem, letra .9rem) en una línea que parte: "<" (indicación "Anterior"; desactivado en la primera), los números (la 1, la última y hasta 2 de cada lado de la actual, con "…" sin borde en los saltos; indicación "Página N"; la actual en zafiro con letra blanca, sin ser botón) y ">" (indicación "Próximo"; desactivado en la última). Una sola página: sin navegador. Cada botón relee la API con la página.',
        'Na barra escura do topo, nessa ordem, em todas as páginas; o da página atual em branco e sublinhado. A Ficha, o Histórico e os Documentos não estão no menu: abrem do painel do relógio (o histórico e os documentos numa aba nova). No celular (até 900px): a barra, presa no alto ao rolar, mostra o nome da página atual à esquerda e o botão "☰ Menu" à direita; aberto, ele vira "✕ Menu" e os itens aparecem em duas colunas, cada um num botão escuro (#27323f), o atual em safira. Depois do último item, o seletor do idioma: uma caixa pequena com o código curto de cada idioma (PT, EN, 中文, हिं, ES, FR; o nome inteiro na dica); escolher grava o cookie lingua (um ano, o caminho todo) e abre a página de novo nele. Os rótulos abaixo são os do português: em outro idioma, as traduções do dicionário das telas.' => 'En la barra oscura de arriba, en ese orden, en todas las páginas; el de la página actual en blanco y subrayado. La Ficha, el Historial y los Documentos no están en el menú: se abren desde el panel del reloj (el historial y los documentos en una pestaña nueva). En el móvil (hasta 900px): la barra, fija arriba al desplazar, muestra el nombre de la página actual a la izquierda y el botón "☰ Menú" a la derecha; abierto, se vuelve "✕ Menú" y los elementos aparecen en dos columnas, cada uno en un botón oscuro (#27323f), el actual en zafiro. Después del último elemento, el selector del idioma: una caja pequeña con el código corto de cada idioma (PT, EN, 中文, हिं, ES, FR; el nombre entero en la indicación); elegir guarda la cookie lingua (un año, el camino entero) y abre la página de nuevo en él. Los rótulos de abajo son los del portugués: en otro idioma, las traducciones del diccionario de las pantallas.',
        'Estatísticas' => 'Estadísticas',
        'Hora certa' => 'Hora exacta',
        'Acessórios' => 'Accesorios',
        'Configuração' => 'Configuración',
        'Critérios' => 'Criterios',
        'Execuções do cron' => 'Ejecuciones del cron',
        'Usuários' => 'Usuarios',
        'Relógio de hoje' => 'Reloj de hoy',
        'index.php; index.php?r=<id> abre o relógio no painel; index.php?novo=1 abre o cadastro de um novo; index.php#manual abre o quadro Modo de rodízio no Rodízio manual' => 'index.php; index.php?r=<id> abre el reloj en el panel; index.php?novo=1 abre la ficha de uno nuevo; index.php#manual abre el cuadro Modo de rotación en la Rotación manual',
        'recurso=hoje (com proximos_pagina)' => 'recurso=hoje (con proximos_pagina)',
        'recurso=proximos (a troca de página dos Próximos dias)' => 'recurso=proximos (el cambio de página de los Próximos días)',
        'recurso=ficha (o painel)' => 'recurso=ficha (el panel)',
        'recurso=rodizio_manual (o Rodízio manual, de 7 em 7 dias)' => 'recurso=rodizio_manual (la Rotación manual, de 7 en 7 días)',
        'lancamento: iniciar, encerrar, lancar, periodo, alterar, excluir' => 'lancamento: iniciar, encerrar, lancar, periodo, alterar, excluir',
        'rodizio: trocar_dia, modo, resortear, resortear_hoje, proxima_semana, usando, sem_relogio, manual, periodo_sortear, periodo_livre, apagar_tudo' => 'rodizio: trocar_dia, modo, resortear, resortear_hoje, proxima_semana, usando, sem_relogio, manual, periodo_sortear, periodo_livre, apagar_tudo',
        'relogio: salvar, foto, remover_foto, excluir' => 'relogio: salvar, foto, remover_foto, excluir',
        'O relógio do dia (um cartão grande, no alto do meio)' => 'El reloj del día (una tarjeta grande, en lo alto del centro)',
        'O relógio do cartão é o de destaque.relogio_id da API (o que tem relogios[].destaque): o relógio do dia, ou, com a Configuração "Destaque no alto da página Hoje" em "O relógio no pulso agora" (destaque_hoje = pulso), o que está no pulso agora. Quando ele não é o do dia (destaque.e = pulso): o nome dele em h1 (link que abre o painel), a janela de data com "no pulso agora" e o tipo dele, e em âmbar "Relógio do dia: <nome, link que abre o painel> (<até>)" (ou "Hoje não tem relógio do dia."), sem o motivo. Com o destaque no pulso e ninguém no pulso, o cartão do dia como sempre e, embaixo do motivo, o destaque.texto em cinza ("Nenhum relógio no pulso agora: aqui, o relógio do dia."). Os pares, o botão Pôs/Tirou do pulso e a foto são do relógio do cartão.' => 'El reloj de la tarjeta es el de destaque.relogio_id de la API (el que tiene relogios[].destaque): el reloj del día, o, con la Configuración "Destacado arriba de la página Hoy" en "El reloj en la muñeca ahora" (destaque_hoje = pulso), el que está en la muñeca ahora. Cuando no es el del día (destaque.e = pulso): su nombre en h1 (enlace que abre el panel), la ventana de fecha con "en la muñeca ahora" y su tipo, y en ámbar "Reloj del día: <nombre, enlace que abre el panel> (<hasta>)" (o "Hoy no hay reloj del día."), sin el motivo. Con el destacado en la muñeca y nadie en la muñeca, la tarjeta del día como siempre y, debajo del motivo, el destaque.texto en gris ("Ningún reloj en la muñeca ahora: aquí, el reloj del día."). Los pares, el botón Me lo puse/Me lo quité de la muñeca y la foto son del reloj de la tarjeta.',
        'À esquerda: "<Dia da semana>, DD/MM/AAAA · <nome do modo>" em cinza; o nome do relógio do dia em h1 (link que abre o painel); a janela de data com o "até" ("só hoje", "até sexta, 02/10") e o tipo dele; o lembrete do dia em âmbar ("Pôr no winder: <relógio> (8 h)"); "Por que ele: <motivo>" (o motivo em cinza); embaixo, o botão leve discreto "Sem relógio hoje" (rodizio sem_relogio; confirma "Hoje sem relógio? O dia fica livre: ...").' => 'A la izquierda: "<Día de la semana>, DD/MM/AAAA · <nombre del modo>" en gris; el nombre del reloj del día en h1 (enlace que abre el panel); la ventana de fecha con el "hasta" ("solo hoy", "hasta el viernes, 02/10") y su tipo; el recordatorio del día en ámbar ("Poner en el winder: <reloj> (8 h)"); "Por qué él: <motivo>" (el motivo en gris); debajo, el botón leve discreto "Sin reloj hoy" (rodizio sem_relogio; confirma "¿Hoy sin reloj? El día queda libre: ...").',
        'No meio, em pares: Agora (a etiqueta "Em uso desde 07:00", "No sol desde 09:12" ou "Em repouso desde ...", na cor do estado, e o botão leve "Pôs no pulso" / "Tirou do pulso", que manda lancamento iniciar/encerrar do tipo pulso); Carga (a barra, o % e de onde vem, ou só o texto); Última leitura ("89% em 06/10 21:30", se houver); Situação (as linhas da API); Próxima manutenção ("<nome> · <data ou hoje> (<falta>)", a falta em vermelho se atrasada, ou "nenhuma prevista"; o aviso mais perto, sem o Encostado); Encostado (só quando o aviso já venceu: a falta em vermelho); Compra ("R$ valor · loja · data"); Garantia ("até DD/MM/AAAA", "(vencida)" se passou); Código.' => 'En el medio, en pares: Ahora (la etiqueta "En uso desde 07:00", "Al sol desde 09:12" o "En reposo desde ...", en el color del estado, y el botón leve "Me lo puse en la muñeca" / "Me lo quité de la muñeca", que manda lancamento iniciar/encerrar del tipo pulso); Carga (la barra, el % y de dónde viene, o solo el texto); Última lectura ("89% el 06/10 21:30", si la hay); Situación (las líneas de la API); Próximo mantenimiento ("<nombre> · <fecha u hoy> (<falta>)", la falta en rojo si está atrasada, o "ninguno previsto"; el aviso más cercano, sin el Arrinconado); Arrinconado (solo cuando el aviso ya venció: la falta en rojo); Compra ("R$ valor · tienda · fecha"); Garantía ("hasta DD/MM/AAAA", "(vencida)" si pasó); Código.',
        'À direita: a foto do relógio (ou o quadrado "Sem foto"), que abre o painel.' => 'A la derecha: la foto del reloj (o el cuadrado "Sin foto"), que abre el panel.',
        'Hoje livre (hoje_livre da API: o Sem relógio hoje, ou um período livre): h1 "Hoje sem relógio", a janela "dia livre", "Nenhum relógio vai ao pulso pelo rodízio hoje. Quer usar um? ..." e o "escolher…" dos dias livres (trocar_dia de hoje: o escolhido vai para o pulso a partir de agora); sem os pares nem a foto (a não ser com o destaque no pulso).' => 'Hoy libre (hoje_livre de la API: el Sin reloj hoy, o un período libre): h1 "Hoy sin reloj", la ventana "día libre", "Ningún reloj va a la muñeca por la rotación hoy. ¿Quiere usar uno? ..." y el "elegir…" de los días libres (trocar_dia de hoy: el elegido va a la muñeca a partir de ahora); sin los pares ni la foto (salvo con el destacado en la muñeca).',
        'Sem relógio para hoje: h1 "Nenhum relógio para hoje" e "Nenhum relógio disponível no grupo deste dia. Mude o grupo no modo de rodízio ou marque um relógio como disponível."' => 'Sin reloj para hoy: h1 "Ningún reloj para hoy" y "Ningún reloj disponible en el grupo de este día. Cambie el grupo en el modo de rotación o marque un reloj como disponible."',
        'Hoje é dia de (só quando há aviso)' => 'Hoy es día de (solo cuando hay aviso)',
        'Tabela com as colunas "O que fazer" (o nome do aviso; atrasado em vermelho), "Relógio" (link que abre o painel), "Por quê" (o texto do aviso) e, à direita, o botão do lançamento que resolve, com o texto e a ação que a API dá (resolve.botao e resolve.acao): sessão fechada: "Pôs <nome em minúsculas>" (lancamento iniciar); sessão aberta: "Tirou do carregador" (lancamento encerrar); com valor: um campo curto com a unidade de dica ("%") e "Informar <nome>" (lancamento lancar com valor); instantâneo: o nome do tipo (lancamento lancar).' => 'Tabla con las columnas "Qué hacer" (el nombre del aviso; atrasado en rojo), "Reloj" (enlace que abre el panel), "Por qué" (el texto del aviso) y, a la derecha, el botón del registro que lo resuelve, con el texto y la acción que da la API (resolve.botao y resolve.acao): sesión cerrada: "Me lo puse <nombre en minúsculas>" (lancamento iniciar); sesión abierta: "Me lo quité del cargador" (lancamento encerrar); con valor: un campo corto con la unidad de indicación ("%") e "Informar <nombre>" (lancamento lancar con valor); instantáneo: el nombre del tipo (lancamento lancar).',
        'Próximos dias' => 'Próximos días',
        'Título "Próximos dias" com o link "ver o plano inteiro →" (plano.php). Tabela: Dia ("DD/MM" e o dia da semana curto, menor), Relógio (o nome; "à mão" pequeno quando escolhido à mão; o motivo embaixo, menor), Lembrete, e o "trocar por…". Fim de semana com fundo #f4f6f8. Sem plano: "Neste modo o sorteio é feito dia a dia." Os dias livres entram no meio, como na página Plano ("livre: escolha à mão", "escolher…"). Os dias vêm da API (hoje.proximos), de "Mostrar até" em "Mostrar até" (a Configuração, padrão 7); passando disso, embaixo o navegador de páginas (recurso=proximos com pagina; só a lista se remonta) e "Página N de M · <total> dias no plano, <n> por página (o "Mostrar até" da Configuração)." (link para configuracao.php). A página à mostra fica a mesma quando a página Hoje se remonta depois de uma gravação.' => 'Título "Próximos días" con el enlace "ver el plan entero →" (plano.php). Tabla: Día ("DD/MM" y el día de la semana corto, menor), Reloj (el nombre; "a mano" pequeño cuando se eligió a mano; el motivo debajo, menor), Recordatorio, y el "cambiar por…". Fin de semana con fondo #f4f6f8. Sin plan: "En este modo el sorteo se hace día a día." Los días libres entran en medio, como en la página Plan ("libre: elija a mano", "elegir…"). Los días vienen de la API (hoje.proximos), de "Mostrar hasta" en "Mostrar hasta" (la Configuración, por defecto 7); pasando de eso, debajo el navegador de páginas (recurso=proximos con pagina; solo se remonta la lista) y "Página N de M · <total> días en el plan, <n> por página (el \\"Mostrar hasta\\" de la Configuración)." (enlace a configuracao.php). La página a la vista se queda igual cuando la página Hoy se remonta después de un guardado.',
        '"trocar por…": uma lista com os relógios disponíveis (menos o do dia) e, num dia de amanhã em diante escolhido à mão, "↺ voltar a sortear" (valor 0); escolhido um, aparece o botão leve "Trocar" (rodizio trocar_dia com data e relogio_id).' => '"cambiar por…": una lista con los relojes disponibles (menos el del día) y, en un día de mañana en adelante elegido a mano, "↺ volver a sortear" (valor 0); elegido uno, aparece el botón leve "Cambiar" (rodizio trocar_dia con data y relogio_id).',
        'Modo de rodízio (um quadro que abre e fecha)' => 'Modo de rotación (un cuadro que se abre y se cierra)',
        'Fechado: "Modo de rodízio" (cinza) e o nome do modo em negrito, "· <forma de escolha>" (na escala: "pela maior nota") e, à direita, o link "editar".' => 'Cerrado: "Modo de rotación" (gris) y el nombre del modo en negrita, "· <forma de elección>" (en la escala: "por la mayor nota") y, a la derecha, el enlace "editar".',
        'Aberto, em duas colunas: à esquerda a lista "Modo de rodízio" (os modos), a explicação do modo escolhido (escala: "Monta o plano do período inteiro de uma vez..."; sorteio: "Cada bloco de dias sorteia entre os relógios do grupo escolhido...") e os campos do modo escolhido: na escala, "Período" (Uma semana, Um mês, Dois meses, Meio ano, Um ano, Dois anos = 7, 30, 60, 180, 365, 730); para cada bloco, uma lista com o nome do bloco (grupos "Sortear entre": Todos e cada grupo com recuo pela profundidade; "Relógio fixo": cada relógio disponível) e, fora da escala, a caixa "sortear um por dia".' => 'Abierto, en dos columnas: a la izquierda la lista "Modo de rotación" (los modos), la explicación del modo elegido (escala: "Monta el plan del período entero de una vez..."; sorteo: "Cada bloque de días sortea entre los relojes del grupo elegido...") y los campos del modo elegido: en la escala, "Período" (Una semana, Un mes, Dos meses, Medio año, Un año, Dos años = 7, 30, 60, 180, 365, 730); para cada bloque, una lista con el nombre del bloque (grupos "Sortear entre": Todos y cada grupo con sangría por la profundidad; "Reloj fijo": cada reloj disponible) y, fuera de la escala, la casilla "sortear uno por día".',
        'À direita: "Como escolher o relógio" (Inteligente; Inteligente com sorteio; Totalmente aleatório; Fila (FIFO)) com a explicação de cada uma (na escala, "Como escolher o relógio: pela maior nota"); "Garantia de rodízio: dias sem uso, no máximo" (número de 0 a 365; só nas formas inteligente, com sorteio e na escala) com "Quem passa do limite tem prioridade, o mais tempo parado primeiro. 0 desliga. O mesmo valor vale para todos os modos que usam a nota." e "A nota vem dos critérios, que você cadastra."' => 'A la derecha: "Cómo elegir el reloj" (Inteligente; Inteligente con sorteo; Totalmente aleatorio; Cola (FIFO)) con la explicación de cada una (en la escala, "Cómo elegir el reloj: por la mayor nota"); "Garantía de rotación: días sin uso, como máximo" (número de 0 a 365; solo en las formas inteligente, con sorteo y en la escala) con "Quien pasa del límite tiene prioridad, el que más tiempo parado primero. 0 la desactiva. El mismo valor vale para todos los modos que usan la nota." y "La nota viene de los criterios, que usted define."',
        'Botão "Aplicar modo" (rodizio modo), com a confirmação "Trocar o modo apaga o plano atual. Continuar?" (com o dia já começado: "Trocar o modo refaz o plano a partir de amanhã; hoje continua o <relógio>. Continuar?") e a nota sobre o histórico que continua e o link para Cadastros (os modos).' => 'Botón "Aplicar modo" (rodizio modo), con la confirmación "¿Cambiar el modo borra el plan actual. Continuar?" (con el día ya empezado: "¿Cambiar el modo rehace el plan a partir de mañana; hoy continúa el <reloj>. Continuar?") y la nota sobre el historial que continúa y el enlace a Definiciones (los modos).',
        '"Sortear de novo": uma lista com as ações possíveis agora e o botão leve "Sortear": "a partir de amanhã" (resortear) e "inclusive hoje" (resortear_hoje) com o dia já começado no pulso, ou "a partir de hoje" (resortear); fora da escala, "a próxima semana (DD/MM a DD/MM)" (proxima_semana; só no domingo: nos outros dias a opção vem desativada com "— disponível no domingo"). Embaixo, a explicação da opção escolhida; cada uma tem a sua confirmação.' => '"Sortear de nuevo": una lista con las acciones posibles ahora y el botón leve "Sortear": "a partir de mañana" (resortear) e "incluido hoy" (resortear_hoje) con el día ya empezado en la muñeca, o "a partir de hoy" (resortear); fuera de la escala, "la próxima semana (DD/MM a DD/MM)" (proxima_semana; solo el domingo: los demás días la opción viene desactivada con "— disponible el domingo"). Debajo, la explicación de la opción elegida; cada una tiene su confirmación.',
        'Rodízio manual: a última opção da lista "Modo de rodízio" (não é um modo: o modo de sempre continua valendo fora do período). Escolhida, a explicação diz "Você escolhe o relógio de cada dia de um período. Ponha o começo e o fim e clique em OK: os dias aparecem de 7 em 7, cada um com a lista dos relógios, "Decida por mim" (o sistema escolhe) e "Sem relógio (dia livre)". Fora do período, continua valendo o modo de rodízio de sempre (<modo>)."; somem a coluna da direita, o "Aplicar modo" com a nota e o "Sortear de novo"; aparece, abaixo de uma linha, o formulário do período: "De" (data, de hoje em diante, já com hoje), "Até" (data) e o botão "OK". O endereço index.php#manual abre o quadro já no Rodízio manual (o link da página Plano).' => 'Rotación manual: la última opción de la lista "Modo de rotación" (no es un modo: el modo de siempre sigue valiendo fuera del período). Elegida, la explicación dice "Usted elige el reloj de cada día de un período. Ponga el comienzo y el fin y pulse OK: los días aparecen de 7 en 7, cada uno con la lista de los relojes, \\"Decide por mí\\" (el sistema elige) y \\"Sin reloj (día libre)\\". Fuera del período, sigue valiendo el modo de rotación de siempre (<modo>)."; desaparecen la columna de la derecha, el "Aplicar modo" con la nota y el "Sortear de nuevo"; aparece, debajo de una línea, el formulario del período: "De" (fecha, de hoy en adelante, ya con hoy), "Hasta" (fecha) y el botón "OK". La dirección index.php#manual abre el cuadro ya en la Rotación manual (el enlace de la página Plan).',
        'OK lê recurso=rodizio_manual (de, ate, pagina) e mostra a tabela compacta (até 46rem): Dia ("DD/MM" e o dia da semana por extenso, menor, com " · hoje"; o número em safira no fim de semana), No plano agora (o relógio com "à mão" ou "sorteado" pequeno em âmbar, "dia livre" ou "—" em cinza) e Relógio do dia (uma lista: "Decida por mim", o grupo "Relógios" com os disponíveis por nome e, menos hoje, "Sem relógio (dia livre)"; de partida, a escolha que a API manda). Mais de 7 dias: embaixo, os botões leves "‹ Anterior", os números das páginas (a 1, a última e até 2 de cada lado da atual, com "…" nos saltos; a atual em safira) e "Próxima ›"; cada um relê a API. O que se escolhe fica guardado na tela ao trocar de página. Embaixo, "Página N de M · <n> dias, de DD/MM/AAAA a DD/MM/AAAA. O que você escolhe fica guardado enquanto você anda pelas páginas; nada muda antes de gravar.", os botões "Gravar o rodízio manual" (rodizio manual com de, ate e dias[data] dos que você mudou; confirma "Gravar o rodízio manual de DD/MM/AAAA a DD/MM/AAAA? Os dias ficam com os relógios escolhidos; os de "Decida por mim" são decididos agora pelo sistema."); e as notas com o critério do Decida por mim (o texto da API) e "Para apagar o que um período tem (e sortear de novo, ou deixar os dias livres): "Apagar um período", embaixo deste quadro, ou na página Plano." (link). Recusado: o motivo em âmbar acima da tabela, e as escolhas ficam; gravado: o recado no alto da página e a página remontada.' => 'OK lee recurso=rodizio_manual (de, ate, pagina) y muestra la tabla compacta (hasta 46rem): Día ("DD/MM" y el día de la semana por extenso, menor, con " · hoy"; el número en zafiro en el fin de semana), En el plan ahora (el reloj con "a mano" o "sorteado" pequeño en ámbar, "día libre" o "—" en gris) y Reloj del día (una lista: "Decide por mí", el grupo "Relojes" con los disponibles por nombre y, menos hoy, "Sin reloj (día libre)"; de partida, la elección que manda la API). Más de 7 días: debajo, los botones leve "‹ Anterior", los números de las páginas (la 1, la última y hasta 2 de cada lado de la actual, con "…" en los saltos; la actual en zafiro) y "Próxima ›"; cada uno relee la API. Lo que se elige queda guardado en la pantalla al cambiar de página. Debajo, "Página N de M · <n> días, de DD/MM/AAAA a DD/MM/AAAA. Lo que usted elige queda guardado mientras anda por las páginas; nada cambia antes de guardar.", los botones "Guardar la rotación manual" (rodizio manual con de, ate y dias[data] de los que usted cambió; confirma "¿Guardar la rotación manual de DD/MM/AAAA a DD/MM/AAAA? Los días quedan con los relojes elegidos; los de \\"Decide por mí\\" se deciden ahora por el sistema."); y las notas con el criterio del Decide por mí (el texto de la API) y "Para borrar lo que tiene un período (y sortear de nuevo, o dejar los días libres): \\"Borrar un período\\", debajo de este cuadro, o en la página Plan." (enlace). Rechazado: el motivo en ámbar encima de la tabla, y las elecciones se quedan; guardado: el mensaje en lo alto de la página y la página remontada.',
        'Abaixo do Sortear de novo, cada um abaixo de uma linha, os mesmos dois formulários da página Plano: "Apagar um período" e "Apagar tudo" (veja a página Plano).' => 'Debajo del Sortear de nuevo, cada uno debajo de una línea, los mismos dos formularios de la página Plan: "Borrar un período" y "Borrar todo" (vea la página Plan).',
        'Relógios (a tabela da coleção)' => 'Relojes (la tabla de la colección)',
        'Título "Relógios" com "<mostrados> de <total> relógios · <n> em uso" em cinza e, à direita, os botões "Limpar filtros" (leve) e "Novo relógio" (abre o cadastro no painel).' => 'Título "Relojes" con "<mostrados> de <total> relojes · <n> en uso" en gris y, a la derecha, los botones "Limpiar filtros" (leve) y "Reloj nuevo" (abre la ficha en el panel).',
        '12 colunas, todas ordenáveis clicando no título (▲ ou ▼ ao lado; clicar de novo inverte; vazios sempre por último): Código, Relógio (miniatura e nome em negrito), Tipo, Estado (o estado_texto da API em etiqueta, na cor do estado: Em uso verde, a sessão aberta (No sol, No winder, No carregador) laranja, Em repouso vermelho, Indisponível cinza), Carga (barra e %, ou o texto de por que não tem), Última vez usado, Próxima manutenção (data ou "hoje"), Em (quanto falta; atrasado em vermelho negrito; atualizado a cada minuto), O que fazer (em âmbar negrito; o aviso de manutenção mais perto, sem o Encostado), Encostado (quanto falta para o limite de dias sem ir ao pulso, ou "atrasado …" em vermelho negrito quando já passou; "—" sem data; atualizado a cada minuto), Comprado em, Valor (à direita, "R$ 1.234,56").' => '12 columnas, todas ordenables haciendo clic en el título (▲ o ▼ al lado; hacer clic de nuevo invierte; vacíos siempre al final): Código, Reloj (miniatura y nombre en negrita), Tipo, Estado (el estado_texto de la API en etiqueta, en el color del estado: En uso verde, la sesión abierta (Al sol, En el winder, En el cargador) naranja, En reposo rojo, No disponible gris), Carga (barra y %, o el texto de por qué no la tiene), Última vez usado, Próximo mantenimiento (fecha u "hoy"), En (cuánto falta; atrasado en rojo negrita; actualizado cada minuto), Qué hacer (en ámbar negrita; el aviso de mantenimiento más cercano, sin el Arrinconado), Arrinconado (cuánto falta para el límite de días sin ir a la muñeca, o "atrasado …" en rojo negrita cuando ya pasó; "—" sin fecha; actualizado cada minuto), Comprado el, Valor (a la derecha, "R$ 1.234,56").',
        'Uma linha de filtros embaixo dos títulos: Código ("nº"), Relógio ("buscar" no nome), Tipo (os tipos que existem), Estado (Todos e os estados da API, na ordem: Em uso, cada sessão, Em repouso, Indisponível), Carga (Todas, ≤ 20%, ≤ 50%), Última vez usado (Todos, 7 dias, +7 dias, nunca), Próxima manutenção (Todas, até hoje, 7 dias, 30 dias), O que fazer (os avisos de manutenção, sem o Encostado), Encostado (Todos, Encostados, Dentro do prazo, sem data), Comprado em (Todas, 30 dias, 90 dias, este ano, sem data), Valor (Todos, ≤ 500, 500–1.500, > 1.500, sem valor). A ordem e os filtros ficam guardados na sessão do navegador.' => 'Una fila de filtros debajo de los títulos: Código ("nº"), Reloj ("buscar" en el nombre), Tipo (los tipos que existen), Estado (Todos y los estados de la API, en orden: En uso, cada sesión, En reposo, No disponible), Carga (Todas, ≤ 20%, ≤ 50%), Última vez usado (Todos, 7 días, +7 días, nunca), Próximo mantenimiento (Todas, hasta hoy, 7 días, 30 días), Qué hacer (los avisos de mantenimiento, sin el Arrinconado), Arrinconado (Todos, Arrinconados, Dentro del plazo, sin fecha), Comprado el (Todas, 30 días, 90 días, este año, sin fecha), Valor (Todos, ≤ 500, 500–1.500, > 1.500, sin valor). El orden y los filtros quedan guardados en la sesión del navegador.',
        'Ordem inicial: os disponíveis primeiro (o de hoje, depois os com aviso), os indisponíveis no fim e em cinza. A linha do relógio de hoje tem a faixa safira à esquerda; a de um com aviso, a âmbar. Clicar numa linha (ou Enter nela) abre o relógio no painel. Rodapé: "Total dos relógios mostrados" e a soma dos valores, à direita. Sem relógios: "Nenhum relógio cadastrado. Use o botão Novo relógio."; com filtros que não deixam nenhum: "Nenhum relógio com esses filtros."' => 'Orden inicial: los disponibles primero (el de hoy, después los con aviso), los no disponibles al final y en gris. La fila del reloj de hoy tiene la franja zafiro a la izquierda; la de uno con aviso, la ámbar. Hacer clic en una fila (o Enter en ella) abre el reloj en el panel. Pie: "Total de los relojes mostrados" y la suma de los valores, a la derecha. Sin relojes: "Ningún reloj definido. Use el botón Reloj nuevo."; con filtros que no dejan ninguno: "Ningún reloj con esos filtros."',
        'Quando as 12 colunas não cabem na largura que a tabela tem: cada relógio vira um cartão, com a foto e o nome na linha de cima e embaixo os mesmos campos com o nome da coluna em cima, em colunas iguais (5; 2 no celular); os títulos viram botões "Ordenar por" e os filtros ficam todos, com o nome em cima.' => 'Cuando las 12 columnas no caben en la anchura que tiene la tabla: cada reloj se vuelve una tarjeta, con la foto y el nombre en la línea de arriba y debajo los mismos campos con el nombre de la columna arriba, en columnas iguales (5; 2 en el móvil); los títulos se vuelven botones "Ordenar por" y los filtros se quedan todos, con el nombre arriba.',
        'O painel do relógio (à direita, flutuante ou em tela cheia)' => 'El panel del reloj (a la derecha, flotante o a pantalla completa)',
        'Um botão redondo "×" no canto (no celular "× Fechar") fecha o painel; Esc também. O endereço vira index.php?r=<id>.' => 'Un botón redondo "×" en la esquina (en el móvil "× Cerrar") cierra el panel; Esc también. La dirección se vuelve index.php?r=<id>.',
        'Cabeça: a foto (ou "Sem foto"; com o mouse parado em cima, a dica relogio.dica_foto da API, em linhas: o nome, o grupo e o código; o estado e a carga; a nota e o próximo dia no rodízio; a compra; e "Duplo clique (ou "Abrir foto", embaixo): a foto em tamanho grande.") com os botões leves "Abrir foto" (só com foto: abre a foto ampliada), "Escolher foto" / "Trocar foto" (abre o seletor de arquivo; escolhida, aparece a prévia e o botão "Salvar foto": relogio foto) e, com foto, "Remover foto" (discreto; confirma "Remover a foto?"); ao lado "<tipo> · <caminho no grupo>" em cinza, o nome em h1, a observação, e as etiquetas: em uso/em repouso, "indisponível", "relógio de hoje" e, fora da coleção, a situação (etiqueta lilás: "desejado", "emprestado", "vendido", "arquivado"; no desejado, sem a etiqueta do estado).' => 'Cabecera: la foto (o "Sin foto"; con el ratón parado encima, la indicación relogio.dica_foto de la API, en líneas: el nombre, el grupo y el código; el estado y la carga; la nota y el próximo día en la rotación; la compra; y "Doble clic (o \\"Abrir foto\\", debajo): la foto en tamaño grande.") con los botones leve "Abrir foto" (solo con foto: abre la foto ampliada), "Elegir foto" / "Cambiar foto" (abre el selector de archivo; elegida, aparece la vista previa y el botón "Guardar foto": relogio foto) y, con foto, "Quitar foto" (discreto; confirma "¿Quitar la foto?"); al lado "<tipo> · <camino en el grupo>" en gris, el nombre en h1, la observación, y las etiquetas: en uso/en reposo, "no disponible", "reloj de hoy" y, fuera de la colección, la situación (etiqueta lila: "deseado", "prestado", "vendido", "archivado"; en el deseado, sin la etiqueta del estado).',
        'Num relógio desejado, no lugar dos quadros abaixo (Agora, Previsão, Gasto, Autonomia, Rodízio, Compra, Manutenções, Marcar), só o quadro Desejo (pares: Marca, Referência, Preço-alvo "R$ ...", Prioridade, Link "abrir a página" numa aba nova; vazio: "—"; no rodapé "Comprou? Em "Editar cadastro", mude a situação para "Na coleção" e preencha a compra.") e o de Documentos; os quadros largos (Dados, Histórico) e o Editar cadastro continuam.' => 'En un reloj deseado, en el lugar de los cuadros de abajo (Ahora, Previsión, Consumo, Autonomía, Rotación, Compra, Mantenimientos, Marcar), solo el cuadro Deseo (pares: Marca, Referencia, Precio objetivo "R$ ...", Prioridad, Enlace "abrir la página" en una pestaña nueva; vacío: "—"; en el pie "¿Lo compró? En \\"Editar ficha\\", cambie la situación a \\"En la colección\\" y rellene la compra.") y el de Documentos; los cuadros anchos (Datos, Historial) y el Editar ficha continúan.',
        'Os quadros, numa grade (lado a lado onde cabem): Agora (pares: Estado ("No carregador desde 06:30", na cor do estado); Carga com a barra e "~68%" e de onde vem; Encostado (a falta, em vermelho negrito se já passou do limite de dias sem ir ao pulso; só quando há data); Situação, uma linha por item; Última leitura); Previsão (só nos que têm leitura: as frases da API, ou "Informe a carga atual para o sistema começar a prever."; embaixo, "De onde vem a conta" (título pequeno em maiúsculas cinza) e a tabela da previsao.conta, uma linha por número: o nome (e, menor, embaixo, o detalhe de como o gasto foi medido), o valor (com a unidade menor embaixo; "—" se vazio, a linha em cinza) e a origem em etiqueta: informado azul, padrão âmbar, medido verde, vazio cinza); Gasto da bateria (No pulso, Fora do pulso: o que vale "% por dia" e embaixo se é medido ou do cadastro; Janela anterior; Medições; no rodapé "Medições mais velhas que a janela saem da conta..."); Autonomia (Cheio, pelo cadastro; Cheio, pela conta; Acaba, seguindo o plano (data e hora, e "em <duração>"); No pulso sem tirar; Guardado; sem dado, o motivo em cinza); Rodízio (Nota com o link "ver a conta" (Critérios, numa aba nova); Critérios de; Próxima vez; no rodapé o botão leve "Usando hoje" (rodizio usando, com confirmação), se ele está disponível e não é o de hoje); Compra (Valor pago, Loja, Comprado em com "há N dias", Garantia "até" ou "vencida em"; sem nada: "Sem dados da compra. Preencha em "Editar cadastro"."); Compra também com "Custo por uso" ("R$ 100,00" em negrito e "3 dias de uso" embaixo; sem: "sem o valor pago" ou "ainda não foi ao pulso" em cinza) e o "há N dias" da compra vindo da API (compra.ha_dias). Documentos (cada categoria com "N arquivos", link para a página Documentos numa aba nova; o botão "Enviar documentos" ou "Abrir os documentos"); Próximas manutenções (data em negrito e o nome; ou "Nada previsto."). Depois de Documentos, Acessórios (pares: o tipo e o nome, com a observação menor embaixo; sem nenhum, "Nenhum: a pulseira extra, a caixa, o estojo, a ferramenta..."; o botão leve "Cadastrar acessórios" ou "Ver os acessórios", que abre acessorios.php?relogio=<id> numa aba nova). No rodapé de Documentos, ao lado do botão dele, o botão leve "Passaporte" (passaporte.php?id=<id> numa aba nova).' => 'Los cuadros, en una cuadrícula (lado a lado donde caben): Ahora (pares: Estado ("En el cargador desde 06:30", en el color del estado); Carga con la barra y "~68%" y de dónde viene; Arrinconado (la falta, en rojo negrita si ya pasó del límite de días sin ir a la muñeca; solo cuando hay fecha); Situación, una línea por elemento; Última lectura); Previsión (solo en los que tienen lectura: las frases de la API, o "Informe la carga actual para que el sistema empiece a prever."; debajo, "De dónde viene la cuenta" (título pequeño en mayúsculas gris) y la tabla de previsao.conta, una línea por número: el nombre (y, menor, debajo, el detalle de cómo se midió el consumo), el valor (con la unidad menor debajo; "—" si está vacío, la línea en gris) y el origen en etiqueta: informado azul, predeterminado ámbar, medido verde, vacío gris); Consumo de la batería (En la muñeca, Fuera de la muñeca: lo que vale "% por día" y debajo si es medido o de la ficha; Ventana anterior; Mediciones; en el pie "Las mediciones más viejas que la ventana salen de la cuenta..."); Autonomía (Lleno, por la ficha; Lleno, por la cuenta; Se acaba, siguiendo el plan (fecha y hora, y "en <duración>"); En la muñeca sin quitar; Guardado; sin dato, el motivo en gris); Rotación (Nota con el enlace "ver la cuenta" (Criterios, en una pestaña nueva); Criterios de; Próxima vez; en el pie el botón leve "Llevándolo hoy" (rodizio usando, con confirmación), si está disponible y no es el de hoy); Compra (Valor pagado, Tienda, Comprado el con "hace N días", Garantía "hasta" o "vencida el"; sin nada: "Sin datos de la compra. Rellénelos en \\"Editar ficha\\"."); Compra también con "Costo por uso" ("R$ 100,00" en negrita y "3 días de uso" debajo; sin: "sin el valor pagado" o "aún no fue a la muñeca" en gris) y el "hace N días" de la compra que viene de la API (compra.ha_dias). Documentos (cada categoría con "N archivos", enlace a la página Documentos en una pestaña nueva; el botón "Enviar documentos" o "Abrir los documentos"); Próximos mantenimientos (fecha en negrita y el nombre; o "Nada previsto."). Después de Documentos, Accesorios (pares: el tipo y el nombre, con la observación menor debajo; sin ninguno, "Ninguno: la correa de más, la caja, el estuche, la herramienta..."; el botón leve "Definir accesorios" o "Ver los accesorios", que abre acessorios.php?relogio=<id> en una pestaña nueva). En el pie de Documentos, al lado de su botón, el botón leve "Pasaporte" (passaporte.php?id=<id> en una pestaña nueva).',
        'Marcar (um quadro na largura toda): "O que você quer marcar?" com uma lista em grupos: "Agora, ou numa hora que você disser" (cada sessão como verbo: "Pôr no sol" / "Tirar do sol" conforme está aberta; cada tipo com valor pelo nome; cada instantâneo pelo nome), "Algo que já passou" ("Um período que já passou (<sessões>)") e "Corrigir" ("Corrigir ou excluir uma marcação (últimos 14 dias)"). Escolhido um, aparecem só os campos dele: sessão: o estado aberto e "Pôs às" / "Tirou às" (data e hora, "Anda com o relógio até você mudar (vazio: agora).") e o botão com o verbo; com valor: "Agora em uso/em repouso" e a estimativa, "Leitura" (com a unidade), "Lida às", a caixa "Atualizar o gasto com esta medição" (marcada; só nos tipos que medem o gasto) e "Informar <nome>"; instantâneo: "Quando" e "Marcar <nome>"; período: "Onde" (se houver mais de uma sessão), "De" (uma hora atrás) e "Até" (agora) e "Registrar o período"; corrigir: "Qual marcação" ("DD/MM HH:MM · nome até HH:MM", "(aberta)", ": 68 %", "(rodízio)") e os campos dela com "Salvar" e "Excluir" (confirma). Nada pode ser no futuro. Os campos de data e hora andam com o relógio do navegador: "Pôs às", "Tirou às", "Lida às", "Quando" e o "Até" do período vêm com a hora de agora e acompanham o relógio (a cada 15 s e ao clicar no campo) até a pessoa mexer, e daí ficam no que ela pôs; sem mexer, "Pôs às", "Tirou às", "Lida às" e "Quando" vão vazios (a API usa o agora dela, com os segundos) e o "Até" vai com o minuto de agora; o máximo de todos (nada no futuro) também anda.' => 'Marcar (un cuadro en toda la anchura): "¿Qué quiere marcar?" con una lista en grupos: "Ahora, o a una hora que usted diga" (cada sesión como verbo: "Poner al sol" / "Quitar del sol" según esté abierta; cada tipo con valor por el nombre; cada instantáneo por el nombre), "Algo que ya pasó" ("Un período que ya pasó (<sesiones>)") y "Corregir" ("Corregir o eliminar una marca (últimos 14 días)"). Elegido uno, aparecen solo sus campos: sesión: el estado abierto y "Me lo puse a las" / "Me lo quité a las" (fecha y hora, "Avanza con el reloj hasta que usted lo cambie (vacío: ahora).") y el botón con el verbo; con valor: "Ahora en uso/en reposo" y la estimación, "Lectura" (con la unidad), "Leída a las", la casilla "Actualizar el consumo con esta medición" (marcada; solo en los tipos que miden el consumo) e "Informar <nombre>"; instantáneo: "Cuándo" y "Marcar <nombre>"; período: "Dónde" (si hay más de una sesión), "De" (una hora atrás) y "Hasta" (ahora) y "Registrar el período"; corregir: "Qué marca" ("DD/MM HH:MM · nombre hasta HH:MM", "(abierta)", ": 68 %", "(rotación)") y sus campos con "Guardar" y "Eliminar" (confirma). Nada puede ser en el futuro. Los campos de fecha y hora avanzan con el reloj del navegador: "Me lo puse a las", "Me lo quité a las", "Leída a las", "Cuándo" y el "Hasta" del período vienen con la hora de ahora y acompañan el reloj (cada 15 s y al hacer clic en el campo) hasta que la persona lo toque, y a partir de ahí se quedan en lo que ella puso; sin tocarlo, "Me lo puse a las", "Me lo quité a las", "Leída a las" y "Cuándo" van vacíos (la API usa su ahora, con los segundos) y el "Hasta" va con el minuto de ahora; el máximo de todos (nada en el futuro) también avanza.',
        'Editar cadastro (um quadro que abre e fecha; no relógio novo, já aberto com o título "Novo relógio"): Nome (obrigatório); Grupo ("(na raiz)" e cada grupo pelo caminho, com a nota "os campos, os lançamentos e os critérios de um grupo valem para tudo abaixo dele"); depois os campos do cadastro, só os que valem para o grupo escolhido (mudar o grupo mostra e esconde na hora): sim/não como caixa; lista como menu (com "—"); data como campo de data; texto como campo; número como campo decimal, com o padrão de dica ("vazio: 5"); a Compra num grupo com título (Data da compra, Valor pago, Onde comprou, Garantia até); a Observação; no novo, a Foto; "Situação na coleção" (menu: Na coleção, Desejado, Emprestado, Vendido, Arquivado; no novo, a do endereço, index.php?novo=1&posse=desejado, senão Na coleção; os campos só nos desejados, como o Preço-alvo e a Prioridade, aparecem só com Desejado, e a caixa do disponível só com Na coleção, na hora); "Disponível para o rodízio" (marcada no novo); "Guardar no banco a cópia de todos os documentos dele" (só quando o config.php não decide); botão "Cadastrar relógio" ou "Salvar alterações" (relogio salvar). Embaixo, "Excluir este relógio" (discreto; confirma "Excluir <nome> com todo o histórico e a foto?").' => 'Editar ficha (un cuadro que se abre y se cierra; en el reloj nuevo, ya abierto con el título "Reloj nuevo"): Nombre (obligatorio); Grupo ("(en la raíz)" y cada grupo por el camino, con la nota "los campos, los registros y los criterios de un grupo valen para todo lo que está debajo de él"); después los campos de la ficha, solo los que valen para el grupo elegido (cambiar el grupo muestra y oculta en el momento): sí/no como casilla; lista como menú (con "—"); fecha como campo de fecha; texto como campo; número como campo decimal, con el predeterminado de indicación ("vacío: 5"); la Compra en un grupo con título (Fecha de la compra, Valor pagado, Dónde lo compró, Garantía hasta); la Observación; en el nuevo, la Foto; "Situación en la colección" (menú: En la colección, Deseado, Prestado, Vendido, Archivado; en el nuevo, la de la dirección, index.php?novo=1&posse=desejado, si no En la colección; los campos solo en los deseados, como el Precio objetivo y la Prioridad, aparecen solo con Deseado, y la casilla del disponible solo con En la colección, en el momento); "Disponible para la rotación" (marcada en el nuevo); "Guardar en la base de datos la copia de todos sus documentos" (solo cuando el config.php no decide); botón "Registrar reloj" o "Guardar cambios" (relogio salvar). Debajo, "Eliminar este reloj" (discreto; confirma "¿Eliminar <nombre> con todo el historial y la foto?").',
        'Carga ao longo do tempo (largo; nos que têm leitura): um gráfico de linha das leituras (eixo de 0 a 100%, guias em 0, 50 e 100%, pontos verdes em uso e vermelhos em repouso, a linha em safira), com a legenda em pares rótulo/valor, menores (Pontos: as bolinhas "leitura em uso" e "leitura em repouso"; Período: "DD/MM a DD/MM"; Escala: "de 0 a 100%"; A conta: "de onde vem cada número: no quadro Previsão"); com menos de duas leituras, "O gráfico aparece a partir de duas leituras de carga." Embaixo, "Medições do gasto" (no quadro estreito, até 40rem, como no painel ao lado: cada medição vira um cartão, a data em negrito e embaixo cada valor com o nome da coluna em maiúsculas cinza na frente): tabela Quando, Leituras ("89 → 75"), Horas ("14 h no pulso, 2 h fora"), Gasto medido ("% por dia de uso" ou "fora do pulso"), Na conta (sim; não (fora da janela); não (só histórico)), as 10 mais recentes.' => 'Carga a lo largo del tiempo (ancho; en los que tienen lectura): un gráfico de línea de las lecturas (eje de 0 a 100%, guías en 0, 50 y 100%, puntos verdes en uso y rojos en reposo, la línea en zafiro), con la leyenda en pares rótulo/valor, menores (Puntos: las bolitas "lectura en uso" y "lectura en reposo"; Período: "DD/MM a DD/MM"; Escala: "de 0 a 100%"; La cuenta: "de dónde viene cada número: en el cuadro Previsión"); con menos de dos lecturas, "El gráfico aparece a partir de dos lecturas de carga." Debajo, "Mediciones del consumo" (en el cuadro estrecho, hasta 40rem, como en el panel al lado: cada medición se vuelve una tarjeta, la fecha en negrita y debajo cada valor con el nombre de la columna en mayúsculas gris delante): tabla Cuándo, Lecturas ("89 → 75"), Horas ("14 h en la muñeca, 2 h fuera"), Consumo medido ("% por día de uso" o "fuera de la muñeca"), En la cuenta (sí; no (fuera de la ventana); no (solo historial)), las 10 más recientes.',
        'Dados do relógio (largo): duas tabelas lado a lado (o valor numérico, a data e o sim/não numa linha só; o valor de texto, como a observação ou uma fórmula que dá texto, quebra a linha dentro da coluna, sem invadir a tabela do lado): Cadastro (Campo, Valor, Origem com a etiqueta informado/padrão/vazio) e Calculado agora (Fórmula com o identificador em código, Valor com a unidade (segundos por extenso), Versão).' => 'Datos del reloj (ancho): dos tablas lado a lado (el valor numérico, la fecha y el sí/no en una sola línea; el valor de texto, como la observación o una fórmula que da texto, parte la línea dentro de la columna, sin invadir la tabla de al lado): Ficha (Campo, Valor, Origen con la etiqueta informado/predeterminado/vacío) y Calculado ahora (Fórmula con el identificador en código, Valor con la unidad (segundos por extenso), Versión).',
        'Histórico (largo): "<n> registros desde DD/MM/AAAA HH:MM. Agora <estado> há <duração>." e a tabela das 5 linhas mais recentes (Quando com "até ..." embaixo, Duração, Estado em etiqueta ou o texto da marcação) e o botão leve "Abrir o histórico completo" (historico.php numa aba nova).' => 'Historial (ancho): "<n> registros desde DD/MM/AAAA HH:MM. Ahora <estado> desde hace <duración>." y la tabla de las 5 líneas más recientes (Cuándo con "hasta ..." debajo, Duración, Estado en etiqueta o el texto de la marca) y el botón leve "Abrir el historial completo" (historico.php en una pestaña nueva).',
        'Depois de gravar no painel, o recado aparece no topo do painel e a página e o painel se remontam sem perder os quadros abertos nem a rolagem; excluir o relógio recarrega a página.' => 'Después de guardar en el panel, el mensaje aparece en lo alto del panel y la página y el panel se remontan sin perder los cuadros abiertos ni el desplazamiento; eliminar el reloj recarga la página.',
        'Ficha do relógio' => 'Ficha del reloj',
        'ficha.php?id=<id> (sem id: o primeiro)' => 'ficha.php?id=<id> (sin id: el primero)',
        'recurso=hoje (a lista)' => 'recurso=hoje (la lista)',
        'as mesmas do painel do relógio' => 'las mismas del panel del reloj',
        'Escolha e painel' => 'Elección y panel',
        'No alto, "Relógio" e uma lista com todos (os disponíveis primeiro, o estado entre parênteses nos outros: "(indisponível)", "(emprestado)"); havendo relógios fora da coleção, a lista vem em dois grupos, "Na coleção" e "Fora da coleção" (cada um com a situação: "(desejado)", "(vendido)", "(arquivado)"); trocar abre o escolhido. Embaixo, o mesmo painel do relógio da página Hoje, numa página própria de até 72rem, com os quadros lado a lado e sem o ×. Sem relógios: "Nenhum relógio cadastrado. Cadastre o primeiro." (link para index.php?novo=1).' => 'Arriba, "Reloj" y una lista con todos (los disponibles primero, el estado entre paréntesis en los demás: "(no disponible)", "(prestado)"); habiendo relojes fuera de la colección, la lista viene en dos grupos, "En la colección" y "Fuera de la colección" (cada uno con la situación: "(deseado)", "(vendido)", "(archivado)"); cambiar abre el elegido. Debajo, el mismo panel del reloj de la página Hoy, en una página propia de hasta 72rem, con los cuadros lado a lado y sin el ×. Sin relojes: "Ningún reloj definido. Defina el primero." (enlace a index.php?novo=1).',
        'relogio: salvar (id e posse=colecao: o Comprei e o Voltar para a coleção)' => 'relogio: salvar (id y posse=colecao: el Lo compré y el Volver a la colección)',
        'Lista de desejos' => 'Lista de deseos',
        'h1 "Lista de desejos" com o botão "Novo desejo" à direita (index.php?novo=1&posse=desejado: o cadastro de um relógio novo já como Desejado). A nota: sem desejados, como um relógio entra na lista ("Novo desejo" ou a "Situação na coleção" do cadastro) e que ele não entra no rodízio nem nos avisos; com desejados, "<n> relógios desejados, a prioridade mais alta primeiro. Somando os preços-alvo: R$ <total> (<n> sem preço-alvo). Comprou? ...".' => 'h1 "Lista de deseos" con el botón "Deseo nuevo" a la derecha (index.php?novo=1&posse=desejado: la ficha de un reloj nuevo ya como Deseado). La nota: sin deseados, cómo entra un reloj en la lista ("Deseo nuevo" o la "Situación en la colección" de la ficha) y que no entra en la rotación ni en los avisos; con deseados, "<n> relojes deseados, la prioridad más alta primero. Sumando los precios objetivo: R$ <total> (<n> sin precio objetivo). ¿Lo compró? ...".',
        'Tabela (vira fichas até 900px) Relógio (a miniatura, o nome com o link da ficha e, embaixo, menor, "marca · referência"), Prioridade, Preço-alvo ("R$ 1.234,56" ou —), Grupo (o caminho; — na raiz), Link ("abrir a página" numa aba nova, só para http:// e https://; outro texto, como está; —) e o botão leve "Comprei" (confirma "Comprou o <nome>? Ele entra na coleção, disponível para o rodízio, e a ficha dele abre para você preencher a compra."; gravado, abre ficha.php?id=<id>).' => 'Tabla (se vuelve fichas hasta 900px) Reloj (la miniatura, el nombre con el enlace de la ficha y, debajo, menor, "marca · referencia"), Prioridad, Precio objetivo ("R$ 1.234,56" o —), Grupo (el camino; — en la raíz), Enlace ("abrir la página" en una pestaña nueva, solo para http:// y https://; otro texto, como está; —) y el botón leve "Lo compré" (confirma "¿Compró el <nombre>? Entra en la colección, disponible para la rotación, y su ficha se abre para que usted rellene la compra."; guardado, abre ficha.php?id=<id>).',
        'Fora da coleção' => 'Fuera de la colección',
        'h2 "Fora da coleção", a nota (fora do rodízio, do plano e dos avisos; o emprestado continua na tabela da página Hoje e no valor da coleção; a ficha, os documentos e o histórico ficam) e a tabela Relógio (miniatura e nome), Situação (etiqueta lilás: emprestado, vendido, arquivado), Grupo e o botão leve "Voltar para a coleção" (confirma; gravado, abre a ficha).' => 'h2 "Fuera de la colección", la nota (fuera de la rotación, del plan y de los avisos; el prestado sigue en la tabla de la página Hoy y en el valor de la colección; la ficha, los documentos y el historial se quedan) y la tabla Reloj (miniatura y nombre), Situación (etiqueta lila: prestado, vendido, archivado), Grupo y el botón leve "Volver a la colección" (confirma; guardado, abre la ficha).',
        'Na página Hoje, ao lado do "Novo relógio", o botão leve "Desejos (<n>) · Fora da coleção (<n>)" (só as partes que têm algum; sem nenhum, o botão some) leva a esta página.' => 'En la página Hoy, al lado del "Reloj nuevo", el botón leve "Deseos (<n>) · Fuera de la colección (<n>)" (solo las partes que tienen alguno; sin ninguno, el botón desaparece) lleva a esta página.',
        'estatisticas.php?de=AAAA-MM-DD&ate=AAAA-MM-DD (de=tudo: desde o primeiro uso; sem nada: os últimos 90 dias)' => 'estatisticas.php?de=AAAA-MM-DD&ate=AAAA-MM-DD (de=tudo: desde el primer uso; sin nada: los últimos 90 días)',
        'Período e resumo' => 'Período y resumen',
        'h1 "Estatísticas" com "de DD/MM/AAAA a DD/MM/AAAA · N dias" em cinza à direita. Filtro num cartão: De, Até (máximo hoje), "Ver" e os atalhos 30 dias, 90 dias, 1 ano, desde o começo.' => 'h1 "Estadísticas" con "de DD/MM/AAAA a DD/MM/AAAA · N días" en gris a la derecha. Filtro en una tarjeta: De, Hasta (máximo hoy), "Ver" y los atajos 30 días, 90 días, 1 año, desde el principio.',
        'Quatro caixas (duas por linha até 900px): "<n>" dias com relógio no pulso (de <dias>); "<h> h" no pulso · <h> h por dia com relógio; "<usados> de <coleção>" relógios usados · <n> sem uso; "R$ <custo médio>" custo por uso, em média · coleção: R$ <valor>. Embaixo, "Mais usado: <link> (<h> h, <n> dias). Menos usado (dos que foram ao pulso): <link> (<h> h)."' => 'Cuatro cajas (dos por línea hasta 900px): "<n>" días con reloj en la muñeca (de <días>); "<h> h" en la muñeca · <h> h por día con reloj; "<usados> de <colección>" relojes usados · <n> sin uso; "R$ <costo medio>" costo por uso, de media · colección: R$ <valor>. Debajo, "Más usado: <enlace> (<h> h, <n> días). Menos usado (de los que fueron a la muñeca): <enlace> (<h> h)."',
        'Cada relógio' => 'Cada reloj',
        'Cartão com a nota do que cada coluna é e a tabela (fichas até 900px) Relógio (o link da ficha e, embaixo, menor, o grupo e a situação fora da coleção), Dias de uso, Horas ("12,5 h"), A parte (a barra horizontal safira com a largura relogios[].barra e "56,8%"), Custo por uso ("R$ 83,30" ou —), Sem uso há ("3 dias", "usado hoje", "nunca usado"), Tendência ("↑ usando mais" em verde, "↓ usando menos" em vermelho, "→ estável", "· poucos dados" em cinza; a dica com as horas de cada metade).' => 'Tarjeta con la nota de lo que es cada columna y la tabla (fichas hasta 900px) Reloj (el enlace de la ficha y, debajo, menor, el grupo y la situación fuera de la colección), Días de uso, Horas ("12,5 h"), La parte (la barra horizontal zafiro con la anchura relogios[].barra y "56,8%"), Costo por uso ("R$ 83,30" o —), Sin uso desde hace ("3 días", "usado hoy", "nunca usado"), Tendencia ("↑ usando más" en verde, "↓ usando menos" en rojo, "→ estable", "· pocos datos" en gris; la indicación con las horas de cada mitad).',
        'Gráficos' => 'Gráficos',
        'Dois cartões lado a lado (um embaixo do outro até 900px): Por dia da semana e Por mês, cada um um gráfico de barras verticais em SVG (largura 100%, as barras safira com a altura da barra da API, o valor "14 h" em cima de cada uma quando são até 8, os rótulos embaixo: seg...dom, set/26..., no máximo uns 7 rótulos) e a nota com os números (a média por dia de cada dia da semana; as horas e quantos relógios em cada mês).' => 'Dos tarjetas lado a lado (una debajo de la otra hasta 900px): Por día de la semana y Por mes, cada uno un gráfico de barras verticales en SVG (anchura 100%, las barras zafiro con la altura de la barra de la API, el valor "14 h" encima de cada una cuando son hasta 8, los rótulos debajo: lun...dom, sep/26..., como máximo unos 7 rótulos) y la nota con los números (la media por día de cada día de la semana; las horas y cuántos relojes en cada mes).',
        'A coleção' => 'La colección',
        'Cartão com a nota e as divisões em grade (lado a lado onde cabem, cada uma com pelo menos 22rem): h3 com o título e a tabela nome, "<n> relógios", a barra com a porcentagem e as horas; numa divisão estreita (até 26rem), cada linha em duas: o nome em negrito em cima e os números embaixo.' => 'Tarjeta con la nota y las divisiones en cuadrícula (lado a lado donde caben, cada una con al menos 22rem): h3 con el título y la tabla nombre, "<n> relojes", la barra con el porcentaje y las horas; en una división estrecha (hasta 26rem), cada línea en dos: el nombre en negrita arriba y los números debajo.',
        'recurso=hora_certa (ao abrir e a cada minuto)' => 'recurso=hora_certa (al abrir y cada minuto)',
        'O relógio' => 'El reloj',
        'h1 "Hora certa" com "<fuso> · UTC<deslocamento>" em cinza. Um cartão com o mostrador em SVG (até 15rem: caixa branca de borda escura, 60 marcas, as das horas grossas; ponteiros das horas e dos minutos escuros e arredondados, o dos segundos vermelho fino, o eixo vermelho) e ao lado (embaixo, no celular) a hora digital grande (HH:MM:SS, números de largura fixa), a data por extenso, a hora UTC em cinza e a nota "O relógio deste aparelho está certo (menos de meio segundo de diferença)." ou "... está <n> s adiantado/atrasado." e de onde vem a hora.' => 'h1 "Hora exacta" con "<huso> · UTC<desplazamiento>" en gris. Una tarjeta con la esfera en SVG (hasta 15rem: caja blanca de borde oscuro, 60 marcas, las de las horas gruesas; agujas de las horas y de los minutos oscuras y redondeadas, la de los segundos roja fina, el eje rojo) y al lado (debajo, en el móvil) la hora digital grande (HH:MM:SS, números de anchura fija), la fecha por extenso, la hora UTC en gris y la nota "El reloj de este aparato está en hora (menos de medio segundo de diferencia)." o "... está <n> s adelantado/atrasado." y de dónde viene la hora.',
        'O relógio da página: a diferença é agora_ms menos o meio do pedido (antes e depois); a cada virada de segundo do relógio acertado, os ponteiros e a hora digital andam (no fuso.segundos da API); a cada minuto, lê a API de novo.' => 'El reloj de la página: la diferencia es agora_ms menos la mitad de la petición (antes y después); a cada cambio de segundo del reloj puesto en hora, las agujas y la hora digital avanzan (en el fuso.segundos de la API); cada minuto, lee la API de nuevo.',
        'Os quadros' => 'Los cuadros',
        'Três cartões lado a lado (um embaixo do outro até 900px), com pares rótulo/valor: Fuso e UTC (Fuso com a abreviação, Deslocamento, UTC (Zulu), Letra militar "P (Papa)", Grupo data-hora local e Zulu em código, ISO 8601), Calendário (Hoje, Dia do ano "286 de 365 · faltam 79", Semana (ISO), Trimestre, Dia juliano, Unix) e Lua (Fase com o símbolo, Idade, Iluminada, Próxima cheia, Próxima nova e a nota do ciclo médio). Embaixo, o cartão Como acertar com o texto da API.' => 'Tres tarjetas lado a lado (una debajo de la otra hasta 900px), con pares rótulo/valor: Huso y UTC (Huso con la abreviatura, Desplazamiento, UTC (Zulu), Letra militar "P (Papa)", Grupo fecha-hora local y Zulu en código, ISO 8601), Calendario (Hoy, Día del año "286 de 365 · faltan 79", Semana (ISO), Trimestre, Día juliano, Unix) y Luna (Fase con el símbolo, Edad, Iluminada, Próxima llena, Próxima nueva y la nota del ciclo medio). Debajo, la tarjeta Cómo ponerlo en hora con el texto de la API.',
        'acessorios.php?relogio=<id> (0: os soltos; sem ele: todos)&editar=<id do acessório>' => 'acessorios.php?relogio=<id> (0: los sueltos; sin él: todos)&editar=<id del accesorio>',
        'recurso=acessorios (com relogio)' => 'recurso=acessorios (con relogio)',
        'acessorios: salvar, excluir' => 'acessorios: salvar, excluir',
        'Lista e cadastro' => 'Lista y ficha',
        'h1 "Acessórios" com "<n> acessórios [do <relógio> | soltos] · 1 pulseira, 2 caixas..." em cinza. Um cartão com o filtro Relógio (Todos, Soltos (de nenhum relógio) e cada relógio; trocar abre o filtrado).' => 'h1 "Accesorios" con "<n> accesorios [del <reloj> | sueltos] · 1 correa, 2 cajas..." en gris. Una tarjeta con el filtro Reloj (Todos, Sueltos (de ningún reloj) y cada reloj; cambiar abre el filtrado).',
        'Tabela (fichas até 900px) Acessório, Tipo, Relógio (o link da ficha, ou "solto" em cinza), Observação (cinza; —) e as ações Editar (link: editar=<id>#form) e Excluir (botão leve discreto; confirma "Excluir o acessório <nome>?"). Vazia: "Nenhum acessório. Cadastre abaixo."' => 'Tabla (fichas hasta 900px) Accesorio, Tipo, Reloj (el enlace de la ficha, o "suelto" en gris), Observación (gris; —) y las acciones Editar (enlace: editar=<id>#form) y Eliminar (botón leve discreto; confirma "¿Eliminar el accesorio <nombre>?"). Vacía: "Ningún accesorio. Defínalo abajo."',
        'Cartão Novo acessório (ou "Alterar <nome>", que a página rola até ele), em grade: Nome (obrigatório, até 120, a dica "Pulseira de couro marrom"), Tipo (Pulseira, Caixa, Estojo, Ferramenta, Carregador, Peça, Outro), Relógio ("— solto (serve a vários) —" e cada relógio; no novo, o do filtro), Observação (texto, até 1000) e "Cadastrar" ou "Salvar" e "cancelar". Gravou: volta à lista, com o mesmo filtro; recusou: o alerta com os erros.' => 'Tarjeta Accesorio nuevo (o "Modificar <nombre>", hasta la que la página se desplaza), en cuadrícula: Nombre (obligatorio, hasta 120, la indicación "Correa de cuero marrón"), Tipo (Correa, Caja, Estuche, Herramienta, Cargador, Pieza, Otro), Reloj ("— suelto (sirve a varios) —" y cada reloj; en el nuevo, el del filtro), Observación (texto, hasta 1000) y "Registrar" o "Guardar" y "cancelar". Guardó: vuelve a la lista, con el mismo filtro; rechazó: la alerta con los errores.',
        'galeria.php (posse=todos: também os de fora da coleção)' => 'galeria.php (posse=todos: también los de fuera de la colección)',
        'Fotos por grupo' => 'Fotos por grupo',
        'Uma barra com o botão "Imprimir" (window.print) e o leve "Também os de fora da coleção" / "Só a coleção". h1 "Galeria" com "<n> relógios · R$ <valor> · <n> com foto" em cinza. Um cartão por grupo (h2 com o caminho) com a grade das fotos (colunas de pelo menos 9rem: duas no celular): a foto quadrada (ou o quadrado "Sem foto"), com o link da ficha, e embaixo o nome em negrito, "marca · referência" e, menor, "ano · R$ valor · <n> dias de uso" em cinza, e a etiqueta lilás da situação fora da coleção. No pé, "Gerado em ... pelo Relojoeiro." No papel (@media print): sem o menu e sem a barra, fundo branco, quatro fotos por linha, nenhuma partida entre páginas.' => 'Una barra con el botón "Imprimir" (window.print) y el leve "También los de fuera de la colección" / "Solo la colección". h1 "Galería" con "<n> relojes · R$ <valor> · <n> con foto" en gris. Una tarjeta por grupo (h2 con el camino) con la cuadrícula de las fotos (columnas de al menos 9rem: dos en el móvil): la foto cuadrada (o el cuadrado "Sin foto"), con el enlace de la ficha, y debajo el nombre en negrita, "marca · referencia" y, menor, "año · R$ valor · <n> días de uso" en gris, y la etiqueta lila de la situación fuera de la colección. Al pie, "Generado el ... por Relojoeiro." En el papel (@media print): sin el menú y sin la barra, fondo blanco, cuatro fotos por línea, ninguna partida entre páginas.',
        'Passaporte do relógio' => 'Pasaporte del reloj',
        'A ficha para imprimir' => 'La ficha para imprimir',
        'Uma barra com "Imprimir", o leve "Voltar para a ficha" e a nota de que no papel saem só os dados. A cabeça: a foto (9rem), "Passaporte do relógio · código N", o nome em h1, "marca · referência · caminho", a situação ("Na coleção · no rodízio · no sistema desde DD/MM/AAAA") e a observação.' => 'Una barra con "Imprimir", el leve "Volver a la ficha" y la nota de que en el papel salen solo los datos. La cabecera: la foto (9rem), "Pasaporte del reloj · código N", el nombre en h1, "marca · referencia · camino", la situación ("En la colección · en la rotación · en el sistema desde DD/MM/AAAA") y la observación.',
        'Cartões (largura até 60rem; os pares lado a lado onde cabem, um embaixo do outro até 700px): Compra e Uso; Cadastro (os valores já em texto); Manutenções (cada tipo: "<n> vezes · a última em DD/MM/AAAA", e a lista das revisões e trocas de pilha); Acessórios e Documentos; Próximos avisos. Vazios: "Sem dados da compra.", "Ainda não foi ao pulso.", "Nada preenchido.", "Nenhuma marcação.", "Nenhum." No pé, "Gerado em ...". No papel: só os cartões, nenhum partido entre páginas.' => 'Tarjetas (anchura hasta 60rem; los pares lado a lado donde caben, uno debajo del otro hasta 700px): Compra y Uso; Ficha (los valores ya en texto); Mantenimientos (cada tipo: "<n> veces · la última el DD/MM/AAAA", y la lista de las revisiones y cambios de pila); Accesorios y Documentos; Próximos avisos. Vacíos: "Sin datos de la compra.", "Aún no fue a la muñeca.", "Nada rellenado.", "Ninguna marca.", "Ninguno." Al pie, "Generado el ...". En el papel: solo las tarjetas, ninguna partida entre páginas.',
        'recurso=plano (com dias=30, 90, 365, 730 ou todos; pagina e relogio)' => 'recurso=plano (con dias=30, 90, 365, 730 o todos; pagina y relogio)',
        'rodizio: trocar_dia, periodo_sortear, periodo_livre, apagar_tudo' => 'rodizio: trocar_dia, periodo_sortear, periodo_livre, apagar_tudo',
        'Cabeça e filtros' => 'Cabecera y filtros',
        'h1 "Plano" e a nota "Modo: <modo> · a escala vai até DD/MM/AAAA · o plano gravado vai até DD/MM/AAAA. Troque o relógio de qualquer dia em "trocar por…": o dia fica escolhido à mão (e a escala é refeita a partir dele)." Filtros lado a lado: Período (Próximos 30 dias, Próximos 90 dias (o padrão), Próximo ano, Próximos 2 anos, Tudo; trocar relê a API) e Relógio (Todos e cada um; filtra o dia a dia na tela).' => 'h1 "Plan" y la nota "Modo: <modo> · la escala llega hasta DD/MM/AAAA · el plan guardado llega hasta DD/MM/AAAA. Cambie el reloj de cualquier día en "cambiar por…":: el día queda elegido a mano (y la escala se rehace a partir de él)." Filtros lado a lado: Período (Próximos 30 días, Próximos 90 días (el predeterminado), Próximo año, Próximos 2 años, Todo; cambiar relee la API) y Reloj (Todos y cada uno; filtra el día a día en la pantalla).',
        'O período à mão' => 'El período a mano',
        'Uma nota: "Para escolher os relógios de um período, dia a dia: na página Hoje, no quadro Modo de rodízio, escolha "Rodízio manual". Para apagar a programação, veja o fim desta página." (o link Hoje vai para index.php#manual).' => 'Una nota: "Para elegir los relojes de un período, día a día: en la página Hoy, en el cuadro Modo de rotación, elija "Rotación manual". Para borrar la programación, vea el final de esta página." (el enlace Hoy va a index.php#manual).',
        'Resumo do período (<n> dias)' => 'Resumen del período (<n> días)',
        'Tabela Relógio, Dias, %, Próximo dia ("DD/MM/AAAA seg"), À mão; do que tem mais dias ao que tem menos. Embaixo, "Sem nenhum dia no período: <relógios>." Sem dias: "Nenhum dia no plano neste período."' => 'Tabla Reloj, Días, %, Próximo día ("DD/MM/AAAA lun"), A mano; del que tiene más días al que tiene menos. Debajo, "Sin ningún día en el período: <relojes>." Sin días: "Ningún día en el plan en este período."',
        'Dia a dia' => 'Día a día',
        'Os dias livres (livres, da API) entram entre os do plano, na ordem das datas: no lugar do relógio, "livre: escolha à mão" em cinza com a marca "livre", e a lista do dia começa em "escolher…" (com "↺ voltar a sortear"). Um título por mês ("Outubro de 2026") e uma tabela de dias: o dia ("DD/MM" e o dia da semana, "hoje" no de hoje, com a faixa safira), o relógio (com "à mão" e o motivo embaixo), o lembrete e o "trocar por…" (como na página Hoje). Fim de semana com fundo cinza claro. Sem dias: "Neste modo o sorteio é feito semana a semana: o plano tem só a semana atual." ou "Nenhum dia." Os dias vêm da API (plano.dia_a_dia, com pagina e relogio: o filtro de relógio relê a API), de "Mostrar até" em "Mostrar até" (a Configuração, padrão 31); passando disso, o navegador de páginas embaixo (cada página relê a API e rola até o dia a dia) e "Página N de M · <total> dias, <n> por página (o "Mostrar até" da Configuração)."' => 'Los días libres (livres, de la API) entran entre los del plan, en el orden de las fechas: en el lugar del reloj, "libre: elija a mano" en gris con la marca "libre", y la lista del día empieza en "elegir…" (con "↺ volver a sortear"). Un título por mes ("octubre de 2026") y una tabla de días: el día ("DD/MM" y el día de la semana, "hoy" en el de hoy, con la franja zafiro), el reloj (con "a mano" y el motivo debajo), el recordatorio y el "cambiar por…" (como en la página Hoy). Fin de semana con fondo gris claro. Sin días: "En este modo el sorteo se hace semana a semana: el plan tiene solo la semana actual." o "Ningún día." Los días vienen de la API (plano.dia_a_dia, con pagina y relogio: el filtro de reloj relee la API), de "Mostrar hasta" en "Mostrar hasta" (la Configuración, por defecto 31); pasando de eso, el navegador de páginas debajo (cada página relee la API y se desplaza hasta el día a día) y "Página N de M · <total> días, <n> por página (el "Mostrar hasta" de la Configuración)."',
        'Rodapé: Apagar a programação (um cartão no fim da página, depois do dia a dia, separado por uma margem grande e uma borda de 3px aço escuro em cima)' => 'Pie: Borrar la programación (una tarjeta al final de la página, después del día a día, separada por un margen grande y un borde de 3px acero oscuro arriba)',
        'Título h2 "Apagar a programação". "Apagar um período" (o rótulo em cinza): numa linha que quebra, "De" e "Até" (datas, de hoje em diante, obrigatórias), "Depois" (lista: "e sortear de novo" = rodizio periodo_sortear; "e deixar livre" = periodo_livre) e o botão leve "Apagar". Embaixo, a explicação da opção escolhida ("Tudo o que o período tem, de amanhã em diante (escolhido à mão, sorteado ou livre), sai, e o modo de rodízio sorteia os dias outra vez." / "... sai, e os dias ficam livres: sem relógio e sem sorteio, para você escolher cada um ..."). Confirma "Apagar o que o período tem e sortear de novo? Os dias escolhidos à mão nele também saem." (ou "... e deixar os dias livres, sem relógio? ...").' => 'Título h2 "Borrar la programación". "Borrar un período" (el rótulo en gris): en una línea que parte, "De" y "Hasta" (fechas, de hoy en adelante, obligatorias), "Después" (lista: "y sortear de nuevo" = rodizio periodo_sortear; "y dejar libre" = periodo_livre) y el botón leve "Borrar". Debajo, la explicación de la opción elegida ("Todo lo que tiene el período, de mañana en adelante (elegido a mano, sorteado o libre), sale, y el modo de rotación sortea los días otra vez." / "... sale, y los días quedan libres: sin reloj y sin sorteo, para que usted elija cada uno ..."). Confirma "¿Borrar lo que tiene el período y sortear de nuevo? Los días elegidos a mano en él también salen." (o "... y dejar los días libres, sin reloj? ...").',
        'Abaixo de uma linha, "Apagar tudo": a caixa "Excluindo hoje (apaga também o dia de hoje)" e o botão leve "Apagar tudo" (rodizio apagar_tudo, com hoje=1 marcada), e a nota "Limpa toda a programação, de amanhã em diante: os dias escolhidos à mão, os sorteados e os livres. Marcando "Excluindo hoje", apaga de hoje em diante (se sair outro relógio para hoje, ele passa a ser o do pulso a partir de agora). Depois, o modo de rodízio monta o plano de novo, do zero." Confirma (com hoje: "Apagar toda a programação, de hoje em diante (escolhidos à mão, sorteados e dias livres)? O modo de rodízio monta o plano de novo, e hoje pode sair outro relógio, que passa a ser o do pulso a partir de agora."; sem: "... de amanhã em diante ...; hoje continua como está.").' => 'Debajo de una línea, "Borrar todo": la casilla "Incluyendo hoy (borra también el día de hoy)" y el botón leve "Borrar todo" (rodizio apagar_tudo, con hoje=1 marcada), y la nota "Limpia toda la programación, de mañana en adelante: los días elegidos a mano, los sorteados y los libres. Marcando "Incluyendo hoy", borra de hoy en adelante (si sale otro reloj para hoy, pasa a ser el de la muñeca a partir de ahora). Después, el modo de rotación arma el plan de nuevo, desde cero." Confirma (con hoy: "¿Borrar toda la programación, de hoy en adelante (elegidos a mano, sorteados y días libres)? El modo de rotación arma el plan de nuevo, y hoy puede salir otro reloj, que pasa a ser el de la muñeca a partir de ahora."; sin: "... de mañana en adelante ...; hoy continúa como está.").',
        'configuracao.php; ?evento=<id> abre um evento para editar; #personalizados' => 'configuracao.php; ?evento=<id> abre un evento para editar; #personalizados',
        'recurso=migracoes (antes de tudo)' => 'recurso=migracoes (antes de todo)',
        'config: salvar, evento_salvar, evento_excluir, testar_manha, testar_noite, teste_agenda_criar, teste_agenda_remover, sincronizar' => 'config: salvar, evento_salvar, evento_excluir, testar_manha, testar_noite, teste_agenda_criar, teste_agenda_remover, sincronizar',
        'migracoes: aplicar' => 'migracoes: aplicar',
        'backup: fazer, restaurar' => 'backup: fazer, restaurar',
        'Banco desatualizado (só quando há migração pendente)' => 'Base de datos desactualizada (solo cuando hay migración pendiente)',
        'Um cartão só: "O banco está desatualizado", a explicação ("Esta versão do sistema precisa de migrações que ainda não foram aplicadas... as páginas, a API e o cron ficam parados..."), a tabela das pendentes (versão em negrito, o que traz, o arquivo em código), o botão "Aplicar agora" (migracoes aplicar) e a nota de como rodar na mão. Depois de aplicar: "Atualização do banco", o resultado e "Continuar para a Configuração".' => 'Una sola tarjeta: "La base de datos está desactualizada", la explicación ("Esta versión del sistema necesita migraciones que aún no se han aplicado... las páginas, la API y el cron se quedan parados..."), la tabla de las pendientes (versión en negrita, lo que trae, el archivo en código), el botón "Aplicar ahora" (migracoes aplicar) y la nota de cómo ejecutarlo a mano. Después de aplicar: "Actualización de la base de datos", el resultado y "Continuar a la Configuración".',
        'Os quadros do alto (uma grade de 3 colunas; um formulário só, salvo pela barra do pé)' => 'Los cuadros de arriba (una cuadrícula de 3 columnas; un solo formulario, guardado por la barra del pie)',
        'Cada opção numa linha: o rótulo à esquerda e o campo à direita, alinhados na mesma coluna em todos os quadros; caixas de marcar no lugar do campo; textos longos com o rótulo em cima e o campo na largura toda. Cada quadro com a explicação embaixo.' => 'Cada opción en una línea: el rótulo a la izquierda y el campo a la derecha, alineados en la misma columna en todos los cuadros; casillas de marcar en el lugar del campo; textos largos con el rótulo arriba y el campo en toda la anchura. Cada cuadro con la explicación debajo.',
        'Rotina do dia: Manhã: relógio do dia e avisos (hora); Noite: preparar o de amanhã (hora); No pulso a partir de (hora); Pôr no pulso sozinho (caixa); No pulso até (hora); Tirar do pulso sozinho (caixa); Sessão no sol esquecida fecha às (hora).' => 'Rutina del día: Mañana: reloj del día y avisos (hora); Noche: preparar el de mañana (hora); En la muñeca a partir de (hora); Poner en la muñeca solo (casilla); En la muñeca hasta (hora); Quitar de la muñeca solo (casilla); Sesión al sol olvidada se cierra a las (hora).',
        'Limites e contas: Carregar quando a carga chegar a (%) (1 a 99, padrão 20); Solar: pôr no sol quando chegar a (%) (1 a 99, padrão 70); Gasto medido: média dos últimos (dias) (1 a 3650, padrão 90); Aviso Encostado: dias sem ir ao pulso (1 a 3650, padrão 30; encostado_dias).' => 'Límites y cuentas: Cargar cuando la carga llegue a (%) (1 a 99, por defecto 20); Solar: poner al sol cuando llegue a (%) (1 a 99, por defecto 70); Consumo medido: media de los últimos (días) (1 a 3650, por defecto 90); Aviso Arrinconado: días sin ir a la muñeca (1 a 3650, por defecto 30; encostado_dias).',
        'Telas: Abrir o relógio na página Hoje (Ao lado da lista; Numa janela flutuante, grande); Destaque no alto da página Hoje (O relógio do dia; O relógio no pulso agora: destaque_hoje dia ou pulso, com a nota "Destaque: ..."); "Próximos dias (página Hoje): mostrar até (dias por página)" e "Plano: mostrar até (dias por página)" (números de 1 a 366, com o valor de mostrar_ate da API: padrão 7 e 31); Endereço do sistema (a âncora {link}); e a nota sobre o Mostrar até (passando disso, as páginas embaixo: <, os números, >).' => 'Pantallas: Abrir el reloj en la página Hoy (Al lado de la lista; En una ventana flotante, grande); Destacado arriba de la página Hoy (El reloj del día; El reloj en la muñeca ahora: destaque_hoje dia o pulso, con la nota "Destacado: ..."); "Próximos días (página Hoy): mostrar hasta (días por página)" y "Plan: mostrar hasta (días por página)" (números de 1 a 366, con el valor de mostrar_ate de la API: por defecto 7 y 31); Dirección del sistema (el marcador {link}); y la nota sobre el Mostrar hasta (pasando de eso, las páginas debajo: <, los números, >).',
        'Cron: "Cron rodando: última execução às HH:MM." (nota) ou, em âmbar, "O cron ainda não rodou" / "O cron não roda desde ..." com a linha do crontab em código; o erro guardado numa caixa ("O cron está com erro"); o link "Ver todas as execuções do cron" e o "Registro da última rodada" (abre e fecha).' => 'Cron: "Cron en marcha: última ejecución a las HH:MM." (nota) o, en ámbar, "El cron aún no se ha ejecutado" / "El cron no se ejecuta desde ..." con la línea del crontab en código; el error guardado en una caja ("El cron tiene un error"); el enlace "Ver todas las ejecuciones del cron" y el "Registro de la última ronda" (se abre y se cierra).',
        'Sorteios (só leitura): "Os números vêm de": "1. RANDOM.ORG (ruído atmosférico) · 2. fora do ar, ANU QRNG (quântico) · 3. sem os dois, o gerador seguro do PHP"; "Último lote": "<fonte> em DD/MM/AAAA HH:MM" (aleatorio.ultimo_lote da API) ou "nenhum ainda"; com os dois fora, "Serviços fora" em âmbar: "os dois sem responder desde DD/MM/AAAA HH:MM; o sistema tenta de novo depois de 10 minutos". A nota: "Todo sorteio do sistema (o rodízio totalmente aleatório, o sorteio pela nota e o desempate de notas iguais na escala) usa estes números. Eles chegam num lote, e cada sorteio usa só o que precisa, sem viés."' => 'Sorteos (solo lectura): "Los números vienen de": "1. RANDOM.ORG (ruido atmosférico) · 2. fuera de servicio, ANU QRNG (cuántico) · 3. sin los dos, el generador seguro de PHP"; "Último lote": "<fuente> el DD/MM/AAAA HH:MM" (aleatorio.ultimo_lote de la API) o "ninguno todavía"; con los dos fuera, "Servicios fuera" en ámbar: "los dos sin responder desde DD/MM/AAAA HH:MM; el sistema lo intenta de nuevo después de 10 minutos". La nota: "Todo sorteo del sistema (la rotación totalmente aleatoria, el sorteo por la nota y el desempate de notas iguales en la escala) usa estos números. Llegan en un lote, y cada sorteo usa solo lo que necesita, sin sesgo."',
        'Telegram (API de alerta): Enviar alertas (caixa). Google Agenda: Criar eventos na agenda (caixa), Antecedência dos eventos (dias, 1 a 365), ID da agenda, Caminho da chave JSON no servidor; a chave encontrada ("Compartilhe a agenda com <e-mail>") ou não; os botões leves "Criar evento de teste" e "Remover evento de teste".' => 'Telegram (API de alerta): Enviar alertas (casilla). Google Calendar: Crear eventos en la agenda (casilla), Antelación de los eventos (días, 1 a 365), ID de la agenda, Camino de la clave JSON en el servidor; la clave encontrada ("Comparta la agenda con <correo>") o no; los botones leve "Crear evento de prueba" y "Quitar evento de prueba".',
        'Mensagem padrão' => 'Mensaje predeterminado',
        'Um cartão por canal (Telegram, Google Agenda), lado a lado: o nome do canal, a lista "Inserir âncora" (põe {ancora} onde está o cursor), o texto (7 linhas) e a ajuda do canal. Embaixo, "O que cada âncora vira" (abre e fecha: a tabela {ancora} → o que é).' => 'Una tarjeta por canal (Telegram, Google Calendar), lado a lado: el nombre del canal, la lista "Insertar marcador" (pone {ancora} donde está el cursor), el texto (7 líneas) y la ayuda del canal. Debajo, "En qué se convierte cada marcador" (se abre y se cierra: la tabla {ancora} → lo que es).',
        'O que vai para onde' => 'Qué va adónde',
        'Tabela: Aviso (o nome; nos eventos personalizados, em negrito, com "editar" e "excluir"), Quando, uma coluna por canal com uma caixa centrada (vai ou não), e Personalizar (uma caixa por canal). Marcar Personalizar abre, na linha de baixo, o texto daquele aviso naquele canal, com "Inserir âncora" e a dica "Vazio usa a mensagem padrão do <canal>".' => 'Tabla: Aviso (el nombre; en los eventos personalizados, en negrita, con "editar" y "eliminar"), Cuándo, una columna por canal con una casilla centrada (va o no), y Personalizar (una casilla por canal). Marcar Personalizar abre, en la línea de abajo, el texto de aquel aviso en aquel canal, con "Insertar marcador" y la indicación "Vacío usa el mensaje por defecto de <canal>".',
        'A barra de salvar no pé: "As mudanças desta página valem depois de salvar." e o botão "Salvar configuração" (config salvar).' => 'La barra de guardar al pie: "Los cambios de esta página valen después de guardar." y el botón "Guardar configuración" (config salvar).',
        'Eventos personalizados' => 'Eventos personalizados',
        'A explicação e um quadro que abre e fecha ("Novo evento" ou "Editar o evento <nome>"): Nome (obrigatório), Relógio (opcional: "Nenhum, é um evento geral" e os relógios), Quando dispara (uma vez, todo dia, toda semana, todo mês, a cada N dias), e só os campos da repetição escolhida: Data / A partir de, Hora (obrigatória), Dia do mês (1 a 31), A cada quantos dias, Dias da semana (caixas seg a dom); Ativo; as próximas vezes (na edição); botão "Criar evento" / "Salvar alterações" e "cancelar".' => 'La explicación y un cuadro que se abre y se cierra ("Evento nuevo" o "Editar el evento <nombre>"): Nombre (obligatorio), Reloj (opcional: "Ninguno, es un evento general" y los relojes), Cuándo se dispara (una vez, todos los días, todas las semanas, todos los meses, cada N días), y solo los campos de la repetición elegida: Fecha / A partir de, Hora (obligatoria), Día del mes (1 a 31), Cada cuántos días, Días de la semana (casillas lun a dom); Activo; las próximas veces (en la edición); botón "Crear evento" / "Guardar cambios" y "cancelar".',
        'Cópia de segurança (no fim da página, depois de Como sai hoje)' => 'Copia de seguridad (al final de la página, después de Cómo sale hoy)',
        'Título "Cópia de segurança". Com a pasta: a nota "Uma cópia do banco inteiro por dia, na rodada da noite, guardando as 7 mais novas, sem (ou com) o conteúdo dos documentos... Última: DD/MM/AAAA HH:MM." (ou "Nenhuma feita ainda."); sem a pasta, em âmbar: "A cópia automática está desligada: <motivo>. Ponha no config.php a BACKUP_PASTA, uma pasta do servidor fora da pasta publicada."' => 'Título "Copia de seguridad". Con la carpeta: la nota "Una copia de la base de datos entera por día, en la ronda de la noche, guardando las 7 más nuevas, sin (o con) el contenido de los documentos... Última: DD/MM/AAAA HH:MM." (o "Ninguna hecha todavía."); sin la carpeta, en ámbar: "La copia automática está desactivada: <motivo>. Ponga en el config.php la BACKUP_PASTA, una carpeta del servidor fuera de la carpeta publicada."',
        'A tabela compacta das cópias (da mais nova para a mais velha): Cópia (o nome do arquivo em fonte fixa), Feita em, Tamanho ("7 KB"), Documentos (com/sem) e, à direita, "Baixar" (link leve para api.php?recurso=backup&arquivo=<nome>) e "Restaurar" (discreto; confirma "Voltar o banco para a cópia de DD/MM/AAAA HH:MM? Tudo o que foi feito depois some. Antes, o sistema guarda uma cópia do que está agora."; backup restaurar). Embaixo, o botão leve "Fazer uma cópia agora" (backup fazer).' => 'La tabla compacta de las copias (de la más nueva a la más antigua): Copia (el nombre del archivo en fuente fija), Hecha el, Tamaño ("7 KB"), Documentos (con/sin) y, a la derecha, "Descargar" (enlace leve a api.php?recurso=backup&arquivo=<nombre>) y "Restaurar" (discreto; confirma "¿Volver la base de datos a la copia de DD/MM/AAAA HH:MM? Todo lo que se hizo después desaparece. Antes, el sistema guarda una copia de lo que hay ahora."; backup restaurar). Debajo, el botón leve "Hacer una copia ahora" (backup fazer).',
        'Com BACKUP_ATIVO = false no config.php, a seção inteira não aparece (nem o aviso de que falta a pasta).' => 'Con BACKUP_ATIVO = false en el config.php, la sección entera no aparece (ni el aviso de que falta la carpeta).',
        'Como sai hoje' => 'Cómo sale hoy',
        'Três caixas lado a lado: Telegram de manhã e Telegram à noite (o texto como sai, em fonte fixa, ou "(nada a enviar)", e o botão leve "Enviar agora"); Agenda (os próximos eventos com a data, a hora, o título em negrito e a descrição, quantos o sistema já criou, e "Sincronizar agora").' => 'Tres cajas lado a lado: Telegram por la mañana y Telegram por la noche (el texto como sale, en fuente fija, o "(nada que enviar)", y el botón leve "Enviar ahora"); Agenda (los próximos eventos con la fecha, la hora, el título en negrita y la descripción, cuántos creó ya el sistema, y "Sincronizar ahora").',
        'Critérios de escolha' => 'Criterios de elección',
        'criterios.php?escopo=<"", g:<grupo> ou r:<relógio>>; ?relogio=<id> abre a conta dele' => 'criterios.php?escopo=<"", g:<grupo> o r:<reloj>>; ?relogio=<id> abre su cuenta',
        'criterios: todas as ações' => 'criterios: todas las acciones',
        'Explicações' => 'Explicaciones',
        'h1 "Critérios de escolha do relógio". Cartão "Como a nota funciona" (lugar, conjunto, parâmetro, subparâmetro, faixas, peso efetivo e nota final, em negrito os termos). Cartão "Como a nota vira escolha": as quatro formas com a explicação, a tabela Modo de rodízio / Forma de escolha ("(o modo atual)") e a garantia de rodízio.' => 'h1 "Criterios de elección del reloj". Tarjeta "Cómo funciona la nota" (lugar, conjunto, parámetro, subparámetro, rangos, peso efectivo y nota final, en negrita los términos). Tarjeta "Cómo la nota se vuelve elección": las cuatro formas con la explicación, la tabla Modo de rotación / Forma de elección ("(el modo actual)") y la garantía de rotación.',
        'Onde há critérios' => 'Dónde hay criterios',
        'Tabela Lugar, Parâmetros (quantos), Usado por ("N relógios" e os nomes em cinza) e o link "editar". Em vermelho: "Há relógios sem conjunto nenhum (nota neutra, 50): ..."' => 'Tabla Lugar, Parámetros (cuántos), Usado por ("N relojes" y los nombres en gris) y el enlace "editar". En rojo: "Hay relojes sin ningún conjunto (nota neutra, 50): ..."',
        'O conjunto do lugar escolhido' => 'El conjunto del lugar elegido',
        '"Editar os critérios de" com a lista de todos os lugares ("Todos os relógios", "Grupo: <caminho>", "Relógio: <nome>"; "— com critérios próprios" nos que têm) e "Abrir". Sem critérios próprios: "<Lugar> não tem critérios próprios: usa os de <lugar de cima>." e os botões "Criar critérios próprios, copiando os de <lugar>" e "Criar vazio" (leve).' => '"Editar los criterios de" con la lista de todos los lugares ("Todos los relojes", "Grupo: <camino>", "Reloj: <nombre>"; "— con criterios propios" en los que los tienen) y "Abrir". Sin criterios propios: "<Lugar> no tiene criterios propios: usa los de <lugar de arriba>." y los botones "Crear criterios propios, copiando los de <lugar>" y "Crear vacío" (leve).',
        'Com critérios: "Critérios de <lugar>", "Usado por N relógios: ..." e a tabela Parâmetro (o nome editável), Peso no conjunto (campo curto e "%"), Subparâmetros (link para a seção; "(fora da conta)" em vermelho se nenhum), e ↑ ↓ Excluir; no rodapé "Soma" com a soma ao vivo e "fecha 100%" ou, em vermelho, "faltam N%" / "passa N%"; botão "Salvar parâmetros". Excluir confirma mostrando como o peso se divide entre os que ficam. Linha de inclusão: Novo parâmetro, Peso (%), "Incluir". Embaixo, "Excluir os critérios próprios de <lugar>" (discreto, confirma).' => 'Con criterios: "Criterios de <lugar>", "Usado por N relojes: ..." y la tabla Parámetro (el nombre editable), Peso en el conjunto (campo corto y "%"), Subparámetros (enlace a la sección; "(fuera de la cuenta)" en rojo si ninguno), y ↑ ↓ Eliminar; en el pie "Suma" con la suma en vivo y "cierra 100%" o, en rojo, "faltan N%" / "pasa N%"; botón "Guardar parámetros". Eliminar confirma mostrando cómo se reparte el peso entre los que se quedan. Fila de inclusión: Parámetro nuevo, Peso (%), "Incluir". Debajo, "Eliminar los criterios propios de <lugar>" (discreto, confirma).',
        'Cada parâmetro' => 'Cada parámetro',
        'Um cartão por parâmetro: "<nome> <peso> do conjunto de <lugar>"; a tabela Subparâmetro, Mede, Peso no parâmetro, Peso efetivo no conjunto (atualizado ao digitar), ↑ ↓ Excluir, com a soma no rodapé e "Salvar subparâmetros".' => 'Una tarjeta por parámetro: "<nombre> <peso> del conjunto de <lugar>"; la tabla Subparámetro, Mide, Peso en el parámetro, Peso efectivo en el conjunto (actualizado al teclear), ↑ ↓ Eliminar, con la suma en el pie y "Guardar subparámetros".',
        'Para cada subparâmetro, "Faixas de <nome>" (abre e fecha, com quantas faixas e o que mede): numa medida numérica, a tabela De, Até, Nota, Apagar; numa de categoria, Categoria (lista), Nota, Apagar; sempre uma linha em branco para incluir, o botão "+ faixa" (mais uma linha) e "Salvar faixas"; a regra das faixas em nota. Embaixo, "Trocar a medida para" (confirma: as faixas recomeçam) e "Mover para o parâmetro".' => 'Para cada subparámetro, "Rangos de <nombre>" (se abre y se cierra, con cuántos rangos y qué mide): en una medida numérica, la tabla De, Hasta, Nota, Borrar; en una de categoría, Categoría (lista), Nota, Borrar; siempre una línea en blanco para incluir, el botón "+ rango" (una línea más) y "Guardar rangos"; la regla de los rangos en nota. Debajo, "Cambiar la medida a" (confirma: los rangos vuelven a empezar) y "Mover al parámetro".',
        'Linha de inclusão: Novo subparâmetro, Mede (lista das medidas), Peso (%), "Incluir". Sem subparâmetros, em vermelho: "Sem subparâmetros: este parâmetro não entra na conta até ganhar um."' => 'Fila de inclusión: Subparámetro nuevo, Mide (lista de las medidas), Peso (%), "Incluir". Sin subparámetros, en rojo: "Sin subparámetros: este parámetro no entra en la cuenta hasta que tenga uno."',
        'A nota de cada relógio agora' => 'La nota de cada reloj ahora',
        'Um quadro que abre e fecha por relógio disponível, da maior nota para a menor: o nome em negrito, "<grupo> · critérios de <lugar>" e a nota à direita; aberto, a tabela Parâmetro, Subparâmetro, Valor medido, Faixa, Nota, Peso efetivo, Pontos, com a nota final no rodapé, e os links "editar os critérios de <lugar>" e "critérios só deste relógio". Por fim, o cartão "Restaurar os critérios iniciais" com o botão leve "Restaurar" (confirma).' => 'Un cuadro que se abre y se cierra por reloj disponible, de la mayor nota a la menor: el nombre en negrita, "<grupo> · criterios de <lugar>" y la nota a la derecha; abierto, la tabla Parámetro, Subparámetro, Valor medido, Rango, Nota, Peso efectivo, Puntos, con la nota final en el pie, y los enlaces "editar los criterios de <lugar>" y "criterios solo de este reloj". Por último, la tarjeta "Restaurar los criterios iniciales" con el botón leve "Restaurar" (confirma).',
        'Grupos de relógios' => 'Grupos de relojes',
        'arvore: novo, renomear, mover, ordem, excluir, relogios' => 'arvore: novo, renomear, mover, ordem, excluir, relogios',
        'Árvore' => 'Árbol',
        'A explicação; a árvore como lista com recuo por nível. Cada grupo: o nome num campo com "Renomear" (discreto), "N relógios" ("· critérios próprios" com link), ↑ ↓ e Excluir (confirma dizendo para onde vão os subgrupos, os relógios e o que acontece com os critérios); os relógios dele em cinza embaixo; e "subgrupo e mover" (abre e fecha): Novo subgrupo + "Criar", Mover para dentro de (só onde não forma ciclo) + "Mover". No fim: linha de inclusão "Novo grupo", "dentro de" e "Criar". Sem grupos: "Nenhum grupo ainda."' => 'La explicación; el árbol como lista con sangría por nivel. Cada grupo: el nombre en un campo con "Renombrar" (discreto), "N relojes" ("· criterios propios" con enlace), ↑ ↓ y Eliminar (confirma diciendo a dónde van los subgrupos, los relojes y qué pasa con los criterios); sus relojes en gris debajo; y "subgrupo y mover" (se abre y se cierra): Subgrupo nuevo + "Crear", Mover para dentro de (solo donde no forma ciclo) + "Mover". Al final: fila de inclusión "Grupo nuevo", "dentro de" y "Crear". Sin grupos: "Ningún grupo todavía."',
        'O grupo de cada relógio' => 'El grupo de cada reloj',
        'Tabela Relógio ("(indisponível)" em cinza) e Grupo (lista com "(na raiz)" e os caminhos), e o botão "Salvar grupos" (arvore relogios, todos de uma vez).' => 'Tabla Reloj ("(no disponible)" en gris) y Grupo (lista con "(en la raíz)" y los caminos), y el botón "Guardar grupos" (arvore relogios, todos de una vez).',
        'execucoes.php?de=&ate=&situacao=&busca=&por=&pagina= (os filtros no endereço)' => 'execucoes.php?de=&ate=&situacao=&busca=&por=&pagina= (los filtros en la dirección)',
        'Título com "Última execução: DD/MM/AAAA HH:MM:SS". Filtros num cartão: De, Até (padrão: os últimos 7 dias), Situação (Com atividade (padrão), Com erro, Sem atividade, Todas), Texto no registro, Por página (25, 50, 100, 200), "Filtrar" e os atalhos hoje, 7 dias, 30 dias, erros do último ano.' => 'Título con "Última ejecución: DD/MM/AAAA HH:MM:SS". Filtros en una tarjeta: De, Hasta (por defecto: los últimos 7 días), Situación (Con actividad (por defecto), Con error, Sin actividad, Todas), Texto en el registro, Por página (25, 50, 100, 200), "Filtrar" y los atajos hoy, 7 días, 30 días, errores del último año.',
        'Resumo em 4 caixas: execuções no período, com atividade, com erro (vermelho se houver), a mais lenta. A nota com quantas e a retenção. Tabela Início (data e a hora em negrito embaixo), Duração ("850 ms" ou "1,5 s"), Situação (etiqueta erro / atividade / sem atividade), Registro (o texto em fonte fixa, ou "nada a fazer neste minuto"); linha com erro em vermelho claro. Paginação: « primeira, ‹ anterior, até 3 números de cada lado, próxima ›, última ».' => 'Resumen en 4 cajas: ejecuciones en el período, con actividad, con error (rojo si las hay), la más lenta. La nota con cuántas y la retención. Tabla Inicio (fecha y la hora en negrita debajo), Duración ("850 ms" o "1,5 s"), Situación (etiqueta error / actividad / sin actividad), Registro (el texto en fuente fija, o "nada que hacer en este minuto"); línea con error en rojo claro. Paginación: « primera, ‹ anterior, hasta 3 números de cada lado, próxima ›, última ».',
        'Histórico — <relógio>' => 'Historial — <reloj>',
        'Cabeça com a foto, "Histórico · <tipo> · código N", o nome em h1 e "<n> registros desde ...". Filtros num cartão: De, Até, Estado (Todos, Em uso, Fora do rodízio, cada tipo de sessão, Em repouso, Marcações), Por página (25, 50, 100, Todos), "Filtrar" e os atalhos 7 dias, 30 dias, desde o começo.' => 'Cabecera con la foto, "Historial · <tipo> · código N", el nombre en h1 y "<n> registros desde ...". Filtros en una tarjeta: De, Hasta, Estado (Todos, En uso, Fuera de la rotación, cada tipo de sesión, En reposo, Marcas), Por página (25, 50, 100, Todos), "Filtrar" y los atajos 7 días, 30 días, desde el principio.',
        'Resumo em caixas: o tempo em cada estado ("5d 7h" e "em uso · 13%") e a contagem de cada marcação. A nota de quantos e de como ler os trechos. Tabela Início, Fim, Duração, Estado (etiqueta verde para uso, vermelha para repouso, laranja para as outras sessões; marcação em cinza, só o texto; "em andamento: o fim é o momento desta consulta"). Paginação: « mais recentes, ‹ anterior, números, próxima ›, mais antigos » e "ver tudo".' => 'Resumen en cajas: el tiempo en cada estado ("5d 7h" y "en uso · 13%") y el recuento de cada marca. La nota de cuántos y de cómo leer los tramos. Tabla Inicio, Fin, Duración, Estado (etiqueta verde para uso, roja para reposo, naranja para las otras sesiones; marca en gris, solo el texto; "en curso: el fin es el momento de esta consulta"). Paginación: « más recientes, ‹ anterior, números, próxima ›, más antiguos » y "ver todo".',
        'documentos.php?relogio=<id>&cat=<categoria> (sem relógio: de todos)' => 'documentos.php?relogio=<id>&cat=<categoría> (sin reloj: de todos)',
        'recurso=documento (cada arquivo)' => 'recurso=documento (cada archivo)',
        'documentos: enviar, alterar, excluir' => 'documentos: enviar, alterar, excluir',
        'relogio: salvar (a cópia no banco do relógio)' => 'relogio: salvar (la copia en la base de datos del reloj)',
        'Cabeça' => 'Cabecera',
        'h1 "Documentos do <relógio>" (ou "de todos os relógios"); a lista "Relógio" (Todos e cada um, com "(N)") e "Abrir a ficha do relógio". A situação da cópia no banco (quem decide: o config.php, o relógio, com o botão "Guardar todos os dele no banco" / "Só os marcados"). Sem a pasta: o motivo em âmbar.' => 'h1 "Documentos del <reloj>" (o "de todos los relojes"); la lista "Reloj" (Todos y cada uno, con "(N)") y "Abrir la ficha del reloj". La situación de la copia en la base de datos (quién decide: el config.php, el reloj, con el botón "Guardar todos los de él en la base de datos" / "Solo los marcados"). Sin la carpeta: el motivo en ámbar.',
        'Enviar arquivos (abre e fecha; aberto quando não há nenhum; só com um relógio escolhido)' => 'Enviar archivos (se abre y se cierra; abierto cuando no hay ninguno; solo con un reloj elegido)',
        'Categoria (com o que ela aceita), Título ("vazio: o nome do arquivo"), Data, Descrição, Arquivos (vários; o seletor só deixa os tipos da categoria), "Guardar a cópia destes arquivos também no banco" (só quando cabe ao arquivo decidir), o limite de tamanho, "Enviar" e o andamento ("Enviando 2 de 5: foto.jpg — 40%"). Um arquivo por vez, cada foto com a miniatura feita no navegador (480px, JPEG 80%). No fim: "N documentos guardados." e os erros.' => 'Categoría (con lo que acepta), Título ("vacío: el nombre del archivo"), Fecha, Descripción, Archivos (varios; el selector solo deja los tipos de la categoría), "Guardar la copia de estos archivos también en la base de datos" (solo cuando le toca al archivo decidir), el límite de tamaño, "Enviar" y el avance ("Enviando 2 de 5: foto.jpg — 40%"). Un archivo cada vez, cada foto con la miniatura hecha en el navegador (480px, JPEG 80%). Al final: "N documentos guardados." y los errores.',
        'Abas e conteúdo' => 'Pestañas y contenido',
        'Abas "Todos (N)" e cada categoria "(N)". Fotos: a galeria (quadrados de 140px, 100px no celular, com o título e a data) e o botão "▶ Apresentação"; tocar numa foto abre o visor em tela cheia (fundo #080b0f): "N de M", "▶ Apresentação" / "❚❚ Parar" (troca a cada 4 s), "Baixar", "×"; ‹ e › nos lados, setas do teclado, deslizar o dedo, Esc fecha, espaço liga a apresentação; a legenda embaixo.' => 'Pestañas "Todos (N)" y cada categoría "(N)". Fotos: la galería (cuadrados de 140px, 100px en el móvil, con el título y la fecha) y el botón "▶ Presentación"; tocar una foto abre el visor a pantalla completa (fondo #080b0f): "N de M", "▶ Presentación" / "❚❚ Parar" (cambia cada 4 s), "Descargar", "×"; ‹ y › en los lados, flechas del teclado, deslizar el dedo, Esc cierra, espacio enciende la presentación; la leyenda debajo.',
        'Vídeos: o player e a lista para marcar e ordenar (↑ ↓), "▶ Assistir os marcados" (tocam em sequência; "‹ Anterior", "Próximo ›", "Fechar"). Arquivos: um cartão por arquivo com o título, a data, a categoria em etiqueta, a descrição, o nome, o tamanho e onde está guardado; PDF: "Ver aqui" (abre embutido), "Abrir noutra aba", "Baixar"; XML de NF-e: a tabela Emitente, Nota, Valor, Produto(s), Chave e "Baixar o XML"; áudio: o player; o resto: "Baixar".' => 'Vídeos: el reproductor y la lista para marcar y ordenar (↑ ↓), "▶ Ver los marcados" (se reproducen en secuencia; "‹ Anterior", "Próximo ›", "Cerrar"). Archivos: una tarjeta por archivo con el título, la fecha, la categoría en etiqueta, la descripción, el nombre, el tamaño y dónde está guardado; PDF: "Ver aquí" (se abre embebido), "Abrir en otra pestaña", "Descargar"; XML de NF-e: la tabla Emisor, Factura, Valor, Producto(s), Clave y "Descargar el XML"; audio: el reproductor; el resto: "Descargar".',
        'Em cada arquivo, "editar" (abre e fecha): Título, Data, Categoria, Descrição, a cópia no banco (quando cabe), "Salvar" e "Excluir" (confirma "Excluir <título>? O arquivo sai do servidor."). Fotos e vídeos se editam numa lista à parte, "Editar ou excluir fotos e vídeos".' => 'En cada archivo, "editar" (se abre y se cierra): Título, Fecha, Categoría, Descripción, la copia en la base de datos (cuando le toca), "Guardar" y "Eliminar" (confirma "¿Eliminar <título>? El archivo sale del servidor."). Fotos y vídeos se editan en una lista aparte, "Editar o eliminar fotos y vídeos".',
        'recurso=calcular (o testar)' => 'recurso=calcular (el probar)',
        'campos, lancamento_tipos, formulas, avisos, modos, documento_categorias' => 'campos, lancamento_tipos, formulas, avisos, modos, documento_categorias',
        'Em todas as abas' => 'En todas las pestañas',
        'h1 "Cadastros" e as abas Campos, Tipos de lançamento, Fórmulas, Avisos, Modos de rodízio, Categorias de documentos. Cada aba é um cartão: o título, a explicação, a tabela com "Editar" (link que abre o formulário embaixo com os dados, no #form) e Excluir em cada linha, e o formulário ("Novo ..." ou "Alterar ...", botão "Criar" / "Salvar" e "cancelar"). Gravou: o recado no alto e a edição acaba; recusado: o que foi digitado fica e os erros aparecem no topo.' => 'h1 "Definiciones" y las pestañas Campos, Tipos de registro, Fórmulas, Avisos, Modos de rotación, Categorías de documentos. Cada pestaña es una tarjeta: el título, la explicación, la tabla con "Editar" (enlace que abre el formulario debajo con los datos, en el #form) y Eliminar en cada línea, y el formulario ("Nuevo ..." o "Modificar ...", botón "Crear" / "Guardar" y "cancelar"). Guardó: el mensaje arriba y la edición acaba; rechazado: lo tecleado se queda y los errores aparecen arriba.',
        'Tabela Campo ("(unidade)"), Identificador (fonte fixa), Tipo, Vale para, Padrão, ações (Editar, ↑, ↓, Excluir com confirmação "Excluir o campo <nome> e os valores dele?"). Formulário: Nome (até 120), Identificador (a-z, 0-9 e _; começa com letra; até 40), Tipo (Número inteiro, Número decimal, Sim ou não, Data, Lista de opções, Texto), Unidade (até 20), Valor padrão, Vale para ("todos os relógios" e os grupos), Opções (lista: uma por linha).' => 'Tabla Campo ("(unidad)"), Identificador (fuente fija), Tipo, Vale para, Predeterminado, acciones (Editar, ↑, ↓, Eliminar con confirmación "¿Eliminar el campo <nombre> y sus valores?"). Formulario: Nombre (hasta 120), Identificador (a-z, 0-9 y _; empieza con letra; hasta 40), Tipo (Número entero, Número decimal, Sí o no, Fecha, Lista de opciones, Texto), Unidad (hasta 20), Valor predeterminado, Vale para ("todos los relojes" y los grupos), Opciones (lista: una por línea).',
        'Tipos de lançamento' => 'Tipos de registro',
        'Tabela Tipo, Identificador, Formato (com a unidade), Fecha sozinho às, Exclusiva, Mede o gasto, Vale quando (fonte fixa), Vale para, Lançamentos (quantos), ações. Formulário: Nome, Identificador, Formato (Instantâneo; Instantâneo com valor; Sessão, com início e fim), Unidade (com valor), Fecha sozinho às (hora; vazio: não fecha), Vale para, Vale quando (fórmula), as caixas "sessão exclusiva (o relógio num lugar só)" e "mede o gasto".' => 'Tabla Tipo, Identificador, Formato (con la unidad), Se cierra solo a las, Exclusiva, Mide el consumo, Vale cuando (fuente fija), Vale para, Registros (cuántos), acciones. Formulario: Nombre, Identificador, Formato (Instantáneo; Instantáneo con valor; Sesión, con inicio y fin), Unidad (con valor), Se cierra solo a las (hora; vacío: no se cierra), Vale para, Vale cuando (fórmula), las casillas "sesión exclusiva (el reloj en un solo lugar)" y "mide el consumo".',
        'Fórmulas' => 'Fórmulas',
        'Tabela Fórmula (o nome e o identificador com a unidade), Versão para, Cálculo (fonte fixa), ações. Formulário: Identificador (só na nova), Nome, Unidade, Versão para, Cálculo (textarea, fonte fixa). "Testar uma fórmula (sem gravar)": o texto da fórmula e "Testar em todos os relógios" (recurso=calcular): a tabela Relógio, Resultado, As partes da conta, ou os erros. "As funções do motor" (abre e fecha): cada função em negrito e a explicação.' => 'Tabla Fórmula (el nombre y el identificador con la unidad), Versión para, Cálculo (fuente fija), acciones. Formulario: Identificador (solo en la nueva), Nombre, Unidad, Versión para, Cálculo (textarea, fuente fija). "Probar una fórmula (sin guardar)": el texto de la fórmula y "Probar en todos los relojes" (recurso=calcular): la tabla Reloj, Resultado, Las partes de la cuenta, o los errores. "Las funciones del motor" (se abre y se cierra): cada función en negrita y la explicación.',
        'Tabela Aviso, Versão para, Data prevista, Vale quando, Antecedência ("N d"), Resolve, Na escala (com o valor ou as horas simuladas), Na agenda, Na hora (sim/não), Ativo, ações. Formulário: Identificador (na novo), Nome, Antecedência (dias), Resolve (os tipos), Versão para, ativo, "na hora (Telegram no minuto em que vence)" (caixa), Na escala inteligente (não; no relógio do dia; sempre), Escala: valor do lançamento simulado, Escala: horas da sessão simulada, Data na agenda (só dentro da antecedência; qualquer data), Data prevista (fórmula), Vale quando (fórmula), Texto (até 300).' => 'Tabla Aviso, Versión para, Fecha prevista, Vale cuando, Antelación ("N d"), Resuelve, En la escala (con el valor o las horas simuladas), En la agenda, A la hora (sí/no), Activo, acciones. Formulario: Identificador (en el nuevo), Nombre, Antelación (días), Resuelve (los tipos), Versión para, activo, "a la hora (Telegram en el minuto en que vence)" (casilla), En la escala inteligente (no; en el reloj del día; siempre), Escala: valor del registro simulado, Escala: horas de la sesión simulada, Fecha en la agenda (solo dentro de la antelación; cualquier fecha), Fecha prevista (fórmula), Vale cuando (fórmula), Texto (hasta 300).',
        'Modos de rodízio' => 'Modos de rotación',
        'Tabela Modo ("(ativo)"), Forma de escolha ("· com ciclo"), Blocos (nome e dias), ações (Editar; nos outros: Ativar e Excluir). Formulário: Nome, Planejamento (sorteio pelos blocos; escala inteligente de 7 dias, 30 dias, 60 dias, 6 meses, 1 ano, 2 anos), Forma de escolha, a caixa "ciclo", e a tabela dos blocos (os que existem e duas linhas vazias): Bloco (nome), Dias (caixas seg a dom), Sortear de, Um por (um por dia; um por bloco (na semana)), Relógio fixo ("— sorteia —" e os relógios). Bloco sem dia marcado sai.' => 'Tabla Modo ("(activo)"), Forma de elección ("· con ciclo"), Bloques (nombre y días), acciones (Editar; en los demás: Activar y Eliminar). Formulario: Nombre, Planificación (sorteo por los bloques; escala inteligente de 7 días, 30 días, 60 días, 6 meses, 1 año, 2 años), Forma de elección, la casilla "ciclo", y la tabla de los bloques (los que existen y dos líneas vacías): Bloque (nombre), Días (casillas lun a dom), Sortear de, Uno por (uno por día; uno por bloque (en la semana)), Reloj fijo ("— sortea —" y los relojes). El bloque sin día marcado sale.',
        'Categorias de documentos' => 'Categorías de documentos',
        'Tabela Categoria, Identificador, Aceita ("qualquer arquivo" ou as famílias), Ordem, Documentos, ações (Excluir só sem documentos). Formulário: Nome, Identificador (na nova), Ordem ("vazio: no fim"), Aceita (caixas imagens, vídeos, áudios, PDF, XML).' => 'Tabla Categoría, Identificador, Acepta ("cualquier archivo" o las familias), Orden, Documentos, acciones (Eliminar solo sin documentos). Formulario: Nombre, Identificador (en la nueva), Orden ("vacío: al final"), Acepta (casillas imágenes, vídeos, audios, PDF, XML).',
        'usuarios: salvar, excluir' => 'usuarios: salvar, excluir',
        'h1 "Usuários". Cartão "Quem acessa": tabela Login ("você" em etiqueta azul no próprio), Criado em, e Excluir (menos no próprio; confirma). Cartão "Criar usuário ou trocar senha": Login, Senha (pelo menos 6 caracteres, campo de senha), "Se o login já existir, a senha dele é trocada." e "Salvar usuário". Recusado: o erro no topo.' => 'h1 "Usuarios". Tarjeta "Quién accede": tabla Login ("usted" en etiqueta azul en el propio), Creado el, y Eliminar (menos en el propio; confirma). Tarjeta "Crear usuario o cambiar contraseña": Login, Contraseña (al menos 6 caracteres, campo de contraseña), "Si el login ya existe, se cambia su contraseña." y "Guardar usuario". Rechazado: el error arriba.',
        'ajuda.php#<âncora>' => 'ajuda.php#<ancla>',
        'recurso=manual (o HTML e o sumário)' => 'recurso=manual (el HTML y el sumario)',
        'h1 "Ajuda"; "Nesta página": o sumário com os títulos de nível 2 e 3 (recuados), cada um link para a sua âncora; depois o manual em HTML, com as tabelas que rolam de lado no celular, as imagens com borda e cantos, o código em fonte fixa. Abrindo com uma âncora no endereço, a página vai direto para ela.' => 'h1 "Ayuda"; "En esta página": el sumario con los títulos de nivel 2 y 3 (con sangría), cada uno enlace a su ancla; después el manual en HTML, con las tablas que se desplazan de lado en el móvil, las imágenes con borde y esquinas, el código en fuente fija. Abriendo con un ancla en la dirección, la página va directo a ella.',
        'a página Hoje no computador, com o painel ao lado' => 'la página Hoy en el ordenador, con el panel al lado',
        'a tabela dos relógios com as 12 colunas e os filtros' => 'la tabla de los relojes con las 12 columnas y los filtros',
        'o histórico de um relógio' => 'el historial de un reloj',
        'a aba Campos dos Cadastros' => 'la pestaña Campos de las Definiciones',
        'no celular: a Hoje, os cartões dos relógios e o painel em tela cheia' => 'en el móvil: la Hoy, las tarjetas de los relojes y el panel a pantalla completa',
        'a base de todas as páginas: topo() (o head, o menu e o título) e rodape() (os scripts, com a data do arquivo na URL)' => 'la base de todas las páginas: topo() (el head, el menú y el título) y rodape() (los scripts, con la fecha del archivo en la URL)',
        'o estilo de todas as páginas: as cores, as letras, os controles, os componentes e os tamanhos de tela' => 'el estilo de todas las páginas: los colores, las letras, los controles, los componentes y los tamaños de pantalla',
        'a base do JavaScript das páginas: os textos no idioma (t(), com o dicionário de recurso=textos), ler e gravar pela API, os formatos do idioma (número, dinheiro, data, hora), o login, os formulários que gravam, as tabelas que viram fichas no celular' => 'la base del JavaScript de las páginas: los textos en el idioma (t(), con el diccionario de recurso=textos), leer y guardar por la API, los formatos del idioma (número, dinero, fecha, hora), el inicio de sesión, los formularios que guardan, las tablas que se vuelven fichas en el móvil',
        'os idiomas: a lista (LINGUAS: o nome, o código curto do menu, o locale e os formatos da data e dos números), o idioma do pedido, t() e os formatos no PHP' => 'los idiomas: la lista (LINGUAS: el nombre, el código corto del menú, el locale y los formatos de la fecha y de los números), el idioma de la petición, t() y los formatos en PHP',
        'o arquivo de um idioma (en, zh-CN, hi, es, fr): o texto em português => a tradução, por parte (telas, api, ajuda, manual, reconstrucao), gerado e conferido por testes/textos.php; o que falta sai em português, ou para com erro no modo estrito (TEXTOS_ESTRITO)' => 'el archivo de un idioma (en, zh-CN, hi, es, fr): el texto en portugués => la traducción, por parte (telas, api, ajuda, manual, reconstrucao), generado y comprobado por testes/textos.php; lo que falta sale en portugués, o se para con error en el modo estricto (TEXTOS_ESTRITO)',
        'o esqueleto da página Hoje (o meio, a tabela dos relógios com os títulos e os filtros, e o painel)' => 'el esqueleto de la página Hoy (el centro, la tabla de los relojes con los títulos y los filtros, y el panel)',
        'a página Hoje: o relógio do dia, os avisos de hoje, os próximos dias, o modo de rodízio e as linhas da tabela dos relógios' => 'la página Hoy: el reloj del día, los avisos de hoy, los próximos días, el modo de rotación y las filas de la tabla de los relojes',
        'a tabela dos relógios: ordenar, filtrar e virar cartões quando as 12 colunas não cabem' => 'la tabla de los relojes: ordenar, filtrar y volverse tarjetas cuando las 12 columnas no caben',
        'o painel do relógio (na página Hoje e na Ficha): os quadros, o Marcar, o Editar cadastro, o gráfico da carga, os dados e o histórico' => 'el panel del reloj (en la página Hoy y en la Ficha): los cuadros, el Marcar, el Editar ficha, el gráfico de la carga, los datos y el historial',
        'a foto reduzida no navegador antes de enviar (1200 px, JPEG 85%), com a prévia' => 'la foto reducida en el navegador antes de enviar (1200 px, JPEG 85%), con la vista previa',
        'a página Ficha do relógio: o painel do relógio numa página própria' => 'la página Ficha del reloj: el panel del reloj en una página propia',
        'o esqueleto da página Plano' => 'el esqueleto de la página Plan',
        'a página Plano: o resumo do período e o dia a dia, mês a mês' => 'la página Plan: el resumen del período y el día a día, mes a mes',
        'o esqueleto da página Configuração' => 'el esqueleto de la página Configuración',
        'a página Configuração: o banco desatualizado, os quadros das opções, as mensagens, o que vai para onde, os eventos e como sai hoje' => 'la página Configuración: la base de datos desactualizada, los cuadros de las opciones, los mensajes, qué va a dónde, los eventos y cómo sale hoy',
        'o esqueleto da página Critérios' => 'el esqueleto de la página Criterios',
        'a página Critérios: as explicações, os lugares, os parâmetros, os subparâmetros, as faixas e a nota de cada relógio' => 'la página Criterios: las explicaciones, los lugares, los parámetros, los subparámetros, los rangos y la nota de cada reloj',
        'o esqueleto da página Grupos' => 'el esqueleto de la página Grupos',
        'a página Grupos: a árvore e o grupo de cada relógio' => 'la página Grupos: el árbol y el grupo de cada reloj',
        'o esqueleto da página Execuções do cron' => 'el esqueleto de la página Ejecuciones del cron',
        'a página Execuções do cron: os filtros, o resumo, a tabela e a paginação' => 'la página Ejecuciones del cron: los filtros, el resumen, la tabla y la paginación',
        'o esqueleto da página Desejos' => 'el esqueleto de la página Deseos',
        'a página Desejos: a lista de desejos (com o Comprei) e os relógios fora da coleção' => 'la página Deseos: la lista de deseos (con el Lo compré) y los relojes fuera de la colección',
        'o esqueleto da página Estatísticas' => 'el esqueleto de la página Estadísticas',
        'o esqueleto da página Hora certa' => 'el esqueleto de la página Hora exacta',
        'o esqueleto da página Acessórios' => 'el esqueleto de la página Accesorios',
        'o esqueleto da página Galeria' => 'el esqueleto de la página Galería',
        'a página Galeria: a coleção em fotos, por grupo, para ver e imprimir' => 'la página Galería: la colección en fotos, por grupo, para ver e imprimir',
        'o esqueleto da página Passaporte do relógio' => 'el esqueleto de la página Pasaporte del reloj',
        'a página Passaporte: a ficha de um relógio para imprimir ou guardar em PDF' => 'la página Pasaporte: la ficha de un reloj para imprimir o guardar en PDF',
        'a página Acessórios: o filtro por relógio, a lista com Editar e Excluir e o cadastro' => 'la página Accesorios: el filtro por reloj, la lista con Editar y Eliminar y la ficha',
        'a página Hora certa: o mostrador e a hora digital andando, acertados pela API, e os quadros do fuso, do calendário e da lua' => 'la página Hora exacta: la esfera y la hora digital avanzando, puestas en hora por la API, y los cuadros del huso, del calendario y de la luna',
        'a página Estatísticas: o período, o resumo, cada relógio, os gráficos em SVG e a coleção' => 'la página Estadísticas: el período, el resumen, cada reloj, los gráficos en SVG y la colección',
        'o esqueleto da página Histórico' => 'el esqueleto de la página Historial',
        'a página Histórico de um relógio: os filtros, o resumo do tempo e a linha do tempo' => 'la página Historial de un reloj: los filtros, el resumen del tiempo y la línea de tiempo',
        'o esqueleto da página Documentos' => 'el esqueleto de la página Documentos',
        'a página Documentos: o envio, as abas, a galeria com o visor, os vídeos, os PDFs, as NF-e e a edição' => 'la página Documentos: el envío, las pestañas, la galería con el visor, los vídeos, los PDF, las NF-e y la edición',
        'o esqueleto da página Cadastros' => 'el esqueleto de la página Definiciones',
        'a página Cadastros: as abas Campos, Tipos de lançamento, Fórmulas, Avisos, Modos de rodízio e Categorias de documentos' => 'la página Definiciones: las pestañas Campos, Tipos de registro, Fórmulas, Avisos, Modos de rotación y Categorías de documentos',
        'o esqueleto da página Usuários' => 'el esqueleto de la página Usuarios',
        'a página Usuários: quem acessa e criar usuário ou trocar a senha' => 'la página Usuarios: quién accede y crear usuario o cambiar la contraseña',
        'o esqueleto da página Ajuda' => 'el esqueleto de la página Ayuda',
        'a página Ajuda: o sumário e o manual em HTML (recurso=manual)' => 'la página Ayuda: el sumario y el manual en HTML (recurso=manual)',
        'a API, a porta única: a autenticação, o formato, a ordem dos recursos (cada um no seu arquivo da pasta api/, ou ali mesmo, os pequenos), os filtros, o JSON e o XML, e no cabeçalho a documentação inteira' => 'la API, la puerta única: la autenticación, el formato, el orden de los recursos (cada uno en su archivo de la carpeta api/, o allí mismo, los pequeños), los filtros, el JSON y el XML, y en la cabecera la documentación entera',
        'as funções que só a API usa (o XML, os textos legíveis do tempo, do plano, dos eventos e da agenda, os filtros das listas e a resposta) e o tratamento dos erros' => 'las funciones que solo usa la API (el XML, los textos legibles del tiempo, del plan, de los eventos y de la agenda, los filtros de las listas y la respuesta) y el tratamiento de los errores',
        'api.php sem recurso: tudo o que está guardado' => 'api.php sin recurso: todo lo que está guardado',
        'recurso=hoje: tudo o que a página Hoje mostra' => 'recurso=hoje: todo lo que muestra la página Hoy',
        'recurso=ficha: tudo o que o painel de um relógio mostra (ou o cadastro de um novo)' => 'recurso=ficha: todo lo que muestra el panel de un reloj (o la ficha de uno nuevo)',
        'recurso=config: a Configuração inteira' => 'recurso=config: la Configuración entera',
        'recurso=desejos: a lista de desejos e os relógios fora da coleção' => 'recurso=desejos: la lista de deseos y los relojes fuera de la colección',
        'recurso=passaporte: a ficha de um relógio para imprimir, tudo já em texto' => 'recurso=passaporte: la ficha de un reloj para imprimir, todo ya en texto',
        'recurso=galeria: a coleção em fotos, por grupo' => 'recurso=galeria: la colección en fotos, por grupo',
        'recurso=hora_certa: a hora do servidor, o fuso, o UTC, a letra militar, o calendário e a lua (sem banco)' => 'recurso=hora_certa: la hora del servidor, el huso, el UTC, la letra militar, el calendario y la luna (sin base de datos)',
        'recurso=estatisticas: o uso da coleção num período, por relógio, dia da semana e mês, e a distribuição da coleção' => 'recurso=estatisticas: el uso de la colección en un período, por reloj, día de la semana y mes, y la distribución de la colección',
        'recurso=historico: a linha do tempo de um relógio, com os filtros e o resumo' => 'recurso=historico: la línea de tiempo de un reloj, con los filtros y el resumen',
        'recurso=plano: o plano dia a dia, o resumo por relógio e as páginas' => 'recurso=plano: el plan día a día, el resumen por reloj y las páginas',
        'recurso=cron: as execuções do cron, com os filtros, o resumo e as páginas' => 'recurso=cron: las ejecuciones del cron, con los filtros, el resumen y las páginas',
        'recurso=arvore: a árvore dos grupos e o grupo de cada relógio' => 'recurso=arvore: el árbol de los grupos y el grupo de cada reloj',
        'recurso=cadastros: os campos, os tipos de lançamento, as fórmulas, os avisos, os modos e as categorias' => 'recurso=cadastros: los campos, los tipos de registro, las fórmulas, los avisos, los modos y las categorías',
        'recurso=calcular: o resultado de uma fórmula para um relógio (ou para todos)' => 'recurso=calcular: el resultado de una fórmula para un reloj (o para todos)',
        'recurso=documentos: os documentos de um relógio (ou de todos), as categorias e o limite' => 'recurso=documentos: los documentos de un reloj (o de todos), las categorías y el límite',
        'recurso=documento: um arquivo de um documento (o original, a miniatura, a página de um PDF)' => 'recurso=documento: un archivo de un documento (el original, la miniatura, la página de un PDF)',
        'recurso=backup: as cópias de segurança da pasta, e uma cópia para baixar (arquivo=)' => 'recurso=backup: las copias de seguridad de la carpeta, y una copia para descargar (arquivo=)',
        'recurso=migracoes: as migrações pendentes do banco (a leitura) e aplicar (a escrita)' => 'recurso=migracoes: las migraciones pendientes de la base de datos (la lectura) y aplicar (la escritura)',
        'recurso=codigo: o código do sistema como está agora, arquivo por arquivo' => 'recurso=codigo: el código del sistema como está ahora, archivo por archivo',
        'recurso=ajuda: a documentação da API (cada consulta, cada escrita e o dicionário dos campos, a fonte única dele)' => 'recurso=ajuda: la documentación de la API (cada consulta, cada escritura y el diccionario de los campos, su fuente única)',
        'as escritas (POST): cada recurso e ação vai para a função dele no operacoes.php, que valida, grava e responde' => 'las escrituras (POST): cada recurso y acción va a su función en el operacoes.php, que valida, guarda y responde',
        'o núcleo: o token, o login, a árvore, os campos, os lançamentos, o motor das fórmulas, os avisos, os critérios, o rodízio, a escala e as listas do código' => 'el núcleo: el token, el inicio de sesión, el árbol, los campos, los registros, el motor de las fórmulas, los avisos, los criterios, la rotación, la escala y las listas del código',
        'as escritas: cada ação valida, grava e devolve ok, mensagem e erros (a API chama estas funções)' => 'las escrituras: cada acción valida, guarda y devuelve ok, mensaje y erros (la API llama a estas funciones)',
        'o banco: MySQL/MariaDB, PostgreSQL, SQLite ou Firebird, o SQL escrito uma vez só e traduzido para cada um, e o catálogo do modelo' => 'la base de datos: MySQL/MariaDB, PostgreSQL, SQLite o Firebird, el SQL escrito una sola vez y traducido a cada uno, y el catálogo del modelo',
        'a reconstrução (recurso=reconstrucao): as regras de cada parte, a especificação das telas e esta lista do código' => 'la reconstrucción (recurso=reconstrucao): las reglas de cada parte, la especificación de las pantallas y esta lista del código',
        'o cron, a cada minuto: as mensagens, o pulso sozinho, a agenda, a manutenção dos documentos, sempre mudo e registrado no banco' => 'el cron, cada minuto: los mensajes, la muñeca sola, la agenda, el mantenimiento de los documentos, siempre mudo y registrado en la base de datos',
        'a instalação pelo servidor (a mesma do POST recurso=instalacao)' => 'la instalación por el servidor (la misma del POST recurso=instalacao)',
        'a importação do sistema antigo pelo servidor (a mesma do POST recurso=importacao)' => 'la importación del sistema antiguo por el servidor (la misma del POST recurso=importacao)',
        'criar um usuário ou trocar a senha pelo servidor (o mesmo do POST recurso=usuarios, acao=salvar)' => 'crear un usuario o cambiar la contraseña por el servidor (lo mismo del POST recurso=usuarios, acao=salvar)',
        'o banco inicial (no dialeto do MySQL, traduzido para os outros) e o cadastro que vem pronto, com os critérios iniciais' => 'la base de datos inicial (en el dialecto de MySQL, traducido a los demás) y el conjunto que viene listo, con los criterios iniciales',
        'o modelo do config.php, com cada constante explicada (o config.php de verdade não sai: veja nao_mostrados)' => 'el modelo del config.php, con cada constante explicada (el config.php de verdad no sale: vea nao_mostrados)',
        'o Apache: o que abre pelo navegador e o que fica bloqueado' => 'el Apache: lo que se abre por el navegador y lo que queda bloqueado',
        'o nginx: o mesmo bloqueio do .htaccess' => 'el nginx: el mismo bloqueo del .htaccess',
        'o roteiro de aceitação: faz pela API o que uma pessoa faz e tira a fotografia de tudo o que a API devolve' => 'el guion de aceptación: hace por la API lo que hace una persona y saca la fotografía de todo lo que devuelve la API',
        'compara duas fotografias do cenário (os quatro bancos, ou a reescrita com a versão atual)' => 'compara dos fotografías del escenario (los cuatro bancos, o la reescritura con la versión actual)',
        'o teste de paridade com um comando: os quatro bancos ao mesmo tempo, numa pasta temporária, e a comparação' => 'la prueba de paridad con un comando: los cuatro bancos a la vez, en una carpeta temporal, y la comparación',
        'o config dos testes (o acesso aos bancos pelo ambiente), apontado por RELOGIOS_CONFIG: o config.php de verdade fica intocado' => 'el config de las pruebas (el acceso a las bases de datos por el entorno), apuntado por RELOGIOS_CONFIG: el config.php de verdad queda intacto',
        'gera o dicionário dos campos do cabeçalho do api.php a partir do da ajuda (a fonte única), e confere que batem' => 'genera el diccionario de los campos de la cabecera de api.php a partir del de la ayuda (la fuente única), y comprueba que coinciden',
        'confere que todo campo das respostas da API está explicado no dicionário da ajuda' => 'comprueba que todo campo de las respuestas de la API está explicado en el diccionario de la ayuda',
        'a conferência do layout: todas as telas num navegador, em 15 tamanhos, com dados de estresse, procurando o que quebra' => 'la comprobación del layout: todas las pantallas en un navegador, en 15 tamaños, con datos de estrés, buscando lo que se rompe',
        'como rodar o teste de paridade e a conferência do layout' => 'cómo ejecutar la prueba de paridad y la comprobación del layout',
        'o manual inteiro: para quem usa, a instalação, a API e como é por dentro' => 'el manual entero: para quien lo usa, la instalación, la API y cómo es por dentro',
        'o que o sistema antigo fazia e onde está no novo' => 'lo que hacía el sistema antiguo y dónde está en el nuevo',
        'a licença' => 'la licencia',
        'o que nunca entra no repositório (a configuração, as chaves, os bancos)' => 'lo que nunca entra en el repositorio (la configuración, las claves, las bases de datos)',
        'as quebras de linha (LF em tudo) e os binários' => 'los saltos de línea (LF en todo) y los binarios',
        'os testes no GitHub a cada push no main: a paridade nos bancos (com a documentação da API) e o layout das telas' => 'las pruebas en GitHub en cada push en main: la paridad en las bases de datos (con la documentación de la API) y el layout de las pantallas',
        'confere os dicionários dos idiomas com o código (o texto que falta, o que sobra, o parâmetro diferente) e a origem de cada manual traduzido; junta traduções novas (--juntar)' => 'compara los diccionarios de los idiomas con el código (el texto que falta, el que sobra, el parámetro distinto) y el origen de cada manual traducido; junta traducciones nuevas (--juntar)',
        'a conferência da arquitetura: as páginas sem banco, a rede das telas só pela API, o banco só no núcleo, na API e no cron, os scripts de linha de comando como atalhos da API, a guarda do api/, o bloqueio pela web, a API e o config.php documentados, as migrações e o repositório' => 'la comprobación de la arquitectura: las páginas sin base, la red de las pantallas solo por la API, la base solo en el núcleo, la API y el cron, los scripts de línea de comandos como atajos de la API, la guarda de api/, el bloqueo por la web, la API y el config.php documentados, las migraciones y el repositorio',
        'monta o README de cada idioma (README.<idioma>.md) a partir do manual traduzido e do resto traduzido, e confere que estão em dia (--conferir)' => 'arma el README de cada idioma (README.<idioma>.md) a partir del manual traducido y del resto traducido, y comprueba que están al día (--conferir)',
        'o dicionário do idioma {1}: o texto em português => a tradução, por parte (telas, api, cadastro, ajuda, reconstrucao)' => 'el diccionario del idioma {1}: el texto en portugués => la traducción, por parte (telas, api, cadastro, ajuda, reconstrucao)',
        'o manual da página Ajuda no idioma {1} (as seções do README para quem usa), com a origem na primeira linha' => 'el manual de la página Ayuda en el idioma {1} (las secciones del README para quien usa), con el origen en la primera línea',
        'o resto do README no idioma {1} (o que não está no manual), com a origem na primeira linha' => 'el resto del README en el idioma {1} (lo que no está en el manual), con el origen en la primera línea',
        'o README no idioma {1}, montado por testes/readme.php (não editar à mão)' => 'el README en el idioma {1}, armado por testes/readme.php (no editar a mano)',
        'tem as senhas do banco e o API_TOKEN' => 'tiene las contraseñas de la base de datos y el API_TOKEN',
        'o config.exemplo.php (o modelo, com cada constante explicada) e listas.config_php no recurso=reconstrucao' => 'el config.exemplo.php (el modelo, con cada constante explicada) y listas.config_php en recurso=reconstrucao',
        'a chave JSON do Google (google-conta-servico.json ou o caminho da Configuração)' => 'la clave JSON de Google (google-conta-servico.json o el camino de la Configuración)',
        'é uma credencial' => 'es una credencial',
        'a seção mensagens do recurso=reconstrucao e o README (Google Agenda): como criar a conta de serviço e a chave' => 'la sección mensajes de recurso=reconstrucao y el README (Google Calendar): cómo crear la cuenta de servicio y la clave',
        'o banco de dados (o servidor MySQL/PostgreSQL/Firebird, ou o arquivo do SQLite)' => 'la base de datos (el servidor MySQL/PostgreSQL/Firebird, o el archivo de SQLite)',
        'são os dados, não o código' => 'son los datos, no el código',
        'o modelo em modelo_de_dados (recurso=reconstrucao) e os dados pela própria API (api.php sem recurso: tudo o que está guardado)' => 'el modelo en modelo_de_dados (recurso=reconstrucao) y los datos por la propia API (api.php sin recurso: todo lo que está guardado)',
        'a pasta dos documentos (DOCUMENTOS_PASTA)' => 'la carpeta de los documentos (DOCUMENTOS_PASTA)',
        'são os arquivos de cada relógio, não o código' => 'son los archivos de cada reloj, no el código',
        'recurso=documentos (a lista) e recurso=documento (cada arquivo)' => 'recurso=documentos (la lista) y recurso=documento (cada archivo)',
        'as senhas dos usuários' => 'las contraseñas de los usuarios',
        'não existem no sistema: só o hash' => 'no existen en el sistema: solo el hash',
        'recurso=usuarios (o login e o hash) e senhas na ajuda (como conferir e migrar)' => 'recurso=usuarios (el login y el hash) y senhas en la ayuda (cómo comprobar y migrar)',
        'a migração ' => 'la migración ',
        'a captura de tela: ' => 'la captura de pantalla: ',
        'text/plain; charset=utf-8' => 'text/plain; charset=utf-8',
        'O código do sistema como está agora, lido do disco na hora: cada arquivo com a camada, o que ele é, o tamanho e o SHA-256. Um arquivo: arquivo=<nome> (o conteúdo como está, em conteudo; a imagem em conteudo_base64); com cru=1, o arquivo puro, sem JSON (texto como text/plain, para ler no navegador). Numa página, html traz o HTML que o navegador recebe, já montado (html=1 com cru=1: só ele), e usa, os arquivos que ela carrega. Todos de uma vez: conteudo=1 (com os filtros: f[arquivos][camada]=tela traz o HTML, o CSS e o JavaScript das telas). O que fica de fora de propósito está em nao_mostrados, com o que ver no lugar.' => 'El código del sistema como está ahora, leído del disco en el momento: cada archivo con la capa, qué es, el tamaño y el SHA-256. Un archivo: arquivo=<nombre> (el contenido como está, en conteudo; la imagen en conteudo_base64); con cru=1, el archivo puro, sin JSON (texto como text/plain, para leer en el navegador). En una página, html trae el HTML que recibe el navegador, ya montado (html=1 con cru=1: solo él), y usa, los archivos que carga. Todos de una vez: conteudo=1 (con los filtros: f[arquivos][camada]=tela trae el HTML, el CSS y el JavaScript de las pantallas). Lo que queda fuera a propósito está en nao_mostrados, con qué ver en su lugar.',
        'as páginas: o esqueleto em PHP, o estilo e o JavaScript que lê a API e monta a tela' => 'las páginas: el esqueleto en PHP, el estilo y el JavaScript que lee la API y monta la pantalla',
        'o back-end: a API e o que ela usa (o núcleo, as escritas, o banco, a reconstrução)' => 'el back-end: la API y lo que usa (el núcleo, las escrituras, la base de datos, la reconstrucción)',
        'o cron e os scripts do servidor' => 'el cron y los scripts del servidor',
        'o banco inicial e as migrações' => 'la base de datos inicial y las migraciones',
        'a configuração do servidor web e o modelo do config.php' => 'la configuración del servidor web y el modelo del config.php',
        'o roteiro de aceitação e a comparação' => 'el guion de aceptación y la comparación',
        'o README e os outros textos' => 'el README y los otros textos',
        'os arquivos do git' => 'los archivos de git',
        'as capturas das telas' => 'las capturas de las pantallas',
        ' ou mais' => ' o más',
        'O Relojoeiro (Relógios 2) planeja o rodízio de uma coleção de relógios: escolhe o relógio de cada dia pela nota de cada um (critérios com pesos) e pelas regras do modo de rodízio, acompanha a energia de cada um (bateria, reserva de marcha, carga de luz, vida da pilha) pelas fórmulas do cadastro e pelo histórico de lançamentos, avisa o que fazer (carregar, dar corda, pôr no sol, trocar a pilha, revisão) pelo Telegram e pelo Google Agenda, mede o gasto real da bateria pelas leituras e guarda os documentos de cada relógio. Esta resposta é o roteiro para reescrever o sistema inteiro do zero e chegar ao mesmo comportamento.' => 'El Relojoeiro (Relojes 2) planifica la rotación de una colección de relojes: elige el reloj de cada día por la nota de cada uno (criterios con pesos) y por las reglas del modo de rotación, sigue la energía de cada uno (batería, reserva de marcha, carga de luz, vida de la pila) por las fórmulas de la ficha y por el historial de registros, avisa qué hacer (cargar, dar cuerda, poner al sol, cambiar la pila, revisión) por Telegram y por Google Calendar, mide el consumo real de la batería por las lecturas y guarda los documentos de cada reloj. Esta respuesta es el guion para reescribir el sistema entero desde cero y llegar al mismo comportamiento.',
        'Leia as seções na ordem: os princípios e a arquitetura, a ordem de construção, e cada módulo com as suas regras.' => 'Lea las secciones en orden: los principios y la arquitectura, el orden de construcción, y cada módulo con sus reglas.',
        'O modelo de dados (modelo_de_dados) é o do banco em uso agora, lido dele: tabelas, colunas, chaves, índices e regras de validação. Os tipos vêm no dialeto desse banco; o dialeto de referência (MySQL) está no schema.sql.' => 'El modelo de datos (modelo_de_dados) es el de la base de datos en uso ahora, leído de ella: tablas, columnas, claves, índices y reglas de validación. Los tipos vienen en el dialecto de esa base de datos; el dialecto de referencia (MySQL) está en el schema.sql.',
        'O contrato da API (cada consulta com parâmetros e exemplo, cada escrita com ações e campos, e o significado de cada campo das respostas) está em api.php?recurso=ajuda: a reescrita deve responder igual, para as telas, os scripts e quem integra continuarem funcionando.' => 'El contrato de la API (cada consulta con parámetros y ejemplo, cada escritura con acciones y campos, y el significado de cada campo de las respuestas) está en api.php?recurso=ajuda: la reescritura debe responder igual, para que las pantallas, los scripts y quien integra sigan funcionando.',
        'O conhecimento sobre relógios não está no código: está no cadastro inicial (schema.sql, a partir de "-- critérios iniciais" para os critérios; os campos, os tipos de lançamento, as fórmulas, os avisos e os modos nas migrações). Leia também por recurso=cadastros e recurso=criterios. A reescrita traz esse cadastro como dado, não como código.' => 'El conocimiento sobre relojes no está en el código: está en el conjunto inicial (schema.sql, a partir de "-- criterios iniciales" para los criterios; los campos, los tipos de registro, las fórmulas, los avisos y los modos en las migraciones). Léalo también por recurso=cadastros y recurso=criterios. La reescritura trae ese conjunto como dato, no como código.',
        'As telas (telas) são a especificação visual: o visual com os valores exatos, o menu e cada página, parte por parte, com cada tabela, campo, botão e mensagem, palavra por palavra. A reescrita reproduz a mesma interface, não uma parecida: o que está lá existe, e o que não está não existe. As capturas em docs/telas/ mostram o resultado.' => 'Las pantallas (telas) son la especificación visual: el visual con los valores exactos, el menú y cada página, parte por parte, con cada tabla, campo, botón y mensaje, palabra por palabra. La reescritura reproduce la misma interfaz, no una parecida: lo que está ahí existe, y lo que no está no existe. Las capturas en docs/telas/ muestran el resultado.',
        'O código de verdade, como está agora, sai pelo recurso=codigo (a lista em codigo, abaixo): o CSS, o JavaScript, cada página e o HTML que ela entrega ao navegador, a API, o banco e o resto, lido do disco na hora (arquivo=<nome>; cru=1 para o arquivo puro). Cada página em telas diz os arquivos dela (codigo). O que não sai (o config.php, as chaves, os dados) está em codigo.nao_mostrados, com o que ver no lugar.' => 'El código de verdad, como está ahora, sale por recurso=codigo (la lista en codigo, abajo): el CSS, el JavaScript, cada página y el HTML que entrega al navegador, la API, la base de datos y el resto, leído del disco en el momento (arquivo=<nombre>; cru=1 para el archivo puro). Cada página en telas dice sus archivos (codigo). Lo que no sale (el config.php, las claves, los datos) está en codigo.nao_mostrados, con qué ver en su lugar.',
        'O README.md explica cada tela e cada opção para quem usa (as seções para quem usa saem também pela API, em recurso=manual: o texto da página Ajuda); o testes/cenario.php é o roteiro de aceitação (veja a seção testes).' => 'El README.md explica cada pantalla y cada opción para quien lo usa (las secciones para quien lo usa salen también por la API, en recurso=manual: el texto de la página Ayuda); el testes/cenario.php es el guion de aceptación (vea la sección testes).',
        'Os princípios (não negociáveis)' => 'Los principios (no negociables)',
        'O sistema não sabe nada de relógios: o código tem só mecanismos (árvore, campos, tipos de lançamento, fórmulas, avisos, critérios, modos). Que um automático tem reserva de marcha, ou que um solar carrega no sol, está escrito em fórmulas cadastradas, que o usuário lê, edita e testa pela tela. Mudar uma regra de relógio é mudar cadastro (com uma migração), não código.' => 'El sistema no sabe nada de relojes: el código tiene solo mecanismos (árbol, campos, tipos de registro, fórmulas, avisos, criterios, modos). Que un automático tiene reserva de marcha, o que un solar carga al sol, está escrito en fórmulas definidas, que el usuario lee, edita y prueba por la pantalla. Cambiar una regla de reloj es cambiar la ficha (con una migración), no el código.',
        'Tudo pela API: as páginas só desenham; toda leitura e toda gravação passa pela API, a mesma que um script usa. Nenhuma regra de negócio no navegador além de mostrar e esconder campos.' => 'Todo por la API: las páginas solo dibujan; toda lectura y todo guardado pasa por la API, la misma que usa un script. Ninguna regla de negocio en el navegador aparte de mostrar y ocultar campos.',
        'Falha segura: sem token válido, com o fuso inválido ou com o banco desatualizado (migração pendente), o sistema para e diz o motivo (a API responde 500 ou 503, o cron registra e não faz nada), em vez de rodar pela metade.' => 'Fallo seguro: sin token válido, con el huso no válido o con la base de datos desactualizada (migración pendiente), el sistema se para y dice el motivo (la API responde 500 o 503, el cron registra y no hace nada), en vez de funcionar a medias.',
        'O banco se defende: relacional e normalizado, toda ligação é chave estrangeira (obrigatória: some junto, ON DELETE CASCADE; opcional: a ligação se desfaz, SET NULL), nenhuma lista guardada como texto, e regras de validação (CHECK, NOT NULL, UNIQUE) iguais às da tela. Uma gravação errada é recusada pelo banco venha de onde vier (a API responde 409 com a regra quebrada).' => 'La base de datos se defiende: relacional y normalizada, toda relación es clave foránea (obligatoria: desaparece junto, ON DELETE CASCADE; opcional: la relación se deshace, SET NULL), ninguna lista guardada como texto, y reglas de validación (CHECK, NOT NULL, UNIQUE) iguales a las de la pantalla. Un guardado erróneo lo rechaza la base de datos venga de donde venga (la API responde 409 con la regla rota).',
        'Os mesmos resultados em MySQL/MariaDB, PostgreSQL, SQLite e Firebird: o SQL do sistema é escrito uma vez só; o que muda de banco para banco fica numa camada de tradução. Maiúsculas e acentos não contam nos textos curtos ("Relógio" = "RELOGIO"), em todos; no MySQL/MariaDB, toda tabela em utf8mb4_unicode_ci (a utf8mb4_general_ci, padrão do MariaDB, ordena diferente); no Firebird, a collation UNICODE_CI_AI.' => 'Los mismos resultados en MySQL/MariaDB, PostgreSQL, SQLite y Firebird: el SQL del sistema se escribe una sola vez; lo que cambia de base de datos a base de datos queda en una capa de traducción. Las mayúsculas y los acentos no cuentan en los textos cortos ("Relógio" = "RELOGIO"), en todos; en MySQL/MariaDB, toda tabla en utf8mb4_unicode_ci (la utf8mb4_general_ci, predeterminada de MariaDB, ordena distinto); en Firebird, la collation UNICODE_CI_AI.',
        'Datas e horas no fuso do sistema (FUSO). Nas fórmulas, o tempo é contado em dias no horário local: a meia-noite local de qualquer data é um número inteiro e a fração é a hora do dia; assim uma data e o agora entram na mesma conta sem o fuso aparecer.' => 'Fechas y horas en el huso del sistema (FUSO). En las fórmulas, el tiempo se cuenta en días en la hora local: la medianoche local de cualquier fecha es un número entero y la fracción es la hora del día; así una fecha y el ahora entran en la misma cuenta sin que aparezca el huso.',
        'O cron é mudo e rastreável: roda a cada minuto, não escreve na saída, e registra no banco o que fez.' => 'El cron es mudo y rastreable: se ejecuta cada minuto, no escribe en la salida, y registra en la base de datos lo que hizo.',
        'Mensagens que explicam o que fazer ("Dê um nome ao relógio (até 120 caracteres)."), em seis idiomas: português (o original), inglês, chinês simplificado, hindi, espanhol e francês. Nenhum texto fixo: todo texto que alguém lê passa por t("o texto em português", parâmetros), com o português como chave (como no gettext) e os parâmetros entre chaves ({1}, {nome}) trocados depois da tradução; cada idioma tem o seu dicionário (o texto em português => a tradução), e o que falta sai em português. O idioma de cada pessoa é dela (o seletor do menu, guardado no navegador); quem não escolheu vê o padrão da instalação (config.idioma), senão o do navegador, senão português. As datas e os números seguem o idioma. Os nomes cadastrados ficam como foram escritos.' => 'Mensajes que explican qué hacer ("Ponga un nombre al reloj (hasta 120 caracteres)."), en seis idiomas: portugués (el original), inglés, chino simplificado, hindi, español y francés. Ningún texto fijo: todo texto que alguien lee pasa por t("el texto en portugués", parámetros), con el portugués como clave (como en gettext) y los parámetros entre llaves ({1}, {nome}) cambiados después de la traducción; cada idioma tiene su diccionario (el texto en portugués => la traducción), y lo que falta sale en portugués. El idioma de cada persona es suyo (el selector del menú, guardado en el navegador); quien no eligió ve el predeterminado de la instalación (config.idioma), si no el del navegador, si no portugués. Las fechas y los números siguen el idioma. Los nombres definidos se quedan como se escribieron.',
        'A arquitetura' => 'La arquitectura',
        'Um back-end único, a API (api.php): GET lê (recurso=...), POST grava (recurso=... e acao=...). Responde JSON (ou XML com formato=xml). O api.php faz a porta (a autenticação, o formato, a ordem dos recursos, os filtros e a resposta); cada recurso grande fica num arquivo da pasta api/ (api/hoje.php, api/ficha.php, api/ajuda.php...), que roda dentro dele, com as mesmas variáveis. Autenticação em todo pedido: o token (cabeçalho X-Api-Token ou parâmetro token, igual ao API_TOKEN) ou o login do site (HTTP Basic com usuário e senha da tabela usuario, senha com password_hash).' => 'Un back-end único, la API (api.php): GET lee (recurso=...), POST guarda (recurso=... y acao=...). Responde JSON (o XML con formato=xml). El api.php hace la puerta (la autenticación, el formato, el orden de los recursos, los filtros y la respuesta); cada recurso grande queda en un archivo de la carpeta api/ (api/hoje.php, api/ficha.php, api/ajuda.php...), que se ejecuta dentro de él, con las mismas variables. Autenticación en toda petición: el token (cabecera X-Api-Token o parámetro token, igual al API_TOKEN) o el inicio de sesión del sitio (HTTP Basic con usuario y contraseña de la tabla usuario, contraseña con password_hash).',
        'Um núcleo (lib.php): o motor das fórmulas, as variáveis de cada relógio, os avisos, as notas, o plano, a escala, a previsão, o gasto medido, o pulso sozinho, a linha do tempo, as mensagens, a agenda e os documentos.' => 'Un núcleo (lib.php): el motor de las fórmulas, las variables de cada reloj, los avisos, las notas, el plan, la escala, la previsión, el consumo medido, la muñeca sola, la línea de tiempo, los mensajes, la agenda y los documentos.',
        'As gravações (operacoes.php): uma função por recurso (op_relogio, op_lancamento, op_campos...), que valida tudo, grava e devolve {ok, mensagem, erros[], ...}. A tela e a API chamam as mesmas.' => 'Los guardados (operacoes.php): una función por recurso (op_relogio, op_lancamento, op_campos...), que lo valida todo, guarda y devuelve {ok, mensagem, erros[], ...}. La pantalla y la API llaman a las mismas.',
        'O banco (banco.php): a conexão com as extensões do PHP (mysqli, pgsql, sqlite3, pdo_firebird), parâmetros sempre por ? (nunca texto colado no SQL), e a tradução do dialeto do MySQL para os outros: AUTO_INCREMENT, ENUM (vira CHECK ... IN), TINYINT, DATETIME, os INDEX dentro do CREATE TABLE, AFTER, MODIFY COLUMN (o SQLite refaz a tabela), INSERT IGNORE, REPLACE INTO, NOW(), <=>, LIKE sem diferenciar maiúsculas; no Firebird, também LIMIT/OFFSET (OFFSET ... ROWS FETCH NEXT ... ROWS ONLY), DATE(x) (CAST AS DATE), CONCAT (||), LENGTH/LEAST/GREATEST (OCTET_LENGTH/MINVALUE/MAXVALUE), o SELECT sem FROM (FROM RDB$DATABASE), o INSERT de várias linhas (um por linha), a tabela no (palavra reservada: "NO"), nomes de índice e de regra com até 31 letras, o TEXT como VARCHAR(8191) e a chave única de várias colunas com coluna vazia como índice único de uma expressão; e três comandos próprios das migrações: ALTER FOREIGN KEY, DROP COLUMN e ADD CONSTRAINT ... CHECK (trocando a regra sem perder a anterior se os dados não cumprem a nova).' => 'La base de datos (banco.php): la conexión con las extensiones de PHP (mysqli, pgsql, sqlite3, pdo_firebird), parámetros siempre por ? (nunca texto pegado en el SQL), y la traducción del dialecto de MySQL a los demás: AUTO_INCREMENT, ENUM (se vuelve CHECK ... IN), TINYINT, DATETIME, los INDEX dentro del CREATE TABLE, AFTER, MODIFY COLUMN (SQLite rehace la tabla), INSERT IGNORE, REPLACE INTO, NOW(), <=>, LIKE sin diferenciar mayúsculas; en Firebird, también LIMIT/OFFSET (OFFSET ... ROWS FETCH NEXT ... ROWS ONLY), DATE(x) (CAST AS DATE), CONCAT (||), LENGTH/LEAST/GREATEST (OCTET_LENGTH/MINVALUE/MAXVALUE), el SELECT sin FROM (FROM RDB$DATABASE), el INSERT de varias líneas (uno por línea), la tabla no (palabra reservada: "NO"), nombres de índice y de regla con hasta 31 letras, el TEXT como VARCHAR(8191) y la clave única de varias columnas con columna vacía como índice único de una expresión; y tres comandos propios de las migraciones: ALTER FOREIGN KEY, DROP COLUMN y ADD CONSTRAINT ... CHECK (cambiando la regla sin perder la anterior si los datos no cumplen la nueva).',
        'As páginas (index.php, plano.php, desejos.php, estatisticas.php, hora.php, acessorios.php, galeria.php, passaporte.php, ficha.php, documentos.php, historico.php, configuracao.php, criterios.php, grupos.php, cadastros.php, execucoes.php, usuarios.php, ajuda.php) só entregam o esqueleto, sem conferir nem o login; o JavaScript de cada uma (hoje.js, painel.js, configuracao.js, ajuda.js...) chama a API e monta a tela, sem fazer conta: resumos, porcentagens e situações (o resumo do plano, a porcentagem de cada estado no histórico, o peso efetivo dos critérios, a situação do cron, o manual em HTML) vêm prontos da API. Formulários com data-recurso gravam pela API e a página se remonta com a resposta.' => 'Las páginas (index.php, plano.php, desejos.php, estatisticas.php, hora.php, acessorios.php, galeria.php, passaporte.php, ficha.php, documentos.php, historico.php, configuracao.php, criterios.php, grupos.php, cadastros.php, execucoes.php, usuarios.php, ajuda.php) solo entregan el esqueleto, sin comprobar ni el inicio de sesión; el JavaScript de cada una (hoje.js, painel.js, configuracao.js, ajuda.js...) llama a la API y monta la pantalla, sin hacer cuentas: resúmenes, porcentajes y situaciones (el resumen del plan, el porcentaje de cada estado en el historial, el peso efectivo de los criterios, la situación del cron, el manual en HTML) vienen listos de la API. Formularios con data-recurso guardan por la API y la página se remonta con la respuesta.',
        'A API faz tudo, inclusive o que vem antes das telas: a instalação do banco vazio (recurso=instalacao, pelo token), o primeiro usuário (recurso=usuarios pelo token), a importação do sistema anterior (recurso=importacao) e o login das páginas (recurso=entrar: a página sem login recebe 401 da API, o api.js manda para api.php?recurso=entrar&volta=<a página>, o navegador pede o usuário e a senha e a API devolve para a página). Os scripts de linha de comando (instalar.php, criar_usuario.php, importar.php) só chamam as mesmas operações.' => 'La API lo hace todo, incluido lo que viene antes de las pantallas: la instalación de la base de datos vacía (recurso=instalacao, por el token), el primer usuario (recurso=usuarios por el token), la importación del sistema anterior (recurso=importacao) y el inicio de sesión de las páginas (recurso=entrar: la página sin inicio de sesión recibe 401 de la API, el api.js manda a api.php?recurso=entrar&volta=<la página>, el navegador pide el usuario y la contraseña y la API devuelve a la página). Los scripts de línea de comandos (instalar.php, criar_usuario.php, importar.php) solo llaman a las mismas operaciones.',
        'Fora da API, só o cron (cron.php), a cada minuto pela linha de comando, com as mesmas funções que a API usa; o que ele fez sai em recurso=cron.' => 'Fuera de la API, solo el cron (cron.php), cada minuto por la línea de comandos, con las mismas funciones que usa la API; lo que hizo sale en recurso=cron.',
        'Sem framework e sem dependências: PHP 8.1+ e JavaScript puro. A reescrita pode usar outra pilha, desde que mantenha o contrato da API, o modelo de dados e as regras.' => 'Sin framework y sin dependencias: PHP 8.1+ y JavaScript puro. La reescritura puede usar otra pila, siempre que mantenga el contrato de la API, el modelo de datos y las reglas.',
        'A ordem de construção' => 'El orden de construcción',
        '1. O banco: as tabelas do modelo_de_dados, com as chaves e as regras; a instalação (o schema inteiro num banco vazio) e as migrações (uma lista ordenada; cada uma com o SQL, um passo opcional em programa, e uma marca de aplicada: uma tabela, uma coluna ou uma linha da config; com alguma pendente, o sistema para e a Configuração mostra o botão de aplicar).' => '1. La base de datos: las tablas de modelo_de_dados, con las claves y las reglas; la instalación (el schema entero en una base de datos vacía) y las migraciones (una lista ordenada; cada una con el SQL, un paso opcional en programa, y una marca de aplicada: una tabla, una columna o una línea de config; con alguna pendiente, el sistema se para y la Configuración muestra el botón de aplicar).',
        '2. O cadastro inicial (a árvore Smartwatch / Tradicional › Mecânico › Automático e Corda manual / Tradicional › Quartzo › Pilha e Solar, os campos, os tipos de lançamento, as fórmulas, os avisos, os critérios e os modos) como dados.' => '2. El conjunto inicial (el árbol Smartwatch / Tradicional › Mecánico › Automático y Cuerda manual / Tradicional › Cuarzo › Pila y Solar, los campos, los tipos de registro, las fórmulas, los avisos, los criterios y los modos) como datos.',
        '3. A autenticação (token e HTTP Basic) e o esqueleto da API: os formatos, os erros (400, 401, 404, 409, 413, 500, 503) e os filtros genéricos de qualquer consulta (incluir, excluir, f[], busca, ordem, limite, pagina, mostrar).' => '3. La autenticación (token y HTTP Basic) y el esqueleto de la API: los formatos, los errores (400, 401, 404, 409, 413, 500, 503) y los filtros genéricos de cualquier consulta (incluir, excluir, f[], busca, ordem, limite, pagina, mostrar).',
        '4. A árvore, os campos (com a validação do valor pelo tipo), os relógios e as fotos.' => '4. El árbol, los campos (con la validación del valor por el tipo), los relojes y las fotos.',
        '5. Os tipos de lançamento e os lançamentos (instantâneo, com valor, sessão; sessão exclusiva fecha as outras exclusivas no mesmo instante; sem sobreposição de sessões do mesmo tipo), e a linha do tempo.' => '5. Los tipos de registro y los registros (instantáneo, con valor, sesión; la sesión exclusiva cierra las otras exclusivas en el mismo instante; sin solapamiento de sesiones del mismo tipo), y la línea de tiempo.',
        '6. O motor das fórmulas (abaixo), as variáveis de um relógio e o botão Testar.' => '6. El motor de las fórmulas (abajo), las variables de un reloj y el botón Probar.',
        '7. Os avisos, a visão de cada relógio (agora, carga, situação, próxima manutenção) e a página Hoje.' => '7. Los avisos, la visión de cada reloj (ahora, carga, situación, próximo mantenimiento) y la página Hoy.',
        '8. O gasto medido pelas leituras e a previsão da energia (autonomia).' => '8. El consumo medido por las lecturas y la previsión de la energía (autonomía).',
        '9. Os critérios e a nota; os modos de rodízio, o plano, a garantia de rodízio, trocar o dia, sortear de novo; a escala inteligente.' => '9. Los criterios y la nota; los modos de rotación, el plan, la garantía de rotación, cambiar el día, sortear de nuevo; la escala inteligente.',
        '10. O pulso sozinho e as sessões esquecidas; o cron.' => '10. La muñeca sola y las sesiones olvidadas; el cron.',
        '11. As mensagens (Telegram), a agenda (Google), os eventos personalizados e a tabela "O que vai para onde".' => '11. Los mensajes (Telegram), la agenda (Google), los eventos personalizados y la tabla "Qué va a dónde".',
        '12. Os documentos (pasta, cópia no banco em três níveis, galeria, vídeos, PDF, NF-e) e a manutenção deles no cron.' => '12. Los documentos (carpeta, copia en la base de datos en tres niveles, galería, vídeos, PDF, NF-e) y su mantenimiento en el cron.',
        '13. As telas, os usuários, as execuções do cron, a ajuda (o README dentro do sistema: os mesmos trechos que recurso=manual devolve) e a importação do sistema anterior.' => '13. Las pantallas, los usuarios, las ejecuciones del cron, la ayuda (el README dentro del sistema: los mismos fragmentos que devuelve recurso=manual) y la importación del sistema anterior.',
        '14. A aceitação: o roteiro de testes nos quatro bancos dá as mesmas respostas (seção testes).' => '14. La aceptación: el guion de pruebas en las cuatro bases de datos da las mismas respuestas (sección testes).',
        'A árvore, os campos e os relógios' => 'El árbol, los campos y los relojes',
        'A árvore de grupos tem quantos níveis o usuário quiser; um relógio fica num grupo só (ou na raiz). Tudo o que se cadastra num grupo (campos, tipos de lançamento, fórmulas, avisos, critérios, a origem de um bloco de modo) vale para ele e para tudo abaixo dele.' => 'El árbol de grupos tiene los niveles que el usuario quiera; un reloj queda en un solo grupo (o en la raíz). Todo lo que se define en un grupo (campos, tipos de registro, fórmulas, avisos, criterios, el origen de un bloque de modo) vale para él y para todo lo que está debajo.',
        'O mesmo nome pode se repetir em ramos diferentes, mas não entre irmãos. Mover um grupo para dentro dele mesmo (ou de um de dentro) é recusado. Excluir um grupo pela tela passa antes o que era dele para o grupo de cima (os de dentro, os relógios, os campos, os tipos, as fórmulas, os avisos e os blocos que sorteavam dele); versões de fórmula e de aviso que o grupo de cima já tem saem.' => 'El mismo nombre puede repetirse en ramas distintas, pero no entre hermanos. Mover un grupo para dentro de sí mismo (o de uno de dentro) se rechaza. Eliminar un grupo por la pantalla pasa antes lo que era de él al grupo de arriba (los de dentro, los relojes, los campos, los tipos, las fórmulas, los avisos y los bloques que sorteaban de él); las versiones de fórmula y de aviso que el grupo de arriba ya tiene salen.',
        'Campos: identificador (minúsculas, números e _, começando por letra, até 40; único entre campos e fórmulas, porque é o nome nas fórmulas; não muda se alguma fórmula usa), nome, tipo (listas.tipos_de_campo), unidade, valor padrão, o grupo, a ordem e a marca só nos desejados (so_desejado). Os campos de um relógio são os de todos e os de cada grupo da cadeia dele (os só nos desejados, só no desejado).' => 'Campos: identificador (minúsculas, números y _, empezando por letra, hasta 40; único entre campos y fórmulas, porque es el nombre en las fórmulas; no cambia si alguna fórmula lo usa), nombre, tipo (listas.tipos_de_campo), unidad, valor predeterminado, el grupo, el orden y la marca solo en los deseados (so_desejado). Los campos de un reloj son los de todos y los de cada grupo de su cadena (los solo en los deseados, solo en el deseado).',
        'O valor de um campo é conferido e normalizado pelo tipo: inteiro; decimal (aceita 1.079,99, 1079,99 e 1079.99, grava com ponto); sim/não (1, sim, s, true; 0, não, nao, n, false); data AAAA-MM-DD; lista (uma das opções); texto (até 1000). Vazio apaga. O valor usado nas contas é o informado, senão o padrão do campo.' => 'El valor de un campo se comprueba y se normaliza por el tipo: entero; decimal (acepta 1.079,99, 1079,99 y 1079.99, guarda con punto); sí/no (1, sim, s, true; 0, não, nao, n, false); fecha AAAA-MM-DD; lista (una de las opciones); texto (hasta 1000). Vacío borra. El valor usado en las cuentas es el informado, si no el predeterminado del campo.',
        'A situação na coleção de cada relógio (posse): colecao (o padrão), desejado (a lista de desejos), emprestado, vendido ou arquivado. Só o que está na coleção entra no rodízio: nas outras, o relógio fica indisponível (o banco garante, ck_relogio_posse_disponivel; a gravação força disponivel=0 e diz isso na mensagem), e por isso sai do sorteio, da escala e dos avisos sem regra a mais. Saindo da coleção, as sessões abertas dele fecham agora (com a nota "Fechei agora: ..."), os dias dele no plano de amanhã em diante saem e são sorteados de novo (com escala, gerar_escala de amanhã; sem, garantir_plano); hoje fica, mas a sessão do dia (o pulso sozinho) não abre para um relógio fora da coleção. Voltando para a coleção sem dizer o disponível, ele fica disponível. Da coleção (contam na tabela da página Hoje e no valor): na coleção e emprestado (o estado do emprestado parado é "Emprestado"); desejado, vendido e arquivado vão para fora_da_colecao (recurso=hoje) e para a página Desejos. Um campo com so_desejado=1 (o preço-alvo, a prioridade) vale só no desejado: campos_do_relogio o deixa de fora nos outros, e a gravação dos valores também. A lista de desejos (recurso=desejos) vem da prioridade mais alta para a mais baixa (a ordem das opções do campo prioridade_desejo; sem prioridade, no fim), depois pelo nome, com a soma dos preços-alvo; no painel do desejado, o quadro Desejo e os documentos tomam o lugar dos do dia a dia.' => 'La situación en la colección de cada reloj (posse): colecao (el predeterminado), desejado (la lista de deseos), emprestado, vendido o arquivado. Solo lo que está en la colección entra en la rotación: en las otras, el reloj queda no disponible (la base de datos lo garantiza, ck_relogio_posse_disponivel; el guardado fuerza disponivel=0 y lo dice en el mensaje), y por eso sale del sorteo, de la escala y de los avisos sin regla de más. Al salir de la colección, sus sesiones abiertas se cierran ahora (con la nota "Cerré ahora: ..."), sus días en el plan de mañana en adelante salen y se sortean de nuevo (con escala, gerar_escala de mañana; sin, garantir_plano); hoy se queda, pero la sesión del día (la muñeca sola) no se abre para un reloj fuera de la colección. Al volver a la colección sin decir el disponible, queda disponible. De la colección (cuentan en la tabla de la página Hoy y en el valor): en la colección y prestado (el estado del prestado parado es "Prestado"); deseado, vendido y archivado van a fora_da_colecao (recurso=hoje) y a la página Deseos. Un campo con so_desejado=1 (el precio objetivo, la prioridad) vale solo en el deseado: campos_do_relogio lo deja fuera en los demás, y el guardado de los valores también. La lista de deseos (recurso=desejos) viene de la prioridad más alta a la más baja (el orden de las opciones del campo prioridade_desejo; sin prioridad, al final), después por el nombre, con la suma de los precios objetivo; en el panel del deseado, el cuadro Deseo y los documentos ocupan el lugar de los del día a día.',
        'Acessórios (tabela acessorio): nome (até 120), tipo (pulseira, caixa, estojo, ferramenta, carregador, peca, outro), o relógio de que ele é (opcional: sem ele, solto; excluir o relógio deixa solto, ON DELETE SET NULL), observação (até 1000) e quando foi cadastrado. A lista vem pelo tipo e pelo nome; a ficha traz os do relógio.' => 'Accesorios (tabla acessorio): nombre (hasta 120), tipo (pulseira, caixa, estojo, ferramenta, carregador, peca, outro), el reloj del que es (opcional: sin él, suelto; eliminar el reloj lo deja suelto, ON DELETE SET NULL), observación (hasta 1000) y cuándo se registró. La lista viene por el tipo y por el nombre; la ficha trae los del reloj.',
        'Relógio: nome (até 120), grupo, situação na coleção, disponível (fora do rodízio e dos avisos quando não), a marca da cópia no banco dos documentos, a foto (JPEG, PNG ou WebP até 4 MB; o navegador reduz para 1200 px antes de enviar). Excluir apaga junto os valores, a foto, os documentos (e os arquivos), os lançamentos, o plano e os critérios próprios.' => 'Reloj: nombre (hasta 120), grupo, situación en la colección, disponible (fuera de la rotación y de los avisos cuando no), la marca de la copia en la base de datos de los documentos, la foto (JPEG, PNG o WebP hasta 4 MB; el navegador reduce a 1200 px antes de enviar). Eliminar borra junto los valores, la foto, los documentos (y los archivos), los registros, el plan y los criterios propios.',
        'Os tipos de lançamento, os lançamentos e a linha do tempo' => 'Los tipos de registro, los registros y la línea de tiempo',
        'Formatos (listas.formatos_de_lancamento): instantâneo (corda, troca de pilha), com valor (a leitura de carga, com unidade) e sessão, com início e fim (no pulso, no winder, no sol). Só a sessão tem "fecha às" (a hora em que a esquecida aberta fecha sozinha) e pode ser exclusiva (abrir uma exclusiva fecha as outras exclusivas abertas no mesmo instante: o relógio fica num lugar só). Só o com valor pode medir o gasto. A condição ("vale quando") é uma fórmula: o tipo só vale para os relógios em que ela dá verdadeiro.' => 'Formatos (listas.formatos_de_lancamento): instantáneo (cuerda, cambio de pila), con valor (la lectura de carga, con unidad) y sesión, con inicio y fin (en la muñeca, en el winder, al sol). Solo la sesión tiene "cierra a las" (la hora a la que la olvidada abierta se cierra sola) y puede ser exclusiva (abrir una exclusiva cierra las otras exclusivas abiertas en el mismo instante: el reloj queda en un solo lugar). Solo el con valor puede medir el consumo. La condición ("vale cuando") es una fórmula: el tipo solo vale para los relojes en los que da verdadero.',
        'Lançar: lancar (instantâneo ou com valor, num instante até agora), iniciar e encerrar (uma sessão; encerrar não antes do início), alternar (a sessão aberta se fecha, a fechada se abre: um botão só num atalho de celular), periodo (uma sessão inteira que já passou, sem sobrepor outra exclusiva), alterar e excluir (corrigir uma marcação). Em todas, relogio_id=hoje é o relógio do dia pelo plano. O formato de um tipo não muda depois de ter lançamentos; um tipo com lançamentos não é excluído.' => 'Registrar: lancar (instantáneo o con valor, en un instante hasta ahora), iniciar y encerrar (una sesión; encerrar no antes del inicio), alternar (la sesión abierta se cierra, la cerrada se abre: un solo botón en un atajo de móvil), periodo (una sesión entera que ya pasó, sin solapar otra exclusiva), alterar y excluir (corregir una marca). En todas, relogio_id=hoje es el reloj del día por el plan. El formato de un tipo no cambia después de tener registros; un tipo con registros no se elimina.',
        'A origem: manual (pela tela ou pela API), rodizio (a sessão no pulso do relógio do dia, aberta pelo sistema ou pelo Pôs no relógio do dia) e importado.' => 'El origen: manual (por la pantalla o por la API), rodizio (la sesión en la muñeca del reloj del día, abierta por el sistema o por Me lo puse en el reloj del día) e importado.',
        'A linha do tempo de um relógio divide o histórico em trechos contínuos: em uso pelo rodízio, no pulso fora do rodízio, em cada tipo de sessão (no winder, no sol...) e em repouso (o que sobra); e as marcações (corda, carga, pilha, revisão) como pontos, sem duração. O resumo dá o tempo e a porcentagem em cada estado.' => 'La línea de tiempo de un reloj divide el historial en tramos continuos: en uso por la rotación, en la muñeca fuera de la rotación, en cada tipo de sesión (en el winder, al sol...) y en reposo (lo que sobra); y las marcas (cuerda, carga, pila, revisión) como puntos, sin duración. El resumen da el tiempo y el porcentaje en cada estado.',
        'O estado de agora de um relógio: em uso (uma sessão no pulso aberta), numa sessão (outra sessão aberta: o estado é o nome do tipo, "No sol", "No winder", "No carregador"; duas juntas, "No sol · No winder") ou em repouso; na tabela da página Hoje, o indisponível em repouso aparece como indisponível. Com o desde quando: o começo da sessão no pulso, o da sessão mais recente, ou o fim da última no pulso ("Em repouso desde 21:40"). A sessão esquecida aberta conta só até o "fecha às" dela. O pulso é o único tipo que o código conhece pelo identificador; os outros entram pelo nome.' => 'El estado de ahora de un reloj: en uso (una sesión en la muñeca abierta), en una sesión (otra sesión abierta: el estado es el nombre del tipo, "Al sol", "En el winder", "En el cargador"; dos juntas, "Al sol · En el winder") o en reposo; en la tabla de la página Hoy, el no disponible en reposo aparece como no disponible. Con el desde cuándo: el comienzo de la sesión en la muñeca, el de la sesión más reciente, o el fin de la última en la muñeca ("En reposo desde 21:40"). La sesión olvidada abierta cuenta solo hasta su "cierra a las". La muñeca es el único tipo que el código conoce por el identificador; los demás entran por el nombre.',
        'O motor das fórmulas' => 'El motor de las fórmulas',
        'A sintaxe é a de uma planilha: números com vírgula ou ponto, textos entre aspas, ; separando os argumentos, + - * / ^ (a potência associa à direita), as comparações = <> < <= > >= (dão 1 ou 0), o sinal, os parênteses, as variáveis e as funções (listas.funcoes_das_formulas). A precedência, da mais fraca para a mais forte: comparação, soma, produto, potência, sinal.' => 'La sintaxis es la de una hoja de cálculo: números con coma o punto, textos entre comillas, ; separando los argumentos, + - * / ^ (la potencia asocia a la derecha), las comparaciones = <> < <= > >= (dan 1 o 0), el signo, los paréntesis, las variables y las funciones (listas.funcoes_das_formulas). La precedencia, de la más débil a la más fuerte: comparación, suma, producto, potencia, signo.',
        'Um valor vazio se propaga pela conta (vazio + 1 = vazio); a divisão por zero dá vazio. MIN e MAX ignoram os vazios. PADRAO(x; outro) troca o vazio. Um erro de escrita diz a posição ("falta fechar as aspas", "\\";\\" sobrando na posição 12").' => 'Un valor vacío se propaga por la cuenta (vacío + 1 = vacío); la división por cero da vacío. MIN y MAX ignoran los vacíos. PADRAO(x; otro) cambia el vacío. Un error de escritura dice la posición ("falta cerrar las comillas", "\\";\\" de más en la posición 12").',
        'As variáveis de um relógio: os campos (o valor usado), as fórmulas (pelo identificador; uma fórmula pode usar outra, sem ciclo) e as que o sistema dá. Cada fórmula pode ter uma versão por grupo; vale a do grupo mais perto do relógio (a dele, senão a de cima, ... senão a de todos). Uma fórmula que não tem versão para o relógio fica vazia nele.' => 'Las variables de un reloj: los campos (el valor usado), las fórmulas (por el identificador; una fórmula puede usar otra, sin ciclo) y las que da el sistema. Cada fórmula puede tener una versión por grupo; vale la del grupo más cercano al reloj (la de él, si no la de arriba, ... si no la de todos). Una fórmula que no tiene versión para el reloj queda vacía en él.',
        'As funções de histórico leem os lançamentos do relógio até o instante da conta (o primeiro argumento é o identificador do tipo, entre aspas). ACUMULA percorre o histórico como um saldo: começa no início, perde por hora, ganha por hora em cada sessão da lista, passa a valer o efeito num instantâneo da lista, sempre entre 0 e o máximo. É ela que faz a reserva de marcha e a carga de luz.' => 'Las funciones de historial leen los registros del reloj hasta el instante de la cuenta (el primer argumento es el identificador del tipo, entre comillas). ACUMULA recorre el historial como un saldo: empieza en el inicio, pierde por hora, gana por hora en cada sesión de la lista, pasa a valer el efecto en un instantáneo de la lista, siempre entre 0 y el máximo. Es ella la que hace la reserva de marcha y la carga de luz.',
        'Testar: a mesma fórmula calculada em todos os relógios (ou nos escolhidos), sem gravar, com o caminho da conta (rastro). Antes de gravar uma fórmula, o sistema a lê (erro de escrita) e confere as variáveis e os tipos que ela usa. Renomear ou excluir um campo, um tipo ou uma fórmula que outra fórmula usa é recusado, com a lista de quem usa.' => 'Probar: la misma fórmula calculada en todos los relojes (o en los elegidos), sin guardar, con el camino de la cuenta (rastro). Antes de guardar una fórmula, el sistema la lee (error de escritura) y comprueba las variables y los tipos que usa. Renombrar o eliminar un campo, un tipo o una fórmula que otra fórmula usa se rechaza, con la lista de quién la usa.',
        'O tempo nas contas é em dias: HOJE() é a meia-noite local de hoje, AGORA() o instante, e as datas dos campos viram dias pelo mesmo relógio. As horas viram dias dividindo por 24.' => 'El tiempo en las cuentas es en días: HOJE() es la medianoche local de hoy, AGORA() el instante, y las fechas de los campos se vuelven días por el mismo reloj. Las horas se vuelven días dividiendo por 24.',
        'Os avisos e a visão de cada relógio' => 'Los avisos y la visión de cada reloj',
        'Um aviso tem uma fórmula que dá a data prevista (expressao, em dias), uma condição (vale quando), a antecedência (0 a 3650 dias), o texto (até 300, com {relogio}, {data}, {quando} e {limite}), o tipo de lançamento que resolve (o botão na tela Hoje), se está ativo, uma versão por grupo (como as fórmulas), e como a escala simula a solução (escala: nao, uso ou sempre; o valor ou as horas simuladas) e se entra na agenda só dentro da janela de antecedência ou sempre.' => 'Un aviso tiene una fórmula que da la fecha prevista (expressao, en días), una condición (vale cuando), la antelación (0 a 3650 días), el texto (hasta 300, con {relogio}, {data}, {quando} y {limite}), el tipo de registro que lo resuelve (el botón en la pantalla Hoy), si está activo, una versión por grupo (como las fórmulas), y cómo simula la escala la solución (escala: nao, uso o sempre; el valor o las horas simuladas) y si entra en la agenda solo dentro de la ventana de antelación o siempre.',
        'Um relógio fora da coleção (desejado, vendido, arquivado) não tem aviso nenhum (o emprestado tem). O aviso vale para um relógio disponível quando a condição dá verdadeiro e a data prevista existe; sai hoje quando a data menos a antecedência já chegou. Estado: atrasado (a data passou) ou em breve. O aviso de um relógio com uma sessão aberta à mão (carregando, no sol) não vai para a agenda enquanto ela estiver aberta: a data andaria a cada conta.' => 'Un reloj fuera de la colección (deseado, vendido, archivado) no tiene ningún aviso (el prestado sí). El aviso vale para un reloj disponible cuando la condición da verdadero y la fecha prevista existe; sale hoy cuando la fecha menos la antelación ya llegó. Estado: atrasado (la fecha pasó) o en breve. El aviso de un reloj con una sesión abierta a mano (cargando, al sol) no va a la agenda mientras ella esté abierta: la fecha andaría en cada cuenta.',
        'Os avisos de carga usam o limite de carga: o do relógio (campo carga_minima), senão o geral da Configuração (carga_limiar); o solar usa sol_limiar. A data do Carregar é pelo gasto do estado de agora (no pulso, o de uso; guardado, o de guardado); no carregador, o Carregar some e vale o Tirar do carregador (carregado: vence quando a bateria enche no carregador).' => 'Los avisos de carga usan el límite de carga: el del reloj (campo carga_minima), si no el general de la Configuración (carga_limiar); el solar usa sol_limiar. La fecha del Cargar es por el consumo del estado de ahora (en la muñeca, el de uso; guardado, el de guardado); en el cargador, el Cargar desaparece y vale el Quitar del cargador (cargado: vence cuando la batería se llena en el cargador).',
        'Um aviso pode ser "na hora" (na_hora): além do alerta da manhã, o cron manda pelo Telegram no minuto em que ele vence, uma vez, e guarda quais já foram (config.na_hora_enviados, relogio_id:identificador); um aviso sai da lista quando deixa de vencer. O botão do aviso na página Hoje vem da API (resolve.acao e resolve.botao): a sessão que resolve, aberta, se encerra ("Tirou do carregador"); fechada, se inicia ("Pôs no sol"); a leitura se informa.' => 'Un aviso puede ser "a la hora" (na_hora): además de la alerta de la mañana, el cron lo manda por Telegram en el minuto en que vence, una vez, y guarda cuáles ya fueron (config.na_hora_enviados, relogio_id:identificador); un aviso sale de la lista cuando deja de vencer. El botón del aviso en la página Hoy viene de la API (resolve.acao y resolve.botao): la sesión que lo resuelve, abierta, se cierra ("Me lo quité del cargador"); cerrada, se inicia ("Me lo puse al sol"); la lectura se informa.',
        'O aviso Encostado (encostado, de todos os relógios, resolve com o pulso) é só cadastro: a data prevista é PADRAO(ULTIMA_DATA("pulso"); data_compra) + CONFIG("encostado_dias") (a Configuração, padrão 30), antecedência 0; sem nunca ter ido ao pulso nem data da compra, não avisa. Não entra na próxima manutenção nem no "O que fazer": a tabela da coleção tem a coluna Encostado, o cartão do dia mostra a falta quando já venceu, e o quadro Agora do painel também.' => 'El aviso Arrinconado (encostado, de todos los relojes, se resuelve con la muñeca) es solo ficha: la fecha prevista es PADRAO(ULTIMA_DATA("pulso"); data_compra) + CONFIG("encostado_dias") (la Configuración, por defecto 30), antelación 0; sin haber ido nunca a la muñeca ni fecha de la compra, no avisa. No entra en el próximo mantenimiento ni en el "Qué hacer": la tabla de la colección tiene la columna Arrinconado, la tarjeta del día muestra la falta cuando ya venció, y el cuadro Ahora del panel también.',
        'A visão de cada relógio (a tabela da página Hoje e o painel): em uso ou em repouso desde quando, a carga estimada agora e de onde vem (a fórmula energia e a origem), a situação (frases curtas: autonomia restante, reserva...), a próxima manutenção (o aviso mais perto, sem o Encostado), o que fazer e a coluna Encostado.' => 'La visión de cada reloj (la tabla de la página Hoy y el panel): en uso o en reposo desde cuándo, la carga estimada ahora y de dónde viene (la fórmula energia y el origen), la situación (frases cortas: autonomía restante, reserva...), el próximo mantenimiento (el aviso más cercano, sin el Arrinconado), qué hacer y la columna Arrinconado.',
        'O gasto medido pelas leituras e a autonomia' => 'El consumo medido por las lecturas y la autonomía',
        'Cada leitura de carga de um tipo que mede o gasto é comparada com a anterior do mesmo relógio: o intervalo vira uma medição, com a queda, as horas no pulso e as horas fora do pulso no intervalo (o horário de uso conta como pulso sozinho quando o pulso sozinho está ligado; as marcações Pôs e Tirou mandam). Uma subida é recarga: novo ponto de partida, sem medir. Só entram intervalos de 1 hora ou mais; o curto entra com peso pequeno. Um intervalo com outra sessão no meio (o carregador) não mede: a medição só separa pulso e guardado.' => 'Cada lectura de carga de un tipo que mide el consumo se compara con la anterior del mismo reloj: el intervalo se vuelve una medición, con la caída, las horas en la muñeca y las horas fuera de la muñeca en el intervalo (el horario de uso cuenta como muñeca sola cuando la muñeca sola está activada; las marcas Me lo puse y Me lo quité mandan). Una subida es recarga: nuevo punto de partida, sin medir. Solo entran intervalos de 1 hora o más; el corto entra con peso pequeño. Un intervalo con otra sesión en medio (el cargador) no mide: la medición solo separa muñeca y guardado.',
        'Cada medição é uma conta com dois desconhecidos: queda = dias de uso × gasto em uso + dias fora × gasto fora. Com as medições da janela (medicao_janela_dias, padrão 90), os dois gastos saem juntos por mínimos quadrados, cada medição pesando as horas que cobriu. Quando elas não separam os dois (só leituras guardado, por exemplo), vale a média das medições de cada um; sem nenhuma na janela, as de antes; sem nenhuma, o do cadastro. O resultado também é dado na janela anterior, para comparar (a bateria envelhecendo).' => 'Cada medición es una cuenta con dos incógnitas: caída = días de uso × consumo en uso + días fuera × consumo fuera. Con las mediciones de la ventana (medicao_janela_dias, por defecto 90), los dos consumos salen juntos por mínimos cuadrados, cada medición pesando las horas que cubrió. Cuando ellas no separan los dos (solo lecturas guardado, por ejemplo), vale la media de las mediciones de cada uno; sin ninguna en la ventana, las de antes; sin ninguna, el de la ficha. El resultado también se da en la ventana anterior, para comparar (la batería envejeciendo).',
        'MEDIDO("uso") e MEDIDO("repouso") dão esses gastos às fórmulas; corrigir uma marcação de pulso recalcula as horas das medições que cobrem aquele trecho.' => 'MEDIDO("uso") y MEDIDO("repouso") dan esos consumos a las fórmulas; corregir una marca de muñeca recalcula las horas de las mediciones que cubren aquel tramo.',
        'A autonomia: cheio pelo cadastro e pela conta (com o gasto medido), quando acaba seguindo o plano (simulando os dias do plano), quanto dura no pulso sem tirar e guardado; e a previsão do smartwatch (a carga dia a dia, até o limite).' => 'La autonomía: lleno por la ficha y por la cuenta (con el consumo medido), cuándo se acaba siguiendo el plan (simulando los días del plan), cuánto dura en la muñeca sin quitar y guardado; y la previsión del smartwatch (la carga día a día, hasta el límite).',
        'Os critérios e a nota' => 'Los criterios y la nota',
        'Um conjunto de critérios por lugar: todos os relógios, um grupo ou um relógio. O relógio usa o conjunto mais perto dele, inteiro (o dele, senão o do grupo, senão o de cima, ..., senão o de todos).' => 'Un conjunto de criterios por lugar: todos los relojes, un grupo o un reloj. El reloj usa el conjunto más cercano a él, entero (el de él, si no el del grupo, si no el de arriba, ..., si no el de todos).',
        'O conjunto tem parâmetros com peso (somam 100%); cada parâmetro tem subparâmetros com peso (somam 100% dentro dele); cada subparâmetro lê uma variável (um campo ou uma fórmula) e transforma o valor em nota (0 a 100) pelas faixas: de um número até outro (a primeira começa em 0, sem buracos nem sobreposição, só a última sem limite) ou por categoria (campo de lista ou texto).' => 'El conjunto tiene parámetros con peso (suman 100%); cada parámetro tiene subparámetros con peso (suman 100% dentro de él); cada subparámetro lee una variable (un campo o una fórmula) y transforma el valor en nota (0 a 100) por los rangos: de un número hasta otro (el primero empieza en 0, sin huecos ni solapamiento, solo el último sin límite) o por categoría (campo de lista o texto).',
        'A nota do parâmetro é a média das notas dos subparâmetros, pelo peso; a nota do relógio, a média dos parâmetros, pelo peso. Um subparâmetro sem valor (campo vazio, valor fora de toda faixa) sai da conta e os outros dividem o peso dele. A conta inteira de cada nota é mostrada (cada faixa, cada peso, cada ponto).' => 'La nota del parámetro es la media de las notas de los subparámetros, por el peso; la nota del reloj, la media de los parámetros, por el peso. Un subparámetro sin valor (campo vacío, valor fuera de todo rango) sale de la cuenta y los otros se reparten su peso. La cuenta entera de cada nota se muestra (cada rango, cada peso, cada punto).',
        'Restaurar os critérios iniciais apaga os de todos os lugares e volta aos do cadastro inicial.' => 'Restaurar los criterios iniciales borra los de todos los lugares y vuelve a los del conjunto inicial.',
        'Os modos de rodízio, o plano e a escala inteligente' => 'Los modos de rotación, el plan y la escala inteligente',
        'Hoje sem relógio (rodizio sem_relogio): o plano de hoje sai e hoje vira um dia livre; a sessão do rodízio de hoje que já começou fecha agora (o tempo dela conta como uso), a que ainda não começou sai; a sessão do dia (o pulso sozinho) não abre num dia sem plano, e o garantir_plano não põe de volta como plano de hoje o relógio que esteve no pulso pelo rodízio num dia livre. Os outros dias não mudam. Desfaz: trocar_dia (ou usando) de hoje, ou resortear_hoje.' => 'Hoy sin reloj (rodizio sem_relogio): el plan de hoy sale y hoy se vuelve un día libre; la sesión de la rotación de hoy que ya empezó se cierra ahora (su tiempo cuenta como uso), la que aún no empezó sale; la sesión del día (la muñeca sola) no se abre en un día sin plan, y el garantir_plano no vuelve a poner como plan de hoy el reloj que estuvo en la muñeca por la rotación en un día libre. Los demás días no cambian. Deshacer: trocar_dia (o usando) de hoy, o resortear_hoje.',
        'Um modo é feito de blocos de dias da semana (cada dia em um bloco só). Cada bloco diz de onde escolher (um grupo, a coleção toda ou um relógio fixo) e se é um relógio por dia ou um para o bloco inteiro. A forma de escolha do modo: inteligente (a maior nota), ponderado (sorteio com a nota como chance), aleatório ou fifo (quem espera há mais tempo). Com o ciclo ligado, um relógio só volta depois que todos os disponíveis do bloco passaram. No máximo um modo em uso.' => 'Un modo está hecho de bloques de días de la semana (cada día en un solo bloque). Cada bloque dice de dónde elegir (un grupo, la colección entera o un reloj fijo) y si es un reloj por día o uno para el bloque entero. La forma de elección del modo: inteligente (la mayor nota), ponderado (sorteo con la nota como probabilidad), aleatorio o fifo (quien espera hace más tiempo). Con el ciclo activado, un reloj solo vuelve después de que pasaron todos los disponibles del bloque. Como máximo un modo en uso.',
        'A garantia de rodízio (max_sem_uso, padrão 21) vale antes da nota: candidato além desse limite de dias sem uso ganha direto, o mais parado primeiro. Os dias sem uso de um relógio nunca usado contam desde a compra (sem data de compra: 9999).' => 'La garantía de rotación (max_sem_uso, por defecto 21) vale antes de la nota: el candidato más allá de ese límite de días sin uso gana directo, el más parado primero. Los días sin uso de un reloj nunca usado cuentan desde la compra (sin fecha de compra: 9999).',
        'O plano guarda o relógio de cada dia, o bloco, a origem (sorteio ou manual), a ação do dia e o motivo, numa frase ("Garantia de rodízio: ...", "Sorteio pela nota, entre 5 candidatos: nota 70,2, 16,4% de chance", "Escolhido à mão"). O cron monta o dia que falta (à 0h da segunda, a semana nova); trocar o relógio de um dia o marca como manual; sortear de novo refaz o período; usando hoje põe outro relógio no período atual e refaz o plano.' => 'El plan guarda el reloj de cada día, el bloque, el origen (sorteio o manual), la acción del día y el motivo, en una frase ("Garantía de rotación: ...", "Sorteo por la nota, entre 5 candidatos: nota 70,2, 16,4% de probabilidad", "Elegido a mano"). El cron arma el día que falta (a las 0h del lunes, la semana nueva); cambiar el reloj de un día lo marca como manual; sortear de nuevo rehace el período; llevándolo hoy pone otro reloj en el período actual y rehace el plan.',
        'Um período escolhido à mão (rodizio, acao=periodo): de, até (de hoje até 2 anos), os relógios na ordem e quantos dias seguidos cada (dias_cada): cada dia do período fica manual, com o relógio da vez (depois do último, volta ao primeiro; hoje, ele passa a ser o do pulso a partir de agora); na escala, ela é refeita a partir do começo do período. De amanhã em diante: periodo_sortear apaga o que o período tem (à mão, sorteado ou livre) e sorteia de novo; periodo_livre apaga e deixa os dias livres (a tabela plano_livre: sem relógio e sem sorteio; o sorteio e a escala pulam esses dias, e a escala não estica um bloco sobre eles). Escolher um relógio para um dia livre (trocar_dia, periodo, usando) o tira de plano_livre; trocar_dia 0 também (volta ao sorteio). Os dias manuais e os livres de amanhã em diante ficam quando se sorteia de novo ou se monta a próxima semana (hoje, o sortear de novo sorteia); trocar de modo refaz os sorteados. A API dá os dias livres em plano.livres e hoje.livres (as telas os põem entre os dias do plano, como "livre: escolha à mão").' => 'Un período elegido a mano (rodizio, acao=periodo): de, hasta (de hoy hasta 2 años), los relojes en orden y cuántos días seguidos cada uno (dias_cada): cada día del período queda manual, con el reloj del turno (después del último, vuelve al primero; hoy, pasa a ser el de la muñeca a partir de ahora); en la escala, ella se rehace a partir del comienzo del período. De mañana en adelante: periodo_sortear borra lo que tiene el período (a mano, sorteado o libre) y sortea de nuevo; periodo_livre borra y deja los días libres (la tabla plano_livre: sin reloj y sin sorteo; el sorteo y la escala saltan esos días, y la escala no estira un bloque sobre ellos). Elegir un reloj para un día libre (trocar_dia, periodo, usando) lo saca de plano_livre; trocar_dia 0 también (vuelve al sorteo). Los días manuales y los libres de mañana en adelante se quedan cuando se sortea de nuevo o se arma la próxima semana (hoy, el sortear de nuevo sortea); cambiar de modo rehace los sorteados. La API da los días libres en plano.livres y hoje.livres (las pantallas los ponen entre los días del plan, como "libre: elija a mano").',
        'O Rodízio manual (a última opção da lista Modo de rodízio da página Hoje; não é um modo: fora do período vale o modo ativo): de e até (de hoje até 2 anos); recurso=rodizio_manual dá os dias de 7 em 7 (pagina), cada um com o que o plano tem e a escolha de partida do seletor: o relógio escolhido à mão, livre (dia livre) ou auto (Decida por mim: o dia sorteado ou sem relógio). rodizio acao=manual grava o período inteiro: dias[data] = o id, auto ou livre (hoje não); o dia que não vem fica com a escolha de partida. Os dias com relógio ficam manual ("Escolhido à mão no rodízio manual de DD/MM a DD/MM."); os livres vão para plano_livre; hoje com outro relógio passa a ser o do pulso a partir de agora (hoje em auto continua o que está); na escala, ela é refeita a partir do começo. O Decida por mim decide ao gravar e grava manual, com o motivo ("Decida por mim: a maior nota (62,9), entre 4 candidatos. O de ontem (X) ficou de fora." ou "Decida por mim, pela garantia de rodízio: parado há 33 dias, além do limite de 15 dias sem uso, ..."): de hoje até o fim do período, dia a dia, cada dia vira uma sessão simulada no pulso (os do plano antes do período, os escolhidos e os decididos), e no dia auto: os disponíveis, menos o de ontem e o escolhido para amanhã (se sobrar outro); a garantia de rodízio na frente (o mais tempo parado além de max_sem_uso); senão a maior nota no começo do uso do dia; empate: o menor id. A resposta diz quantos dias foram escolhidos, decididos, livres e quantos ficaram como já estavam.' => 'La Rotación manual (la última opción de la lista Modo de rotación de la página Hoy; no es un modo: fuera del período vale el modo activo): de y hasta (de hoy hasta 2 años); recurso=rodizio_manual da los días de 7 en 7 (pagina), cada uno con lo que tiene el plan y la elección de partida del selector: el reloj elegido a mano, livre (día libre) o auto (Decide por mí: el día sorteado o sin reloj). rodizio acao=manual guarda el período entero: dias[data] = el id, auto o livre (hoy no); el día que no viene se queda con la elección de partida. Los días con reloj quedan manual ("Elegido a mano en la rotación manual de DD/MM a DD/MM."); los libres van a plano_livre; hoy con otro reloj pasa a ser el de la muñeca a partir de ahora (hoy en auto continúa lo que está); en la escala, ella se rehace a partir del comienzo. El Decide por mí decide al guardar y guarda manual, con el motivo ("Decide por mí: la mayor nota (62,9), entre 4 candidatos. El de ayer (X) quedó fuera." o "Decide por mí, por la garantía de rotación: parado desde hace 33 días, más allá del límite de 15 días sin uso, ..."): de hoy hasta el fin del período, día a día, cada día se vuelve una sesión simulada en la muñeca (los del plan antes del período, los elegidos y los decididos), y en el día auto: los disponibles, menos el de ayer y el elegido para mañana (si sobra otro); la garantía de rotación por delante (el más tiempo parado más allá de max_sem_uso); si no la mayor nota al comienzo del uso del día; empate: el menor id. La respuesta dice cuántos días se eligieron, se decidieron, libres y cuántos se quedaron como ya estaban.',
        'Apagar a programação (página Plano e quadro Modo de rodízio): apagar um período (periodo_sortear: sai tudo o que ele tem, de amanhã em diante, e o modo sorteia de novo; periodo_livre: sai tudo e os dias ficam livres) e apagar tudo (rodizio apagar_tudo: sai toda a programação de amanhã em diante, à mão, sorteada e livre; com hoje=1, "Excluindo hoje", de hoje em diante; depois o modo ativo monta o plano de novo, gerar_escala na escala e garantir_plano até domingo no sorteio; hoje, se mudar, o novo vai para o pulso a partir de agora, como no resortear_hoje).' => 'Borrar la programación (página Plan y cuadro Modo de rotación): borrar un período (periodo_sortear: sale todo lo que tiene, de mañana en adelante, y el modo sortea de nuevo; periodo_livre: sale todo y los días quedan libres) y borrar todo (rodizio apagar_tudo: sale toda la programación de mañana en adelante, a mano, sorteada y libre; con hoje=1, "Incluyendo hoy", de hoy en adelante; después el modo activo arma el plan de nuevo, gerar_escala en la escala y garantir_plano hasta el domingo en el sorteo; hoy, si cambia, el nuevo va a la muñeca a partir de ahora, como en el resortear_hoje).',
        'As listas longas de dias vêm da API uma página por vez (plano_pagina): os Próximos dias (hoje.proximos e recurso=proximos, de hoje até o fim do plano) e o dia a dia da página Plano (plano.dia_a_dia, com o filtro relogio), com os dias livres no meio (origem livre; sem eles no filtro de relógio), cada dia com o dia da semana (dia_semana 1 a 7, dia_semana_curto); o tamanho da página é o Mostrar até da Configuração (config proximos_por_pagina, padrão 7; plano_por_pagina, padrão 31; 1 a 366; por_pagina no pedido vale por cima), e o recurso=config devolve os dois já com o padrão (mostrar_ate).' => 'Las listas largas de días vienen de la API una página cada vez (plano_pagina): los Próximos días (hoje.proximos y recurso=proximos, de hoy hasta el fin del plan) y el día a día de la página Plan (plano.dia_a_dia, con el filtro relogio), con los días libres en medio (origen livre; sin ellos en el filtro de reloj), cada día con el día de la semana (dia_semana 1 a 7, dia_semana_curto); el tamaño de la página es el Mostrar hasta de la Configuración (config proximos_por_pagina, por defecto 7; plano_por_pagina, por defecto 31; 1 a 366; por_pagina en la petición vale por encima), y recurso=config devuelve los dos ya con el predeterminado (mostrar_ate).',
        'A escala inteligente (um modo com escala_dias de 7 a 730) planeja tudo de uma vez simulando dia a dia: a nota de cada relógio com o estado simulado daquele dia; a escolha (o smartwatch fica os dias que a bateria aguenta, até 7); a sessão no pulso no horário de uso e o efeito dela em todos; os avisos (se o escolhido vai precisar de carga ou corda, anota a ação no dia e simula o lançamento que resolve). Toda manhã o cron refaz a escala a partir do estado real. Notas iguais na maior (o empate exato) se desempatam por sorteio, e o motivo diz "Empatado na nota com N outros: saiu no sorteio (<fonte>)."' => 'La escala inteligente (un modo con escala_dias de 7 a 730) planifica todo de una vez simulando día a día: la nota de cada reloj con el estado simulado de aquel día; la elección (el smartwatch se queda los días que aguanta la batería, hasta 7); la sesión en la muñeca en el horario de uso y su efecto en todos; los avisos (si el elegido va a necesitar carga o cuerda, anota la acción en el día y simula el registro que lo resuelve). Cada mañana el cron rehace la escala a partir del estado real. Notas iguales en la mayor (el empate exacto) se desempatan por sorteo, y el motivo dice "Empatado en la nota con N otros: salió en el sorteo (<fuente>)."',
        'O sorteio (sorteio(min, max): o modo aleatório, o sorteio pela nota e o desempate da escala) usa números aleatórios de fora, nesta ordem: RANDOM.ORG (www.random.org/integers/?num=64&min=0&max=65535&col=1&base=10&format=plain&rnd=new: ruído atmosférico); senão o ANU QRNG (qrng.anu.edu.au/API/jsonI.php?length=64&type=uint16, o endereço antigo, sem chave: {"success": true, "data": [...]}; quântico); senão o gerador seguro do PHP (random_int). Um lote de 64 números de 16 bits por pedido, na memória do pedido; cada sorteio junta quantos pedaços de 16 bits precisar e descarta o valor que passa do último múltiplo inteiro da faixa (sem viés). Cada serviço tem 4 segundos; a resposta tem de vir completa e dentro da faixa, senão vale como falha. Se os dois falham, a config aleatorio_fora guarda quando, e por 10 minutos o sistema nem tenta (usa o do PHP); a config aleatorio_ultima guarda a fonte do último lote e quando (recurso=config: aleatorio.ultimo_lote, aleatorio.fora_desde; a Configuração mostra no quadro Sorteios). O motivo de cada dia sorteado termina com a fonte entre parênteses ("... todos com a mesma chance (RANDOM.ORG)."). Com RELOGIOS_SEMENTE (os testes), mt_rand com a semente, sem rede (a fonte: "semente de teste"). O que é segredo (o sal das senhas, os nomes dos arquivos dos documentos) fica no gerador do PHP: número que viaja pela internet não serve para segredo.' => 'El sorteo (sorteio(min, max): el modo aleatorio, el sorteo por la nota y el desempate de la escala) usa números aleatorios de fuera, en este orden: RANDOM.ORG (www.random.org/integers/?num=64&min=0&max=65535&col=1&base=10&format=plain&rnd=new: ruido atmosférico); si no el ANU QRNG (qrng.anu.edu.au/API/jsonI.php?length=64&type=uint16, la dirección antigua, sin clave: {"success": true, "data": [...]}; cuántico); si no el generador seguro de PHP (random_int). Un lote de 64 números de 16 bits por petición, en la memoria de la petición; cada sorteo junta los trozos de 16 bits que necesite y descarta el valor que pasa del último múltiplo entero del rango (sin sesgo). Cada servicio tiene 4 segundos; la respuesta tiene que venir completa y dentro del rango, si no vale como fallo. Si los dos fallan, la config aleatorio_fora guarda cuándo, y durante 10 minutos el sistema ni lo intenta (usa el de PHP); la config aleatorio_ultima guarda la fuente del último lote y cuándo (recurso=config: aleatorio.ultimo_lote, aleatorio.fora_desde; la Configuración lo muestra en el cuadro Sorteos). El motivo de cada día sorteado termina con la fuente entre paréntesis ("... todos con la misma probabilidad (RANDOM.ORG)."). Con RELOGIOS_SEMENTE (las pruebas), mt_rand con la semilla, sin red (la fuente: "semilla de prueba"). Lo que es secreto (la sal de las contraseñas, los nombres de los archivos de los documentos) se queda en el generador de PHP: un número que viaja por internet no sirve para secreto.',
        'O pulso sozinho e as sessões esquecidas' => 'La muñeca sola y las sesiones olvidadas',
        'O horário de uso (uso_inicio e uso_fim) diz quando o relógio do dia está no pulso. Pôr sozinho (pulso_auto_inicio): no início do horário, o cron abre a sessão no pulso do relógio do dia (origem rodizio). Tirar sozinho (pulso_auto_fim): o "fecha às" do tipo No pulso segue o fim do horário. Desligados, só as marcações Pôs e Tirou contam; o que foi marcado sempre vale. Com o relógio do dia noutra sessão exclusiva aberta (no carregador, no sol, no winder), o pôr sozinho espera; se ele saiu de uma depois do início do horário, a sessão no pulso começa quando ele saiu.' => 'El horario de uso (uso_inicio y uso_fim) dice cuándo el reloj del día está en la muñeca. Poner solo (pulso_auto_inicio): al inicio del horario, el cron abre la sesión en la muñeca del reloj del día (origen rodizio). Quitar solo (pulso_auto_fim): el "cierra a las" del tipo En la muñeca sigue el fin del horario. Desactivados, solo cuentan las marcas Me lo puse y Me lo quité; lo que se marcó siempre vale. Con el reloj del día en otra sesión exclusiva abierta (en el cargador, al sol, en el winder), el poner solo espera; si salió de una después del inicio del horario, la sesión en la muñeca empieza cuando salió.',
        'Toda sessão esquecida aberta fecha sozinha no "fecha às" do tipo dela (a do sol, em sol_fim).' => 'Toda sesión olvidada abierta se cierra sola en el "cierra a las" de su tipo (la del sol, en sol_fim).',
        'O cron' => 'El cron',
        'A cada minuto: confere o token, o fuso e as migrações (pendente: registra e para); apaga execuções antigas (sem atividade, 7 dias; com atividade ou erro, 1 ano); monta o dia do plano que falta; fecha as sessões esquecidas; abre a sessão no pulso do dia; dispara os eventos personalizados no minuto marcado (depois de uma parada de até 7 dias, sai uma vez só, sem repetir); a manutenção dos documentos.' => 'Cada minuto: comprueba el token, el huso y las migraciones (pendiente: registra y se para); borra ejecuciones antiguas (sin actividad, 7 días; con actividad o error, 1 año); arma el día del plan que falta; cierra las sesiones olvidadas; abre la sesión en la muñeca del día; dispara los eventos personalizados en el minuto marcado (después de una parada de hasta 7 días, sale una sola vez, sin repetir); el mantenimiento de los documentos.',
        'Na hora da manhã (horario_manha), uma vez por dia: refaz a escala a partir do estado real, manda o Telegram do dia (o relógio de hoje e os avisos) e sincroniza a agenda. Na hora da noite (horario_noite): o Telegram da véspera (o relógio de amanhã e o que preparar) e a sincronização; conta os documentos perdidos; e, com a BACKUP_PASTA no config.php, faz a cópia de segurança do banco.' => 'A la hora de la mañana (horario_manha), una vez por día: rehace la escala a partir del estado real, manda el Telegram del día (el reloj de hoy y los avisos) y sincroniza la agenda. A la hora de la noche (horario_noite): el Telegram de la víspera (el reloj de mañana y qué preparar) y la sincronización; cuenta los documentos perdidos; y, con la BACKUP_PASTA en el config.php, hace la copia de seguridad de la base de datos.',
        'Os avisos na hora, a cada minuto: os vencidos agora (de todos os relógios) que ainda não foram vão pelo Telegram.' => 'Los avisos a la hora, cada minuto: los vencidos ahora (de todos los relojes) que aún no fueron van por Telegram.',
        'A cópia de segurança: um arquivo relojoeiro-AAAA-MM-DD-HHMMSS.jsonl.gz na BACKUP_PASTA (fora da pasta publicada: dentro dela, recusada), JSON Lines comprimido, o mesmo nos quatro bancos: a primeira linha é o cabeçalho (relojoeiro_copia 1, criada, banco, versao: a última migração, documentos, tabelas); depois, para cada tabela, uma linha {tabela, colunas, binarias} e uma linha por registro com a lista dos valores (binários em base64). As tabelas vêm na ordem em que voltam (a citada antes da que cita; a que cita a si mesma, a árvore, volta em rodadas). Ficam as BACKUP_MANTER mais novas (padrão 7). O conteúdo dos documentos (documento_parte) só com BACKUP_DOCUMENTOS = true. Restaurar: só da mesma versão; antes, uma cópia do que está agora; depois, numa transação, apaga tudo (na ordem inversa) e grava a cópia; sem o conteúdo dos documentos, documento.no_banco volta a 0.' => 'La copia de seguridad: un archivo relojoeiro-AAAA-MM-DD-HHMMSS.jsonl.gz en la BACKUP_PASTA (fuera de la carpeta publicada: dentro de ella, rechazada), JSON Lines comprimido, el mismo en las cuatro bases de datos: la primera línea es la cabecera (relojoeiro_copia 1, criada, banco, versao: la última migración, documentos, tabelas); después, para cada tabla, una línea {tabela, colunas, binarias} y una línea por registro con la lista de los valores (binarios en base64). Las tablas vienen en el orden en que vuelven (la citada antes de la que cita; la que se cita a sí misma, el árbol, vuelve en rondas). Quedan las BACKUP_MANTER más nuevas (por defecto 7). El contenido de los documentos (documento_parte) solo con BACKUP_DOCUMENTOS = true. Restaurar: solo de la misma versión; antes, una copia de lo que hay ahora; después, en una transacción, borra todo (en el orden inverso) y guarda la copia; sin el contenido de los documentos, documento.no_banco vuelve a 0.',
        'Com BACKUP_ATIVO = false no config.php, o cron não faz a cópia de segurança e a escrita fazer é recusada.' => 'Con BACKUP_ATIVO = false en el config.php, el cron no hace la copia de seguridad y la escritura fazer se rechaza.',
        'Mudo: avisos do PHP e erros entram no registro, nunca na saída. Grava em cron_execucao o que fez (só quando fez algo, ou deu erro), o último erro em config.cron_erro (sai na primeira execução sem erro) e a última rodada com atividade em config.cron_registro. Erro fatal sem banco vai para um arquivo na pasta temporária. Opções: --forcar (manhã e noite agora) e -v (mostra o registro).' => 'Mudo: avisos de PHP y errores entran en el registro, nunca en la salida. Guarda en cron_execucao lo que hizo (solo cuando hizo algo, o dio error), el último error en config.cron_erro (sale en la primera ejecución sin error) y la última ronda con actividad en config.cron_registro. Error fatal sin base de datos va a un archivo en la carpeta temporal. Opciones: --forcar (por la mañana y por la noche ahora) y -v (muestra el registro).',
        'As mensagens, a agenda e os eventos personalizados' => 'Los mensajes, la agenda y los eventos personalizados',
        'Dois canais (listas.canais): Telegram (tg) e Google Agenda (ag). Cada tipo de aviso (dia, vespera, o identificador de cada aviso e ev<id> de cada evento personalizado) é marcado ou não para cada canal, e pode ter mensagem própria no canal; sem ela, vale a mensagem padrão do canal (tg_padrao, ag_padrao). As mensagens têm âncoras entre chaves (listas.ancoras), trocadas pelos valores na hora.' => 'Dos canales (listas.canais): Telegram (tg) y Google Calendar (ag). Cada tipo de aviso (dia, vespera, el identificador de cada aviso y ev<id> de cada evento personalizado) está marcado o no para cada canal, y puede tener mensaje propio en el canal; sin él, vale el mensaje por defecto del canal (tg_padrao, ag_padrao). Los mensajes tienen marcadores entre llaves (listas.ancoras), cambiados por los valores en el momento.',
        'O Telegram vai por uma API de mensagem (MSG_ENDPOINT): GET com destinatario, titulo e mensagem; partes de até 3000 caracteres (as mensagens do mesmo horário vão juntas, separadas por uma linha em branco).' => 'El Telegram va por una API de mensaje (MSG_ENDPOINT): GET con destinatario, titulo y mensagem; partes de hasta 3000 caracteres (los mensajes de la misma hora van juntos, separados por una línea en blanco).',
        'A agenda: uma conta de serviço do Google (a chave JSON no servidor; token por JWT RS256, escopo do Calendar). O sistema calcula o que tem de estar na agenda (de hoje até agenda_antecedencia dias: os avisos marcados para a agenda, no horário da manhã do dia previsto; o relógio do dia e a véspera, pelo plano; as ocorrências dos eventos), cada item com uma chave estável; cria o que falta, atualiza o que mudou (pela assinatura), apaga o que deixou de valer; o que já passou fica. Na agenda, a primeira linha do modelo é o título e o resto a descrição.' => 'La agenda: una cuenta de servicio de Google (la clave JSON en el servidor; token por JWT RS256, alcance del Calendar). El sistema calcula lo que tiene que estar en la agenda (de hoy hasta agenda_antecedencia días: los avisos marcados para la agenda, a la hora de la mañana del día previsto; el reloj del día y la víspera, por el plan; las ocurrencias de los eventos), cada elemento con una clave estable; crea lo que falta, actualiza lo que cambió (por la firma), borra lo que dejó de valer; lo que ya pasó se queda. En la agenda, la primera línea del modelo es el título y el resto la descripción.',
        'Evento personalizado: nome, ativo, repetição (listas.repeticoes), data (uma vez; a cada N dias: a partir dela), hora, dias da semana, dia do mês (1 a 31; mês sem o dia, o último), intervalo (1 a 3650), relógio opcional (com ele, as âncoras do relógio funcionam). Só o que a repetição usa fica gravado. Novo, já vai pelo Telegram.' => 'Evento personalizado: nombre, activo, repetición (listas.repeticoes), fecha (una vez; cada N días: a partir de ella), hora, días de la semana, día del mes (1 a 31; mes sin el día, el último), intervalo (1 a 3650), reloj opcional (con él, los marcadores del reloj funcionan). Solo lo que usa la repetición queda guardado. Nuevo, ya va por Telegram.',
        'Os documentos de cada relógio' => 'Los documentos de cada reloj',
        'Qualquer arquivo, cada um numa categoria (as que aceitam só algumas famílias recusam as outras), com título, data e descrição. O tipo vem do conteúdo do arquivo; quando o conteúdo diz pouco (texto, binário genérico, zip), da extensão. A família decide como abre: imagem (galeria com visor em tela cheia e apresentação, com a miniatura feita no navegador), vídeo (player, em sequência na ordem escolhida), PDF (visualizador), XML (o resumo da NF-e: emitente, número, série, data, valor, chave e produtos; lido sem baixar nada de fora), o resto para baixar. Inline só o que o navegador mostra sem rodar nada (HTML, SVG e XML sempre como download); atende pedido de pedaço (Range).' => 'Cualquier archivo, cada uno en una categoría (las que aceptan solo algunas familias rechazan las otras), con título, fecha y descripción. El tipo viene del contenido del archivo; cuando el contenido dice poco (texto, binario genérico, zip), de la extensión. La familia decide cómo se abre: imagen (galería con visor a pantalla completa y presentación, con la miniatura hecha en el navegador), vídeo (reproductor, en secuencia en el orden elegido), PDF (visor), XML (el resumen de la NF-e: emisor, número, serie, fecha, valor, clave y productos; leído sin descargar nada de fuera), el resto para descargar. Inline solo lo que el navegador muestra sin ejecutar nada (HTML, SVG y XML siempre como descarga); atiende petición de trozo (Range).',
        'Os arquivos ficam numa pasta fora da publicada (DOCUMENTOS_PASTA), em r<id do relógio>/ com nome aleatório. Limite por arquivo: DOCUMENTOS_LIMITE (padrão 100 MB) e os do PHP e do servidor web.' => 'Los archivos quedan en una carpeta fuera de la publicada (DOCUMENTOS_PASTA), en r<id del reloj>/ con nombre aleatorio. Límite por archivo: DOCUMENTOS_LIMITE (por defecto 100 MB) y los de PHP y del servidor web.',
        'A cópia no banco (documento_parte, pedaços de 4 MB, com o SHA-256): três níveis, e o de cima vale sobre os de baixo. O sistema (DOCUMENTOS_COPIA_BANCO: true todos; false nenhum; ausente, decidem os de baixo), o relógio (copia_banco: todos os dele) e o arquivo (copia_banco: só ele). A tela só mostra a escolha de quem decide. A cópia entra na hora no envio e em editar; pelo relógio, o cron copia aos poucos; quando ninguém mais pede, sai, mas só se o arquivo da pasta confere com ela (o documento nunca fica sem as duas).' => 'La copia en la base de datos (documento_parte, trozos de 4 MB, con el SHA-256): tres niveles, y el de arriba vale sobre los de abajo. El sistema (DOCUMENTOS_COPIA_BANCO: true todos; false ninguno; ausente, deciden los de abajo), el reloj (copia_banco: todos los de él) y el archivo (copia_banco: solo él). La pantalla solo muestra la elección de quien decide. La copia entra en el momento en el envío y en editar; por el reloj, el cron copia poco a poco; cuando ya nadie la pide, sale, pero solo si el archivo de la carpeta coincide con ella (el documento nunca se queda sin las dos).',
        'A manutenção (o cron, a cada minuto, até 256 MB por rodada): o arquivo que sumiu da pasta volta da cópia (conferindo o SHA-256); a cópia pedida que falta é feita; a que ninguém pede sai; a pasta de um relógio que não existe mais sai inteira; o arquivo que não é de nenhum documento sai (só depois de 10 minutos: um envio pode estar no meio). Os perdidos (sem arquivo e sem cópia) são contados à noite.' => 'El mantenimiento (el cron, cada minuto, hasta 256 MB por ronda): el archivo que desapareció de la carpeta vuelve de la copia (comprobando el SHA-256); la copia pedida que falta se hace; la que nadie pide sale; la carpeta de un reloj que ya no existe sale entera; el archivo que no es de ningún documento sale (solo después de 10 minutos: un envío puede estar a medias). Los perdidos (sin archivo y sin copia) se cuentan por la noche.',
        'As estatísticas' => 'Las estadísticas',
        'recurso=estatisticas conta o tempo no pulso de cada relógio em cada dia do período (as sessões do tipo pulso partidas na meia-noite, a aberta até agora; as marcações antigas no pulso contam o dia, sem horas). Dela saem: os dias de uso e as horas de cada relógio, a parte de cada um, a barra (comparada com o mais usado), a tendência (a segunda metade do período contra a primeira: até 20% ou menos de 1 h de diferença é estável; menos de 1 h no total ou período de menos de 14 dias, poucos dados), o uso por dia da semana e por mês (com a média por dia e a barra comparada com o maior) e o resumo. O custo por uso e os dias de uso desde sempre são as fórmulas custo_por_uso e dias_de_uso. A coleção (na coleção e emprestados) é dividida por grupo, marca, ano da compra, situação e cada campo de lista (menos os só dos desejados). Período padrão: os últimos 90 dias; até hoje; no máximo 3661 dias; de=tudo: desde o primeiro uso.' => 'recurso=estatisticas cuenta el tiempo en la muñeca de cada reloj en cada día del período (las sesiones del tipo pulso partidas en la medianoche, la abierta hasta ahora; las marcas antiguas en la muñeca cuentan el día, sin horas). De ahí salen: los días de uso y las horas de cada reloj, la parte de cada uno, la barra (comparada con el más usado), la tendencia (la segunda mitad del período contra la primera: hasta el 20% o menos de 1 h de diferencia es estable; menos de 1 h en total o período de menos de 14 días, pocos datos), el uso por día de la semana y por mes (con la media por día y la barra comparada con el mayor) y el resumen. El costo por uso y los días de uso desde siempre son las fórmulas custo_por_uso y dias_de_uso. La colección (en la colección y prestados) se divide por grupo, marca, año de la compra, situación y cada campo de lista (menos los solo de los deseados). Período por defecto: los últimos 90 días; hasta hoy; como máximo 3661 días; de=tudo: desde el primer uso.',
        'A hora certa' => 'La hora exacta',
        'recurso=hora_certa não usa o banco: a hora do servidor (microtime) no fuso do sistema e em UTC; a letra militar do fuso pelo deslocamento em horas cheias (A a M sem J a leste, N a Y a oeste, Z no UTC; fora da hora cheia, nenhuma); o grupo data-hora DDHHMM + letra + mês em inglês + ano com dois dígitos; o calendário pelo formato de datas (z, L, W, o); o dia juliano = segundos / 86400 + 2440587,5; a lua pela idade no ciclo sinódico médio de 29,530588853 dias a partir da lua nova de 06/01/2000 18:14 UTC (dia juliano 2451550,1), a parte iluminada (1 - cos(2π idade/ciclo)) / 2 e a fase pelos oitavos do ciclo (os limites 1,85; 5,54; 9,23; 12,92; 16,61; 20,30; 23,99; 27,68 dias).' => 'recurso=hora_certa no usa la base de datos: la hora del servidor (microtime) en el huso del sistema y en UTC; la letra militar del huso por el desplazamiento en horas en punto (A a M sin J al este, N a Y al oeste, Z en el UTC; fuera de la hora en punto, ninguna); el grupo fecha-hora DDHHMM + letra + mes en inglés + año con dos dígitos; el calendario por el formato de fechas (z, L, W, o); el día juliano = segundos / 86400 + 2440587,5; la luna por la edad en el ciclo sinódico medio de 29,530588853 días a partir de la luna nueva del 06/01/2000 18:14 UTC (día juliano 2451550,1), la parte iluminada (1 - cos(2π edad/ciclo)) / 2 y la fase por los octavos del ciclo (los límites 1,85; 5,54; 9,23; 12,92; 16,61; 20,30; 23,99; 27,68 días).',
        'As telas' => 'Las pantallas',
        'A especificação completa, tela por tela, está em telas (abaixo): o visual com os valores exatos (cores, letras, controles, componentes, larguras), o menu, e cada página com o endereço, o que ela lê e grava na API, e as partes em ordem com cada tabela, campo, botão e mensagem. Aqui, o resumo.' => 'La especificación completa, pantalla por pantalla, está en telas (abajo): el visual con los valores exactos (colores, letras, controles, componentes, anchuras), el menú, y cada página con la dirección, lo que lee y guarda en la API, y las partes en orden con cada tabla, campo, botón y mensaje. Aquí, el resumen.',
        'Hoje: no alto, o destaque: o relógio do dia ou, com destaque_hoje = pulso, o que está no pulso agora (a API escolhe: destaque.relogio_id) (com o Pôs e o Tirou), "Hoje é dia de" (os avisos com o botão que resolve), os próximos dias com o motivo e o trocar por…, o modo de rodízio (troca ali mesmo), e a tabela da coleção com filtros e ordenação; clicar num relógio abre o painel dele, ao lado da lista ou numa janela flutuante (painel_modo).' => 'Hoy: arriba, el destacado: el reloj del día o, con destaque_hoje = pulso, el que está en la muñeca ahora (la API elige: destaque.relogio_id) (con el Me lo puse y el Me lo quité), "Hoy es día de" (los avisos con el botón que lo resuelve), los próximos días con el motivo y el cambiar por…, el modo de rotación (se cambia allí mismo), y la tabla de la colección con filtros y ordenación; hacer clic en un reloj abre su panel, al lado de la lista o en una ventana flotante (painel_modo).',
        'O painel (e a ficha, a mesma coisa numa página): a cabeça (foto, grupo, nome, marcas), quadros alinhados numa grade (Agora, Previsão, Gasto da bateria, Autonomia, Rodízio, Compra, Documentos, Próximas manutenções), cada um com rótulo e valor em duas colunas; o quadro Marcar (um menu só, "O que você quer marcar?", e embaixo só os campos daquilo); Editar cadastro; o gráfico da carga com as medições; os dados do relógio (o cadastro com a origem de cada valor e o resultado de cada fórmula com a versão); o histórico recente.' => 'El panel (y la ficha, lo mismo en una página): la cabecera (foto, grupo, nombre, marcas), cuadros alineados en una cuadrícula (Ahora, Previsión, Consumo de la batería, Autonomía, Rotación, Compra, Documentos, Próximos mantenimientos), cada uno con rótulo y valor en dos columnas; el cuadro Marcar (un solo menú, "¿Qué quiere marcar?", y debajo solo los campos de aquello); Editar ficha; el gráfico de la carga con las mediciones; los datos del reloj (la ficha con el origen de cada valor y el resultado de cada fórmula con la versión); el historial reciente.',
        'Plano, Histórico, Documentos, Configuração (quadros com uma opção por linha e a barra de salvar presa no pé), Critérios, Grupos, Cadastros, Execuções do cron, Usuários e Ajuda (as seções do README).' => 'Plan, Historial, Documentos, Configuración (cuadros con una opción por línea y la barra de guardar fija al pie), Criterios, Grupos, Definiciones, Ejecuciones del cron, Usuarios y Ayuda (las secciones del README).',
        'Três tamanhos com o mesmo sistema visual: até 900 px (celular e tablet de pé) o menu fica recolhido, as tabelas viram cartões e o relógio abre em tela cheia (o voltar do aparelho fecha); de 901 a 1199 px o painel ao lado desliza por cima, pela direita. A mesma informação em todos os tamanhos: nenhuma coluna, filtro ou dia é escondido por falta de espaço. A tabela dos relógios tem sempre as 12 colunas; quando a tabela inteira não cabe na largura que tem (medida com os dados, com ou sem o painel aberto), cada relógio vira um cartão com os mesmos 12 campos na mesma ordem, cada um com o nome da coluna em cima (2 colunas no celular, 5 no tablet), os títulos viram botões de ordenar e os 11 filtros ficam todos. Campos com letra de 16 px no celular (o iPhone não aproxima a tela).' => 'Tres tamaños con el mismo sistema visual: hasta 900 px (móvil y tableta de pie) el menú queda recogido, las tablas se vuelven tarjetas y el reloj se abre a pantalla completa (el volver del aparato cierra); de 901 a 1199 px el panel al lado se desliza por encima, por la derecha. La misma información en todos los tamaños: ninguna columna, filtro o día se oculta por falta de espacio. La tabla de los relojes tiene siempre las 12 columnas; cuando la tabla entera no cabe en la anchura que tiene (medida con los datos, con o sin el panel abierto), cada reloj se vuelve una tarjeta con los mismos 12 campos en el mismo orden, cada uno con el nombre de la columna arriba (2 columnas en el móvil, 5 en la tableta), los títulos se vuelven botones de ordenar y los 11 filtros se quedan todos. Campos con letra de 16 px en el móvil (el iPhone no acerca la pantalla).',
        'Segurança' => 'Seguridad',
        'Todo pedido da API exige autenticação (o token ou o login do site); as páginas são só o esqueleto, sem dado nenhum, e quem chega sem login vai para o login da API. O cron e os scripts só pela linha de comando. Os arquivos internos (núcleo, banco, configuração, scripts, testes, dados, os que começam com ponto) ficam bloqueados no servidor web (.htaccess e nginx-relogios.conf).' => 'Toda petición de la API exige autenticación (el token o el inicio de sesión del sitio); las páginas son solo el esqueleto, sin ningún dato, y quien llega sin inicio de sesión va al inicio de sesión de la API. El cron y los scripts solo por la línea de comandos. Los archivos internos (núcleo, base de datos, configuración, scripts, pruebas, datos, los que empiezan con punto) quedan bloqueados en el servidor web (.htaccess y nginx-relogios.conf).',
        'SQL sempre com parâmetros; textos escapados no HTML; XML da NF-e lido sem entidades nem rede; arquivos servidos inline só dos tipos seguros; senhas com password_hash; o token comparado em tempo constante.' => 'SQL siempre con parámetros; textos escapados en el HTML; XML de la NF-e leído sin entidades ni red; archivos servidos inline solo de los tipos seguros; contraseñas con password_hash; el token comparado en tiempo constante.',
        'Senhas: só o hash, pelo password_hash do PHP (bcrypt, $2y$<custo>$<sal de 22><resultado de 31>); o login confere com o password_verify (o bcrypt da senha digitada com o sal e o custo do hash). A API entrega o login e o hash de cada usuário (recurso=usuarios: senha_hash, senha_algoritmo, senha_custo) e aceita criar um usuário pelo hash de outro sistema (usuarios/salvar com senha_hash; bcrypt $2y$, $2b$ ou $2a$, ou argon2; o $2b$ guardado como $2y$, o mesmo cálculo). A reescrita tem de conferir pelo mesmo bcrypt, para os usuários migrarem com a mesma senha. Os arquivos dos documentos só pelo recurso=documento.' => 'Contraseñas: solo el hash, por password_hash de PHP (bcrypt, $2y$<coste>$<sal de 22><resultado de 31>); el inicio de sesión comprueba con password_verify (el bcrypt de la contraseña tecleada con la sal y el coste del hash). La API entrega el login y el hash de cada usuario (recurso=usuarios: senha_hash, senha_algoritmo, senha_custo) y acepta crear un usuario por el hash de otro sistema (usuarios/salvar con senha_hash; bcrypt $2y$, $2b$ o $2a$, o argon2; el $2b$ guardado como $2y$, el mismo cálculo). La reescritura tiene que comprobar por el mismo bcrypt, para que los usuarios migren con la misma contraseña. Los archivos de los documentos solo por recurso=documento.',
        'Os testes e a aceitação' => 'Las pruebas y la aceptación',
        'testes/cenario.php faz pela API o que uma pessoa faz (cadastra relógios de cada tipo, lança cordas, cargas, sol, winder e pilha, monta a escala, mexe nos critérios, nos eventos e nas fotos, roda o cron) e tira a fotografia de tudo o que a API devolve; testes/comparar.php compara duas fotografias. Com RELOGIOS_SEMENTE (o sorteio fica previsível), o roteiro rodado em MySQL, PostgreSQL, SQLite e Firebird, num banco recém-instalado, tem de dar as mesmas respostas; e a reescrita, as mesmas da versão atual. testes/paridade.sh faz tudo com um comando (os bancos recriados, a instalação, o usuário, os servidores, o roteiro e a comparação), com o config de teste apontado pela variável de ambiente RELOGIOS_CONFIG (o núcleo carrega o arquivo que ela diz; sem ela, o config.php).' => 'testes/cenario.php hace por la API lo que hace una persona (define relojes de cada tipo, registra cuerdas, cargas, sol, winder y pila, arma la escala, toca los criterios, los eventos y las fotos, ejecuta el cron) y saca la fotografía de todo lo que devuelve la API; testes/comparar.php compara dos fotografías. Con RELOGIOS_SEMENTE (el sorteo queda previsible), el guion ejecutado en MySQL, PostgreSQL, SQLite y Firebird, en una base de datos recién instalada, tiene que dar las mismas respuestas; y la reescritura, las mismas de la versión actual. testes/paridade.sh lo hace todo con un comando (las bases de datos recreadas, la instalación, el usuario, los servidores, el guion y la comparación), con el config de prueba apuntado por la variable de entorno RELOGIOS_CONFIG (el núcleo carga el archivo que ella dice; sin ella, el config.php).',
        'Além disso: nenhuma escrita do roteiro recusada; o dicionário da ajuda explica todos os campos das respostas; as telas sem erro de JavaScript e sem rolagem lateral no celular, no tablet e no computador.' => 'Además: ninguna escritura del guion rechazada; el diccionario de la ayuda explica todos los campos de las respuestas; las pantallas sin error de JavaScript y sin desplazamiento lateral en el móvil, en la tableta y en el ordenador.',
        'A documentação da API tem uma fonte só: o dicionário dos campos da ajuda (recurso=ajuda, campos); o do cabeçalho do api.php é gerado dele (testes/dicionario.php --gravar; sem o --gravar, confere). testes/campos.php confere que todo campo das respostas está explicado. Os dois rodam no testes/paridade.sh.' => 'La documentación de la API tiene una sola fuente: el diccionario de los campos de la ayuda (recurso=ajuda, campos); el de la cabecera de api.php se genera de él (testes/dicionario.php --gravar; sin el --gravar, comprueba). testes/campos.php comprueba que todo campo de las respuestas está explicado. Los dos se ejecutan en testes/paridade.sh.',
        'testes/layout.cjs abre todas as telas (com os quadros recolhidos abertos e cada opção dos menus que mostram partes) num navegador, em 15 tamanhos de 320 a 1920px, e mede o que quebra: a página que rola de lado, o elemento que sai da caixa em que está, a etiqueta partida, o texto cortado, o botão com o texto em duas linhas e o que fica por cima de outro. O esperado: 0 problemas.' => 'testes/layout.cjs abre todas las pantallas (con los cuadros recogidos abiertos y cada opción de los menús que muestran partes) en un navegador, en 15 tamaños de 320 a 1920px, y mide lo que se rompe: la página que se desplaza de lado, el elemento que sale de la caja en la que está, la etiqueta partida, el texto cortado, el botón con el texto en dos líneas y lo que queda por encima de otro. Lo esperado: 0 problemas.',
        'Cada tabela com as colunas (nome, tipo no dialeto do banco em uso, se aceita vazio, o padrão), a chave primária, as chaves estrangeiras (a coluna, a tabela.coluna de referência e o que acontece ao apagar a linha de cima: CASCADE some junto, SET NULL desfaz a ligação), as chaves únicas, os índices e as regras de validação (CHECK). As colunas de texto curto não diferenciam maiúsculas nem acentos. Três referências ficam pelo nome, de propósito: as fórmulas e os critérios citam campos e fórmulas pelo identificador, e canal_aviso.tipo cita o aviso pelo identificador (vale para todas as versões dele).' => 'Cada tabla con las columnas (nombre, tipo en el dialecto de la base de datos en uso, si acepta vacío, el predeterminado), la clave primaria, las claves foráneas (la columna, la tabla.columna de referencia y lo que ocurre al borrar la fila de arriba: CASCADE desaparece junto, SET NULL deshace la relación), las claves únicas, los índices y las reglas de validación (CHECK). Las columnas de texto corto no diferencian mayúsculas ni acentos. Tres referencias quedan por el nombre, a propósito: las fórmulas y los criterios citan campos y fórmulas por el identificador, y canal_aviso.tipo cita el aviso por el identificador (vale para todas sus versiones).',
    ],
];
